{
  "timeline": [
    {
      "headline": "Birth of Jeff Dunham",
      "text": "Jeffrey Douglas Dunham was born on April 18, 1962, in Dallas, Texas, USA.",
      "date": "1962-04-18"
    },
    {
      "headline": "First Television Appearance",
      "text": "In 1976, at the age of 14, Jeff Dunham made his first television appearance on a local Dallas show.",
      "date": "1976"
    },
    {
      "headline": "Graduation from Baylor University",
      "text": "Jeff Dunham graduated from Baylor University in 1986, where he studied communications.",
      "date": "1986"
    },
    {
      "headline": "Debut on The Tonight Show",
      "text": "Jeff Dunham made his debut on The Tonight Show Starring Johnny Carson in 1990, which significantly boosted his career.",
      "date": "1990"
    },
    {
      "headline": "Comedy Central Presents Special",
      "text": "In 2003, Jeff Dunham had his first Comedy Central Presents special, which helped him gain a wider audience.",
      "date": "2003"
    },
    {
      "headline": "Spark of Insanity Tour",
      "text": "Jeff Dunham's Spark of Insanity tour began in 2007 and set the Guinness World Record for 'Most tickets sold for a stand-up comedy tour'.",
      "date": "2007"
    },
    {
      "headline": "The Jeff Dunham Show",
      "text": "In 2009, Jeff Dunham starred in The Jeff Dunham Show, a series that aired on Comedy Central.",
      "date": "2009"
    },
    {
      "headline": "Star on the Hollywood Walk of Fame",
      "text": "Jeff Dunham received a star on the Hollywood Walk of Fame on September 21, 2017.",
      "date": "2017-09-21"
    },
    {
      "headline": "Netflix Specials",
      "text": "Jeff Dunham released two Netflix specials, the first in 2017 titled 'Jeff Dunham: Relative Disaster' and the second in 2019 titled 'Jeff Dunham: Beside Himself'.",
      "date": "2017"
    }
  ]
}

