{
  "timeline": [
    {
      "headline": "Renaming of the Air Force",
      "text": "In 1979, following the Iranian Revolution, the Imperial Iranian Air Force was renamed to the Islamic Republic of Iran Air Force (IRIAF).",
      "date": "1979"
    },
    {
      "headline": "Operation Kaman 99",
      "text": "On September 23, 1980, the IRIAF launched Operation Kaman 99, a massive airstrike against Iraqi airbases in response to the Iraqi invasion of Iran.",
      "date": "1980-09-23"
    },
    {
      "headline": "Operation Sultan 10",
      "text": "In October 1980, the IRIAF conducted Operation Sultan 10, targeting Iraqi military installations and infrastructure.",
      "date": "1980-10"
    },
    {
      "headline": "H-3 Airstrike",
      "text": "On April 4, 1981, the IRIAF executed the H-3 airstrike, a long-range attack on Iraqi airbases near the Jordanian border.",
      "date": "1981-04-04"
    },
    {
      "headline": "Operation Scorch Sword",
      "text": "On September 30, 1980, the IRIAF carried out Operation Scorch Sword, the first attack on a nuclear reactor in history, targeting the Osirak reactor in Iraq.",
      "date": "1980-09-30"
    },
    {
      "headline": "Iran–Iraq War Aerial Combat",
      "text": "Throughout the Iran–Iraq War (1980-1988), the IRIAF was heavily involved in aerial combat, achieving significant success and claiming the second highest number of fighter aces in the region.",
      "date": "1980-1988"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "India's First Cricket World Cup Participation",
      "text": "India participated in the inaugural Cricket World Cup held in England in 1975. This marked India's debut in the Cricket World Cup tournament.",
      "date": "1975"
    },
    {
      "headline": "India Wins First Cricket World Cup",
      "text": "On June 25, 1983, India won its first Cricket World Cup by defeating the West Indies in the final at Lord's, England. This victory was a significant milestone in Indian cricket history.",
      "date": "1983-06-25"
    },
    {
      "headline": "India Co-hosts the Cricket World Cup",
      "text": "India co-hosted the Cricket World Cup in 1987 along with Pakistan. This was the first time the tournament was held outside England.",
      "date": "1987"
    },
    {
      "headline": "India Co-hosts the Cricket World Cup Again",
      "text": "India co-hosted the Cricket World Cup for the second time in 1996, along with Pakistan and Sri Lanka.",
      "date": "1996"
    },
    {
      "headline": "India Wins Second Cricket World Cup",
      "text": "On April 2, 2011, India won its second Cricket World Cup by defeating Sri Lanka in the final held at Wankhede Stadium, Mumbai. This victory made India the third team to win the World Cup more than once.",
      "date": "2011-04-02"
    },
    {
      "headline": "India Co-hosts the Cricket World Cup for the Third Time",
      "text": "India co-hosted the Cricket World Cup in 2011 along with Sri Lanka and Bangladesh. This was the third time India had co-hosted the tournament.",
      "date": "2011"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Trish Stratus",
      "text": "Patricia Anne Stratigeas, known professionally as Trish Stratus, was born on December 18, 1975, in Toronto, Ontario, Canada.",
      "date": "1975-12-18"
    },
    {
      "headline": "Debut in WWE",
      "text": "Trish Stratus made her debut in WWE on March 19, 2000, as a valet for the tag team T & A (Test and Albert).",
      "date": "2000-03-19"
    },
    {
      "headline": "First WWE Women's Championship",
      "text": "Trish Stratus won her first WWE Women's Championship at the Survivor Series event on November 18, 2001.",
      "date": "2001-11-18"
    },
    {
      "headline": "Longest Reign as WWE Women's Champion",
      "text": "Trish Stratus began her longest reign as WWE Women's Champion on January 9, 2005, which lasted 448 days.",
      "date": "2005-01-09"
    },
    {
      "headline": "Retirement Match",
      "text": "Trish Stratus retired from full-time wrestling after winning her seventh WWE Women's Championship at Unforgiven on September 17, 2006.",
      "date": "2006-09-17"
    },
    {
      "headline": "Induction into WWE Hall of Fame",
      "text": "Trish Stratus was inducted into the WWE Hall of Fame on April 6, 2013.",
      "date": "2013-04-06"
    },
    {
      "headline": "Return to WWE for Evolution",
      "text": "Trish Stratus returned to WWE to compete at the first-ever all-women's pay-per-view event, Evolution, on October 28, 2018.",
      "date": "2018-10-28"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "2024 Vermont Republican Presidential Primary",
      "text": "The 2024 Vermont Republican presidential primary was held on March 5, 2024, as part of the Republican Party primaries for the 2024 presidential election. 17 delegates to the 2024 Republican National Convention were allocated on a winner-take-most basis. The contest was held on Super Tuesday alongside primaries in 14 other states.",
      "date": "2024-03-05"
    },
    {
      "headline": "Nikki Haley Wins Vermont Primary",
      "text": "Nikki Haley won the Vermont Republican presidential primary against Donald Trump, making her the first woman to win a state in a Republican presidential primary, and the first nonwhite woman to win a presidential primary of a major party. Haley was awarded nine delegates and Trump was awarded eight delegates.",
      "date": "2024-03-05"
    },
    {
      "headline": "County Victories in Vermont Primary",
      "text": "In the 2024 Vermont Republican presidential primary, Nikki Haley won Chittenden County, Grand Isle County, Lamoille County, Washington County, Addison County, Windsor County, and Windham County. Donald Trump won Franklin County, Orleans County, Essex County, Caledonia County, Orange County, Rutland County, and Bennington County.",
      "date": "2024-03-05"
    }
  ]
}

{
