{
  "timeline": [
    {
      "headline": "Birth of Sarah Huckabee Sanders",
      "text": "Sarah Elizabeth Huckabee was born on August 13, 1982, in Hope, Arkansas.",
      "date": "1982-08-13"
    },
    {
      "headline": "Graduation from Ouachita Baptist University",
      "text": "Sarah Huckabee Sanders graduated from Ouachita Baptist University in Arkadelphia, Arkansas, in 2004 with a Bachelor of Arts degree in political science.",
      "date": "2004"
    },
    {
      "headline": "Role in Mike Huckabee's Presidential Campaign",
      "text": "In 2008, Sarah Huckabee Sanders worked as a field coordinator for her father, Mike Huckabee's, presidential campaign.",
      "date": "2008"
    },
    {
      "headline": "Senior Advisor on Trump's Presidential Campaign",
      "text": "Sarah Huckabee Sanders served as a senior advisor on Donald Trump's 2016 presidential campaign.",
      "date": "2016"
    },
    {
      "headline": "Appointed White House Deputy Press Secretary",
      "text": "In January 2017, Sarah Huckabee Sanders was appointed as the White House Deputy Press Secretary under President Donald Trump.",
      "date": "2017-01"
    },
    {
      "headline": "Becomes White House Press Secretary",
      "text": "On July 21, 2017, Sarah Huckabee Sanders was promoted to White House Press Secretary, becoming the third woman to hold the position.",
      "date": "2017-07-21"
    },
    {
      "headline": "Resignation as White House Press Secretary",
      "text": "Sarah Huckabee Sanders resigned from her position as White House Press Secretary on June 28, 2019.",
      "date": "2019-06-28"
    },
    {
      "headline": "Announces Candidacy for Governor of Arkansas",
      "text": "On January 25, 2021, Sarah Huckabee Sanders announced her candidacy for Governor of Arkansas.",
      "date": "2021-01-25"
    },
    {
      "headline": "Wins Republican Nomination for Governor",
      "text": "Sarah Huckabee Sanders won the Republican nomination for Governor of Arkansas in the 2022 election.",
      "date": "2022"
    },
    {
      "headline": "Elected Governor of Arkansas",
      "text": "Sarah Huckabee Sanders was elected as the 47th Governor of Arkansas on November 8, 2022, defeating Democratic nominee Chris Jones.",
      "date": "2022-11-08"
    },
    {
      "headline": "Inauguration as Governor of Arkansas",
      "text": "Sarah Huckabee Sanders was inaugurated as the 47th Governor of Arkansas on January 10, 2023.",
      "date": "2023-01-10"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Film Release",
      "text": "Gremlins was released in the United States on June 8, 1984. It is a comedy horror film directed by Joe Dante and written by Chris Columbus.",
      "date": "1984-06-08"
    },
    {
      "headline": "Film Setting",
      "text": "The story of Gremlins is set during Christmas Eve in the fictional town of Kingston Falls, where a young man named Billy Peltzer receives a strange creature called a mogwai as a pet.",
      "date": "1984-12-24"
    },
    {
      "headline": "Cultural Impact",
      "text": "Gremlins became a significant cultural reference for mischievous creatures causing malfunctions, drawing on legends from the British Royal Air Force during World War II.",
      "date": "1984"
    },
    {
      "headline": "Box Office Success",
      "text": "Gremlins was a commercial success, grossing over $212 million worldwide against an $11 million budget.",
      "date": "1984"
    },
    {
      "headline": "Critical Reception",
      "text": "Upon its release, Gremlins received positive reviews for its humor, special effects, and performances, particularly Howie Mandel's voice work as Gizmo.",
      "date": "1984"
    }
  ]
}

{
  "timeline": [
