{
  "timeline": [
    {
      "headline": "Founding of Hanoi",
      "text": "Hanoi was founded in 1010 by Emperor Lý Thái Tổ, who moved the capital of Đại Việt to the site of modern-day Hanoi and named it Thăng Long.",
      "date": "1010"
    },
    {
      "headline": "Name Change to Đông Đô",
      "text": "In 1397, the capital was moved to Thanh Hóa, and Thăng Long was renamed Đông Đô.",
      "date": "1397"
    },
    {
      "headline": "Name Change to Đông Quan",
      "text": "In 1408, during the Ming Dynasty's occupation of Vietnam, the city was renamed Đông Quan.",
      "date": "1408"
    },
    {
      "headline": "Restoration and Name Change to Đông Kinh",
      "text": "In 1428, after the Vietnamese regained independence, the city was renamed Đông Kinh.",
      "date": "1428"
    },
    {
      "headline": "Name Change to Thăng Long",
      "text": "In 1802, when the Nguyễn Dynasty moved the capital to Huế, the city was renamed Thăng Long again.",
      "date": "1802"
    },
    {
      "headline": "Renamed to Hanoi",
      "text": "In 1831, Emperor Minh Mạng officially renamed the city Hanoi.",
      "date": "1831"
    },
    {
      "headline": "French Colonial Period",
      "text": "Hanoi became the capital of French Indochina in 1902 during the French colonial period.",
      "date": "1902"
    },
    {
      "headline": "Japanese Occupation",
      "text": "During World War II, Hanoi was occupied by Japanese forces from 1940 to 1945.",
      "date": "1940"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On September 2, 1945, Ho Chi Minh declared Vietnam's independence from French colonial rule in Ba Đình Square, Hanoi.",
      "date": "1945-09-02"
    },
    {
      "headline": "First Indochina War",
      "text": "Hanoi was a major center during the First Indochina War, which lasted from 1946 to 1954.",
      "date": "1946"
    },
    {
      "headline": "Becomes Capital of North Vietnam",
      "text": "In 1954, after the Geneva Accords, Hanoi became the capital of North Vietnam.",
      "date": "1954"
    },
    {
      "headline": "Vietnam War",
      "text": "During the Vietnam War (1955-1975), Hanoi was the capital of North Vietnam and was heavily bombed by the United States.",
      "date": "1955"
    },
    {
      "headline": "Reunification of Vietnam",
      "text": "In 1976, following the end of the Vietnam War, Hanoi became the capital of the reunified Socialist Republic of Vietnam.",
      "date": "1976"
    },
    {
      "headline": "UNESCO Recognition",
      "text": "In 2010, Hanoi celebrated its 1000th anniversary and was recognized by UNESCO for its cultural heritage.",
      "date": "2010"
    }
  ]
}

