{
  "timeline": [
    {
      "headline": "Early Human Habitation",
      "text": "Java has been inhabited by humans since prehistoric times. The earliest evidence of human habitation is the discovery of the Java Man, a Homo erectus fossil, which dates back to approximately 1.5 million years ago.",
      "date": "-1500000"
    },
    {
      "headline": "Arrival of Austronesian Peoples",
      "text": "Around 2000 BCE, Austronesian peoples began migrating to Java, bringing with them agriculture and new technologies.",
      "date": "-2000"
    },
    {
      "headline": "Indian Influence and Hindu-Buddhist Kingdoms",
      "text": "Starting around the 4th century CE, Indian traders and scholars brought Hinduism and Buddhism to Java, leading to the establishment of Hindu-Buddhist kingdoms such as Tarumanagara and later, the powerful Mataram Kingdom.",
      "date": "0400"
    },
    {
      "headline": "Majapahit Empire",
      "text": "The Majapahit Empire, which emerged in the late 13th century, became one of the greatest empires in Southeast Asian history, reaching its peak in the 14th century under the rule of Hayam Wuruk.",
      "date": "1293"
    },
    {
      "headline": "Spread of Islam",
      "text": "Islam began spreading in Java in the 15th century, gradually replacing Hinduism and Buddhism as the dominant religion by the 16th century.",
      "date": "1400"
    },
    {
      "headline": "Dutch Colonization",
      "text": "In the early 17th century, the Dutch East India Company established a foothold in Java, eventually leading to Dutch colonial rule over the island.",
      "date": "1602"
    },
    {
      "headline": "Java War",
      "text": "The Java War (1825-1830) was a major rebellion against Dutch colonial rule led by Prince Diponegoro, which ultimately ended in a Dutch victory.",
      "date": "1825"
    },
    {
      "headline": "Indonesian National Revolution",
      "text": "Following World War II, Java was a central battleground in the Indonesian National Revolution (1945-1949) against Dutch attempts to re-establish colonial control, leading to Indonesia's independence.",
      "date": "1945"
    },
    {
      "headline": "Jakarta Becomes Capital",
      "text": "Jakarta, located on the northwestern coast of Java, was established as the capital of Indonesia following the country's independence.",
      "date": "1949"
    },
    {
      "headline": "Java's Population Growth",
      "text": "By the 21st century, Java had become the world's most populous island, with a population of over 153.8 million people, accounting for approximately 54% of Indonesia's total population.",
      "date": "2020"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Implementation of Operation Wetback",
      "text": "Operation Wetback was implemented in June 1954 by U.S. Attorney General Herbert Brownell. The initiative was created by Joseph Swing, a retired United States Army lieutenant general and head of the United States Immigration and Naturalization Service (INS).",
      "date": "1954-06"
    },
    {
      "headline": "Military-style Tactics Used",
      "text": "The operation used military-style tactics to remove Mexican immigrants, some of whom were American citizens, from the United States. This was part of a broader effort to address illegal immigration.",
      "date": "1954-06"
    },
    {
      "headline": "Impact on Mexican Immigrants",
      "text": "Though millions of Mexicans had legally entered the country through joint immigration programs in the first half of the 20th century, Operation Wetback was designed to send them to Mexico. This included some naturalized citizens who were once native.",
      "date": "1954-06"
    }
  ]
}

