{
  "timeline": [
    {
      "headline": "Establishment of Vijayanagara Empire",
      "text": "The Vijayanagara Empire was established in 1336 by the brothers Harihara I and Bukka Raya I of the Sangama dynasty.",
      "date": "1336"
    },
    {
      "headline": "Reign of Harihara I",
      "text": "Harihara I ruled the Vijayanagara Empire from 1336 until his death in 1356.",
      "date": "1336"
    },
    {
      "headline": "Reign of Bukka Raya I",
      "text": "Bukka Raya I succeeded Harihara I and ruled from 1356 to 1377. He expanded the empire and strengthened its administration.",
      "date": "1356"
    },
    {
      "headline": "Reign of Harihara II",
      "text": "Harihara II, the son of Bukka Raya I, ruled from 1377 to 1404. His reign marked the consolidation of the empire's power.",
      "date": "1377"
    },
    {
      "headline": "Reign of Deva Raya I",
      "text": "Deva Raya I ruled from 1406 to 1422. He is known for his military campaigns and patronage of art and architecture.",
      "date": "1406"
    },
    {
      "headline": "Reign of Deva Raya II",
      "text": "Deva Raya II, known as the greatest ruler of the Sangama dynasty, ruled from 1424 to 1446. His reign saw the peak of the empire's prosperity and cultural achievements.",
      "date": "1424"
    },
    {
      "headline": "Reign of Krishnadevaraya",
      "text": "Krishnadevaraya, a ruler from the Tuluva dynasty, ruled from 1509 to 1529. His reign is considered the golden age of the Vijayanagara Empire.",
      "date": "1509"
    },
    {
      "headline": "Battle of Talikota",
      "text": "The Battle of Talikota took place in 1565, leading to a decisive defeat for the Vijayanagara Empire against the Deccan Sultanates, marking the beginning of the empire's decline.",
      "date": "1565"
    },
    {
      "headline": "End of Vijayanagara Empire",
      "text": "The Vijayanagara Empire effectively came to an end in 1646, although it had been in decline since the Battle of Talikota.",
      "date": "1646"
    }
  ]
}

