{
  "timeline": [
    {
      "headline": "Invention of the Piano",
      "text": "The piano was invented by Bartolomeo Cristofori in Florence, Italy. Cristofori was dissatisfied with the lack of control over the volume level of the harpsichord and created the first piano, known as the 'gravicembalo col piano e forte', around 1700.",
      "date": "1700"
    },
    {
      "headline": "First Known Public Performance",
      "text": "The first known public performance on a piano was given by Lodovico Giustini in Florence, Italy, in 1732. Giustini was one of the first composers to write music specifically for the piano.",
      "date": "1732"
    },
    {
      "headline": "Development of the Modern Piano",
      "text": "By the late 18th century, the piano had evolved into an instrument similar to the modern piano, with a range of five octaves. Innovations by builders like Johann Andreas Stein and Sébastien Érard contributed to its development.",
      "date": "1780"
    },
    {
      "headline": "Introduction of the Iron Frame",
      "text": "In 1825, Alpheus Babcock of Boston, USA, introduced the one-piece cast iron frame for the piano, which allowed for greater string tension and a more powerful sound.",
      "date": "1825"
    },
    {
      "headline": "Standardization of the 88-Key Piano",
      "text": "By the late 19th century, the 88-key piano became the standard, with a range of seven octaves plus a minor third, from A0 to C8. This standardization was largely due to the influence of piano manufacturers like Steinway & Sons.",
      "date": "1880"
    },
    {
      "headline": "Introduction of the Upright Piano",
      "text": "The upright piano, which takes up less space than a grand piano, became popular in the late 19th century, making the piano more accessible to the general public.",
      "date": "1880"
    },
    {
      "headline": "Invention of the Player Piano",
      "text": "The player piano, which uses a pneumatic mechanism to play pre-programmed music rolls, was developed in the early 20th century, with the first successful models appearing around 1900.",
      "date": "1900"
    },
    {
      "headline": "Introduction of the Electric Piano",
      "text": "The electric piano, which uses electronic amplification to produce sound, was introduced in the mid-20th century, with models like the Wurlitzer and Rhodes becoming popular in the 1950s and 1960s.",
      "date": "1950"
    },
    {
      "headline": "Development of the Digital Piano",
      "text": "The digital piano, which simulates the sound and feel of an acoustic piano using digital technology, became widely available in the late 20th century, offering a portable and versatile alternative to traditional pianos.",
      "date": "1980"
    }
  ]
}

