{
  "timeline": [
    {
      "headline": "Huronian Glaciation",
      "text": "The Huronian glaciation occurred approximately 2.4 to 2.1 billion years ago. It is one of the earliest known ice ages and is believed to have been triggered by the Great Oxygenation Event, which significantly altered Earth's atmosphere.",
      "date": "-2400000000"
    },
    {
      "headline": "Cryogenian Period",
      "text": "The Cryogenian Period, lasting from about 720 to 635 million years ago, is known for the most severe ice ages in Earth's history, including the Sturtian and Marinoan glaciations, which may have covered the planet in ice, a hypothesis known as 'Snowball Earth'.",
      "date": "-0720000000"
    },
    {
      "headline": "Andean-Saharan Glaciation",
      "text": "The Andean-Saharan glaciation occurred approximately 450 to 420 million years ago during the Late Ordovician to Early Silurian periods. It is associated with a major extinction event.",
      "date": "-0450000000"
    },
    {
      "headline": "Karoo Ice Age",
      "text": "The Karoo Ice Age took place from about 360 to 260 million years ago during the late Paleozoic Era. It is associated with the assembly of the supercontinent Pangaea and significant changes in Earth's climate and ecosystems.",
      "date": "-0360000000"
    },
    {
      "headline": "Quaternary Glaciation",
      "text": "The Quaternary glaciation began around 2.58 million years ago and continues to the present day. It is characterized by repeated glacial and interglacial cycles, with the most recent glacial period ending approximately 11,700 years ago.",
      "date": "-0000025800"
    },
    {
      "headline": "Last Glacial Maximum",
      "text": "The Last Glacial Maximum occurred around 26,500 years ago, when ice sheets were at their greatest extent during the last glacial period of the Quaternary glaciation.",
      "date": "-0000026500"
    },
    {
      "headline": "Holocene Epoch",
      "text": "The Holocene Epoch began approximately 11,700 years ago, marking the end of the last glacial period and the start of the current interglacial period, characterized by a relatively stable climate and the development of human civilizations.",
      "date": "-0000011700"
    }
  ]
}

