{
  "timeline": [
    {
      "headline": "Introduction of Moore's Law",
      "text": "Moore's Law was introduced by Gordon E. Moore, co-founder of Intel and Fairchild Semiconductor, in a paper published on April 19, 1965. He observed that the number of transistors on a microchip doubles approximately every two years, though the cost of computers is halved.",
      "date": "1965-04-19"
    },
    {
      "headline": "Moore's Law Revised",
      "text": "In 1975, Gordon Moore revised his prediction to a doubling of transistors approximately every two years, rather than every year as initially stated.",
      "date": "1975"
    },
    {
      "headline": "Impact on Semiconductor Industry",
      "text": "Throughout the 1970s and 1980s, Moore's Law guided the semiconductor industry, influencing the long-term planning and setting targets for research and development.",
      "date": "1970-1989"
    },
    {
      "headline": "Intel's Microprocessor Development",
      "text": "Intel, co-founded by Moore, consistently followed Moore's Law in its microprocessor development, releasing new generations of processors that adhered to the doubling of transistors.",
      "date": "1971-1990"
    },
    {
      "headline": "Challenges to Moore's Law",
      "text": "By the late 1990s and early 2000s, physical limitations began to challenge the continuation of Moore's Law, as transistors approached the size of atoms.",
      "date": "1990-2000"
    },
    {
      "headline": "Continued Relevance",
      "text": "Despite challenges, Moore's Law continued to be a driving force in the technology industry, with companies finding innovative ways to maintain the pace of advancement.",
      "date": "2000-2020"
    },
    {
      "headline": "Moore's Law in the 21st Century",
      "text": "In the 21st century, Moore's Law has been considered more of a guiding principle than a strict rule, as advancements in technology have continued at a rapid pace, though not always strictly adhering to the two-year doubling period.",
      "date": "2000-2023"
    }
  ]
}

