    {
      "headline": "Establishment of Cognac Houses",
      "text": "During the 18th century, several Cognac houses were established, including Martell in 1715 and Rémy Martin in 1724, which contributed to the growth of the Cognac industry.",
      "date": "1700"
    },
    {
      "headline": "Phylloxera Crisis",
      "text": "In the late 19th century, the Cognac region was devastated by the phylloxera epidemic, which destroyed many vineyards. This crisis led to the replanting of vines with phylloxera-resistant rootstock.",
      "date": "1870"
    },
    {
      "headline": "Creation of the Cognac Appellation d'Origine Contrôlée (AOC)",
      "text": "In 1936, Cognac was granted Appellation d'Origine Contrôlée (AOC) status, which established strict regulations to ensure the quality and authenticity of Cognac.",
      "date": "1936"
    },
    {
      "headline": "Introduction of the VSOP Classification",
      "text": "The VSOP (Very Superior Old Pale) classification was introduced in the early 20th century to denote Cognac that has been aged for at least four years.",
      "date": "1900"
    }
  ]
}

