{
  "timeline": [
    {
      "headline": "Introduction of the Yen",
      "text": "The yen was introduced by the Meiji government in an Act signed on May 10, 1871. The new currency was gradually adopted by the government during the early years of the Meiji era.",
      "date": "1871-05-10"
    },
    {
      "headline": "Adoption of the Gold Standard",
      "text": "In 1897, Japan adopted the gold standard, pegging the yen to gold. This move was part of Japan's efforts to modernize its economy and integrate with the global financial system.",
      "date": "1897"
    },
    {
      "headline": "Suspension of the Gold Standard",
      "text": "The gold standard was suspended in 1917 due to the economic strains of World War I, leading to inflation and economic instability.",
      "date": "1917"
    },
    {
      "headline": "Return to the Gold Standard",
      "text": "Japan returned to the gold standard in 1930, but the Great Depression forced the country to abandon it again in 1931.",
      "date": "1930"
    },
    {
      "headline": "Abandonment of the Gold Standard",
      "text": "In 1931, Japan permanently abandoned the gold standard due to the global economic crisis of the Great Depression.",
      "date": "1931"
    },
    {
      "headline": "Post-War Economic Reforms",
      "text": "After World War II, the yen was pegged to the US dollar at a rate of 360 yen per dollar as part of the Bretton Woods system, which lasted until 1971.",
      "date": "1949"
    },
    {
      "headline": "Floating Exchange Rate",
      "text": "In 1973, Japan adopted a floating exchange rate system, allowing the yen's value to be determined by the foreign exchange market.",
      "date": "1973"
    },
    {
      "headline": "Plaza Accord",
      "text": "In 1985, the Plaza Accord was signed, leading to a significant appreciation of the yen against the US dollar, aimed at correcting trade imbalances.",
      "date": "1985"
    },
    {
      "headline": "Asian Financial Crisis",
      "text": "During the Asian financial crisis of 1997, the yen experienced significant volatility, impacting Japan's economy and financial markets.",
      "date": "1997"
    },
    {
      "headline": "Introduction of Quantitative Easing",
      "text": "In the early 2000s, the Bank of Japan introduced quantitative easing to combat deflation and stimulate the economy.",
      "date": "2001"
    },
    {
      "headline": "Abenomics",
      "text": "In 2012, Prime Minister Shinzo Abe introduced 'Abenomics', a series of economic policies including aggressive monetary easing to revive Japan's economy.",
      "date": "2012"
    }
  ]
}

