{
  "timeline": [
    {
      "headline": "Development of SQL",
      "text": "SQL was developed at IBM by Donald D. Chamberlin and Raymond F. Boyce in the early 1970s. It was initially called SEQUEL (Structured English Query Language) and was designed to manipulate and retrieve data stored in IBM's original relational database management system, System R.",
      "date": "1970"
    },
    {
      "headline": "Renaming to SQL",
      "text": "The language was renamed to SQL (Structured Query Language) due to trademark issues with the name 'SEQUEL'.",
      "date": "1974"
    },
    {
      "headline": "First Commercial SQL Database",
      "text": "In 1979, Relational Software, Inc. (now Oracle Corporation) released the first commercially available implementation of SQL, known as Oracle V2.",
      "date": "1979"
    },
    {
      "headline": "SQL Standardization",
      "text": "In 1986, SQL became a standard of the American National Standards Institute (ANSI), and in 1987, of the International Organization for Standardization (ISO).",
      "date": "1986"
    },
    {
      "headline": "SQL-92 Standard",
      "text": "The SQL-92 standard was released, which included significant enhancements to the language, such as support for more complex queries and additional data types.",
      "date": "1992"
    },
    {
      "headline": "SQL:1999 Standard",
      "text": "The SQL:1999 standard introduced features such as triggers, procedural language capabilities, and support for object-oriented data management.",
      "date": "1999"
    },
    {
      "headline": "SQL:2003 Standard",
      "text": "The SQL:2003 standard added XML-related features, window functions, and the ability to generate sequences.",
      "date": "2003"
    },
    {
      "headline": "SQL:2008 Standard",
      "text": "The SQL:2008 standard introduced features like the MERGE statement, additional data types, and enhanced support for large objects.",
      "date": "2008"
    },
    {
      "headline": "SQL:2011 Standard",
      "text": "The SQL:2011 standard added features for temporal databases, allowing for the management of historical data.",
      "date": "2011"
    },
    {
      "headline": "SQL:2016 Standard",
      "text": "The SQL:2016 standard introduced JSON support, allowing for the integration of SQL with JSON data.",
      "date": "2016"
    }
  ]
}

