    {
      "headline": "Second British Capture",
      "text": "In 1793, during the French Revolutionary Wars, Pondicherry was captured again by the British.",
      "date": "1793"
    },
    {
      "headline": "Return to French Control Again",
      "text": "Pondicherry was restored to France in 1814 after the Treaty of Paris.",
      "date": "1814"
    },
    {
      "headline": "De facto Transfer to India",
      "text": "On November 1, 1954, Pondicherry was transferred to the Indian Union de facto.",
