    {
      "headline": "Elijah's First Appearance",
      "text": "Elijah the Tishbite, from Tishbe in Gilead, appears suddenly in the biblical narrative, confronting King Ahab of Israel. He prophesies a drought as punishment for the worship of Baal. This event is traditionally dated to the 9th century BCE.",
      "date": "-0850"
    },
    {
      "headline": "Miracle of the Widow's Son",
      "text": "During the drought, Elijah stays with a widow in Zarephath. He performs a miracle by ensuring her supply of flour and oil does not run out and later revives her son from death. This event is part of the narrative in the Books of Kings.",
      "date": "-0850"
    },
    {
      "headline": "Contest on Mount Carmel",
      "text": "Elijah challenges the prophets of Baal to a contest on Mount Carmel to prove whose deity is real. God answers Elijah's prayers by sending fire from heaven, consuming the sacrifice. This event leads to the slaughter of the prophets of Baal.",
      "date": "-0850"
    },
    {
      "headline": "Elijah's Flight to Mount Horeb",
      "text": "After Queen Jezebel threatens his life, Elijah flees to Mount Horeb (Sinai), where he experiences a theophany. God speaks to him in a 'still small voice' and gives him further instructions.",
      "date": "-0850"
    },
    {
      "headline": "Anointing of Elisha",
      "text": "Elijah is instructed by God to anoint Elisha as his successor. Elisha becomes his disciple and accompanies him until Elijah's departure.",
      "date": "-0850"
    },
    {
      "headline": "Elijah's Ascension to Heaven",
      "text": "Elijah is taken up to heaven in a whirlwind by a chariot of fire, witnessed by Elisha. This event marks the end of Elijah's earthly ministry.",
      "date": "-0850"
    }
  ]
}

