{
  "timeline": [
    {
      "headline": "Invention of Zyklon B",
      "text": "Zyklon B was invented in the early 1920s in Germany as a pesticide. It consisted of hydrogen cyanide, a cautionary eye irritant, and an adsorbent such as diatomaceous earth.",
      "date": "1920"
    },
    {
      "headline": "Patent and Commercial Use",
      "text": "Zyklon B was patented and began to be used commercially as a pesticide for fumigating ships, buildings, and warehouses.",
      "date": "1920s"
    },
    {
      "headline": "Nazi Germany's Use of Zyklon B",
      "text": "During World War II, Nazi Germany began using Zyklon B in extermination camps to murder approximately 1.1 million people, primarily at Auschwitz-Birkenau and Majdanek.",
      "date": "1941"
    },
    {
      "headline": "End of World War II and the Holocaust",
      "text": "The use of Zyklon B in extermination camps ceased with the end of World War II and the liberation of the camps by Allied forces.",
      "date": "1945"
    },
    {
      "headline": "Nuremberg Trials",
      "text": "During the Nuremberg Trials, the use of Zyklon B in the Holocaust was a significant point of evidence against Nazi war criminals.",
      "date": "1945-1946"
    }
  ]
}

