{
  "timeline": [
    {
      "headline": "Construction Begins",
      "text": "Construction of the Brooklyn Bridge began in 1869. The bridge was designed by John A. Roebling, who died before construction began, and was completed by his son, Washington Roebling.",
      "date": "1869"
    },
    {
      "headline": "Caisson Construction",
      "text": "In 1870, the construction of the caissons, which are watertight structures used to work on the foundations of the bridge, began. This was a significant engineering challenge.",
      "date": "1870"
    },
    {
      "headline": "Washington Roebling Takes Over",
      "text": "After John A. Roebling's death in 1869, his son Washington Roebling took over the project. However, in 1872, Washington Roebling became bedridden due to decompression sickness, also known as 'the bends', but continued to oversee the project with the help of his wife, Emily Warren Roebling.",
      "date": "1872"
    },
    {
      "headline": "Completion of Towers",
      "text": "By 1875, the towers of the Brooklyn Bridge were completed. These towers were a critical component of the bridge's structure.",
      "date": "1875"
    },
    {
      "headline": "Cable Spinning",
      "text": "The spinning of the cables, a crucial phase of the construction, began in 1876. The cables were made from steel wire and were an innovative feature at the time.",
      "date": "1876"
    },
    {
      "headline": "Bridge Opens",
      "text": "The Brooklyn Bridge was officially opened on May 24, 1883. It was the first fixed crossing of the East River and was the longest suspension bridge in the world at the time of its opening.",
      "date": "1883-05-24"
    },
    {
      "headline": "Renaming of the Bridge",
      "text": "In 1915, the bridge was officially renamed the Brooklyn Bridge. It was previously known as the New York and Brooklyn Bridge or the East River Bridge.",
      "date": "1915"
    }
  ]
}

