    {
      "headline": "Creation of UTF-8",
      "text": "UTF-8 was created by Ken Thompson and Rob Pike. It was designed to be backward compatible with ASCII and to avoid the complications of endianness and byte order marks. The design was first presented in 1992.",
      "date": "1992"
    },
    {
      "headline": "UTF-8 Standardized by ISO",
      "text": "UTF-8 was standardized by the International Organization for Standardization (ISO) as part of ISO/IEC 10646 in 1993.",
      "date": "1993"
    },
    {
      "headline": "RFC 2279 Published",
      "text": "In January 1998, UTF-8 was described in RFC 2279, which was later obsoleted by RFC 3629.",
      "date": "1998-01"
    },
    {
      "headline": "RFC 3629 Published",
      "text": "In November 2003, RFC 3629 was published, updating the definition of UTF-8 and limiting the range of code points to U+0000 to U+10FFFF, in line with the Unicode Standard.",
      "date": "2003-11"
    },
    {
      "headline": "UTF-8 Dominates the Web",
      "text": "By 2008, UTF-8 became the most common encoding for the World Wide Web, surpassing ASCII and other encodings.",
      "date": "2008"
    },
    {
      "headline": "UTF-8 Becomes the Default Encoding",
      "text": "In 2012, UTF-8 was adopted as the default character encoding for many programming languages and platforms, including HTML5 and Python 3.",
      "date": "2012"
    }
  ]
}

