      "headline": "Birth of Stephen of Blois",
      "text": "Stephen of Blois was born in the County of Blois, France, around the year 1096.",
      "date": "1096"
    },
    {
      "headline": "Marriage to Matilda of Boulogne",
      "text": "In 1125, Stephen married Matilda of Boulogne, becoming Count of Boulogne jure uxoris.",
      "date": "1125"
