    {
      "headline": "Accession to the English Throne",
      "text": "Stephen was crowned King of England on 22 December 1135, following the death of his uncle, King Henry I.",
      "date": "1135-12-22"
    },
    {
      "headline": "Duke of Normandy",
      "text": "Stephen became Duke of Normandy in 1135, a title he held until 1144.",
      "date": "1135"
    },
    {
      "headline": "The Anarchy Begins",
      "text": "The Anarchy, a civil war between Stephen and his cousin Empress Matilda, began in 1139 when Matilda invaded England.",
      "date": "1139"
    },
    {
      "headline": "Battle of Lincoln",
      "text": "On 2 February 1141, Stephen was captured at the Battle of Lincoln by forces loyal to Empress Matilda.",
      "date": "1141-02-02"
    },
    {
      "headline": "Release from Captivity",
      "text": "Stephen was released from captivity later in 1141, after a prisoner exchange.",
      "date": "1141"
    },
    {
      "headline": "Loss of Normandy",
      "text": "In 1144, Stephen lost control of Normandy to Geoffrey Plantagenet, the husband of Empress Matilda.",
      "date": "1144"
    },
    {
      "headline": "Treaty of Wallingford",
      "text": "In 1153, Stephen agreed to the Treaty of Wallingford, recognizing Matilda's son, Henry, as his heir.",
      "date": "1153"
    },
    {
      "headline": "Death of Stephen",
      "text": "Stephen died on 25 October 1154 in Dover, Kent, England. He was succeeded by Henry II, the first of the Angevin kings.",
      "date": "1154-10-25"
    }
  ]
}

