{
  "timeline": [
    {
      "headline": "Birth of Louis Pasteur",
      "text": "Louis Pasteur was born on December 27, 1822, in Dole, France.",
      "date": "1822-12-27"
    },
    {
      "headline": "Graduation from École Normale Supérieure",
      "text": "In 1847, Pasteur earned his Doctor of Science degree from the École Normale Supérieure in Paris.",
      "date": "1847"
    },
    {
      "headline": "Discovery of Molecular Asymmetry",
      "text": "In 1848, Pasteur discovered that molecules could exist in mirror-image forms, laying the foundation for the field of stereochemistry.",
      "date": "1848"
    },
    {
      "headline": "Appointment at University of Strasbourg",
      "text": "In 1849, Pasteur was appointed as a professor of chemistry at the University of Strasbourg.",
      "date": "1849"
    },
    {
      "headline": "Marriage to Marie Laurent",
      "text": "On May 29, 1849, Louis Pasteur married Marie Laurent, the daughter of the university's rector.",
      "date": "1849-05-29"
    },
    {
      "headline": "Discovery of Fermentation Process",
      "text": "In 1857, Pasteur discovered that fermentation is caused by the growth of microorganisms, which led to the development of the germ theory of disease.",
      "date": "1857"
    },
    {
      "headline": "Pasteurization Process Developed",
      "text": "In 1864, Pasteur developed the process of pasteurization, which involves heating liquids to kill harmful bacteria.",
      "date": "1864"
    },
    {
      "headline": "Anthrax Vaccine Development",
      "text": "In 1881, Pasteur developed the first vaccine for anthrax, demonstrating its effectiveness in a public experiment.",
      "date": "1881"
    },
    {
      "headline": "Rabies Vaccine Development",
      "text": "In 1885, Pasteur successfully developed a vaccine for rabies, administering it to Joseph Meister, a young boy who had been bitten by a rabid dog.",
      "date": "1885"
    },
    {
      "headline": "Founding of the Pasteur Institute",
      "text": "In 1887, Pasteur founded the Pasteur Institute in Paris, which became a leading center for research in microbiology.",
      "date": "1887"
    },
    {
      "headline": "Death of Louis Pasteur",
      "text": "Louis Pasteur died on September 28, 1895, in Marnes-la-Coquette, France.",
      "date": "1895-09-28"
    }
  ]
}

