{
  "timeline": [
    {
      "headline": "Earliest Recorded Witchcraft",
      "text": "The earliest recorded mention of witchcraft dates back to ancient Mesopotamia, around 2000 BCE. The Code of Hammurabi, a Babylonian legal text, includes laws against witchcraft.",
      "date": "-2000"
    },
    {
      "headline": "Witchcraft in Ancient Greece",
      "text": "In ancient Greece, witchcraft was associated with figures like Circe and Medea, who were depicted as powerful sorceresses in Greek mythology. These stories date back to around 700 BCE.",
      "date": "-0700"
    },
    {
      "headline": "Roman Laws Against Witchcraft",
      "text": "In 186 BCE, the Roman Senate issued the Senatus consultum de Bacchanalibus, which restricted the Bacchanalia and included measures against witchcraft.",
      "date": "-0186"
    },
    {
      "headline": "Witchcraft in the Middle Ages",
      "text": "During the Middle Ages, witchcraft was often associated with heresy and was persecuted by the Church. The first major witch hunts began in the 15th century.",
      "date": "1400"
    },
    {
      "headline": "Publication of the Malleus Maleficarum",
      "text": "In 1487, the Malleus Maleficarum, a treatise on witchcraft, was published by Heinrich Kramer and Jacob Sprenger. It became a key text in the witch hunts of the early modern period.",
      "date": "1487"
    },
    {
      "headline": "Witch Trials in Europe",
      "text": "The period between 1580 and 1630 saw the height of the European witch trials, with tens of thousands of people, mostly women, executed for witchcraft.",
      "date": "1580"
    },
    {
      "headline": "Salem Witch Trials",
      "text": "In 1692, the Salem witch trials took place in colonial Massachusetts, resulting in the execution of 20 people and the imprisonment of many others.",
      "date": "1692"
    },
    {
      "headline": "End of Witch Hunts in Europe",
      "text": "By the late 18th century, the witch hunts in Europe had largely ended, with the last known execution for witchcraft occurring in Switzerland in 1782.",
      "date": "1782"
    },
    {
      "headline": "Modern Witchcraft Movements",
      "text": "In the 20th century, modern witchcraft movements such as Wicca emerged, focusing on nature worship and the revival of ancient pagan traditions.",
      "date": "1900"
    }
  ]
}

