  "timeline": [
    {
      "headline": "Origin of Tea",
      "text": "Tea is believed to have originated in the borderlands of southwestern China and northern Myanmar. The earliest credible record of tea drinking dates back to the 3rd century AD.",
      "date": "0200"
    },
    {
      "headline": "Tea in Chinese Culture",
      "text": "During the Tang dynasty (618–907), tea became a popular drink in China. It was during this period that tea culture began to flourish.",
      "date": "0618"
    },
    {
      "headline": "Tea Reaches Japan",
      "text": "Tea was introduced to Japan by Buddhist monks in the early 9th century, who brought tea seeds from China.",
      "date": "0800"
    },
    {
      "headline": "The Classic of Tea",
      "text": "In 760, Lu Yu wrote 'The Classic of Tea' (Cha Jing), the first known monograph on tea, which described the cultivation and preparation of tea.",
      "date": "0760"
    },
    {
      "headline": "Tea in the Song Dynasty",
      "text": "During the Song dynasty (960–1279), tea drinking became a highly refined art form, and the practice of tea ceremonies began.",
      "date": "0960"
    },
    {
      "headline": "Tea Reaches Europe",
      "text": "Tea was introduced to Europe by Portuguese priests and merchants in the 16th century. The first recorded shipment of tea by a European nation was in 1607 by the Dutch.",
      "date": "1607"
    },
    {
      "headline": "Tea in England",
      "text": "Tea became popular in England in the 17th century, with the first advertisement for tea appearing in a London newspaper in 1658.",
      "date": "1658"
    },
    {
      "headline": "Boston Tea Party",
      "text": "On December 16, 1773, American colonists protested against British taxation by dumping 342 chests of tea into Boston Harbor, an event known as the Boston Tea Party.",
      "date": "1773-12-16"
    },
    {
      "headline": "Tea in the British Empire",
      "text": "In the 19th century, the British Empire established tea plantations in India and Ceylon (now Sri Lanka) to break the Chinese monopoly on tea.",
      "date": "1800"
    },
    {
      "headline": "Introduction of Tea Bags",
      "text": "Tea bags were invented in the early 20th century, with the first patent for a tea bag machine filed in 1903.",
      "date": "1903"
    }
  ]
}

