    {
      "headline": "Patriarchate of Mar Aba I",
      "text": "Mar Aba I served as Patriarch from 540 to 552 and was instrumental in reforming the church and strengthening its structure.",
      "date": "0540"
    },
    {
      "headline": "Expansion into Asia",
      "text": "During the 7th and 8th centuries, the Church of the East expanded significantly into Central Asia, China, and India, establishing a vast network of dioceses.",
      "date": "0700"
    },
    {
      "headline": "Decline under Mongol Rule",
      "text": "In the 13th century, the Church of the East began to decline due to the Mongol invasions and the subsequent political changes in the region.",
      "date": "1200"
    },
    {
      "headline": "Schism and Formation of the Chaldean Catholic Church",
      "text": "In 1552, a schism occurred within the Church of the East, leading to the formation of the Chaldean Catholic Church, which entered into communion with the Roman Catholic Church.",
      "date": "1552"
    },
    {
      "headline": "Modern Reorganization",
      "text": "In the 20th century, the Assyrian Church of the East underwent significant reorganization, establishing new dioceses in the diaspora and engaging in ecumenical dialogues.",
      "date": "1900"
    }
  ]
