  "timeline": [
    {
      "headline": "Birth of Pompey",
      "text": "Gnaeus Pompeius Magnus, known as Pompey, was born on September 29, 106 BCE in Picenum, Italy.",
      "date": "-0106-09-29"
    },
    {
      "headline": "First Military Command",
      "text": "In 83 BCE, Pompey raised three legions to support Sulla's return to Italy, marking his first significant military command.",
      "date": "-0083"
    },
    {
      "headline": "Triumph for Victories in Africa",
      "text": "In 81 BCE, Pompey was granted a triumph for his victories in Africa, despite not holding a senatorial office.",
      "date": "-0081"
    },
    {
      "headline": "Marriage to Sulla's Stepdaughter",
      "text": "In 83 BCE, Pompey married Aemilia Scaura, Sulla's stepdaughter, strengthening his political alliances.",
      "date": "-0083"
    },
    {
      "headline": "Defeat of Sertorius",
      "text": "In 72 BCE, Pompey played a crucial role in the defeat of the Roman general Sertorius in Hispania.",
      "date": "-0072"
    },
    {
      "headline": "Consulship with Crassus",
      "text": "In 70 BCE, Pompey served as consul of Rome alongside Marcus Licinius Crassus.",
      "date": "-0070"
    },
    {
      "headline": "Defeat of the Pirates",
      "text": "In 67 BCE, Pompey was given extraordinary powers to rid the Mediterranean Sea of pirates, which he accomplished in just three months.",
      "date": "-0067"
    },
    {
      "headline": "Campaign Against Mithridates VI",
      "text": "From 66 BCE to 63 BCE, Pompey led successful campaigns against Mithridates VI of Pontus, expanding Roman territories in the East.",
      "date": "-0066"
    },
    {
      "headline": "Third Triumph",
      "text": "In 61 BCE, Pompey celebrated his third triumph in Rome for his victories in the East.",
      "date": "-0061"
    },
    {
      "headline": "First Triumvirate",
      "text": "In 60 BCE, Pompey formed the First Triumvirate with Julius Caesar and Crassus, a political alliance that dominated Roman politics.",
      "date": "-0060"
    },
    {
      "headline": "Second Consulship",
      "text": "In 55 BCE, Pompey served his second consulship, again with Crassus.",
      "date": "-0055"
    },
    {
      "headline": "Break with Caesar",
      "text": "In 49 BCE, tensions between Pompey and Caesar escalated, leading to a civil war after Caesar crossed the Rubicon.",
      "date": "-0049"
    },
    {
      "headline": "Defeat at the Battle of Pharsalus",
      "text": "On August 9, 48 BCE, Pompey was decisively defeated by Caesar at the Battle of Pharsalus in Greece.",
      "date": "-0048-08-09"
    },
    {
      "headline": "Assassination in Egypt",
      "text": "On September 28, 48 BCE, Pompey was assassinated upon his arrival in Egypt, where he sought refuge after his defeat.",
      "date": "-0048-09-28"
    }
  ]
}

