{
  "timeline": [
    {
      "headline": "Euclid's Algorithm",
      "text": "Euclid's algorithm, one of the earliest known algorithms, was described in Euclid's Elements around 300 BCE. It is used to compute the greatest common divisor of two numbers.",
      "date": "-0300"
    },
    {
      "headline": "Al-Khwarizmi's Contributions",
      "text": "In the 9th century, Persian mathematician Al-Khwarizmi wrote a book on the systematic solution of linear and quadratic equations, which introduced the term 'algorithm' derived from his name.",
      "date": "0820"
    },
    {
      "headline": "Development of the Binary System",
      "text": "In 1679, Gottfried Wilhelm Leibniz developed the binary numeral system, which is fundamental to the operation of modern computers and algorithms.",
      "date": "1679"
    },
    {
      "headline": "Ada Lovelace's Algorithm",
      "text": "In 1843, Ada Lovelace wrote the first algorithm intended to be processed by a machine, for Charles Babbage's early mechanical general-purpose computer, the Analytical Engine.",
      "date": "1843"
    },
    {
      "headline": "Turing Machine Concept",
      "text": "In 1936, Alan Turing introduced the concept of a Turing machine, providing a formal foundation for the theory of computation and algorithms.",
      "date": "1936"
    },
    {
      "headline": "Quicksort Algorithm",
      "text": "In 1960, Tony Hoare developed the Quicksort algorithm, an efficient sorting algorithm that is still widely used today.",
      "date": "1960"
    },
    {
      "headline": "RSA Algorithm",
      "text": "In 1977, the RSA algorithm was introduced by Ron Rivest, Adi Shamir, and Leonard Adleman, revolutionizing public-key cryptography.",
      "date": "1977"
    },
    {
      "headline": "PageRank Algorithm",
      "text": "In 1996, Larry Page and Sergey Brin developed the PageRank algorithm, which became the foundation of Google's search engine.",
      "date": "1996"
    }
  ]
}

