    },
    {
      "headline": "Commissioning of the Taj Mahal",
      "text": "Following her death, Shah Jahan commissioned the construction of the Taj Mahal in Agra as a mausoleum for Mumtaz Mahal. The construction began in 1632.",
      "date": "1632"
    }
  ]
}

{
  "timeline": [
