{
  "timeline": [
    {
      "headline": "Renaming to Zaire",
      "text": "On October 27, 1971, the Democratic Republic of the Congo was officially renamed the Republic of Zaire by President Mobutu Sese Seko as part of his Authenticité campaign, which aimed to rid the country of colonial influences.",
      "date": "1971-10-27"
    },
    {
      "headline": "Mobutu's Dictatorship",
      "text": "Throughout the 1970s and 1980s, Mobutu Sese Seko ruled Zaire as a dictator, maintaining power through a combination of patronage, repression, and the support of Western governments, particularly the United States, due to Zaire's strategic importance during the Cold War.",
      "date": "1970"
    },
    {
      "headline": "Shaba I Conflict",
      "text": "In March 1977, the Shaba I conflict occurred when the Front for the National Liberation of the Congo (FNLC) invaded the Shaba Province from Angola. The conflict ended in May 1977 with the intervention of Moroccan troops and French logistical support.",
      "date": "1977-03"
    },
    {
      "headline": "Shaba II Conflict",
      "text": "In May 1978, the Shaba II conflict erupted as the FNLC again invaded Shaba Province. This time, Zaire received military assistance from France, Belgium, and the United States, leading to the defeat of the FNLC by June 1978.",
      "date": "1978-05"
    },
    {
      "headline": "Economic Decline",
      "text": "During the 1980s, Zaire's economy suffered due to corruption, mismanagement, and falling commodity prices. The country's infrastructure deteriorated, and Mobutu's regime faced increasing domestic and international criticism.",
      "date": "1980"
    },
    {
      "headline": "Transition to Democracy",
      "text": "In the early 1990s, Mobutu faced pressure to democratize. In 1991, he agreed to a transition to multiparty democracy, but the process was marred by delays and political instability.",
      "date": "1991"
    },
    {
      "headline": "First Congo War",
      "text": "The First Congo War began in October 1996 when Laurent-Désiré Kabila, with support from Rwanda and Uganda, launched a rebellion against Mobutu's regime. The war led to the overthrow of Mobutu in May 1997.",
      "date": "1996-10"
    },
    {
      "headline": "End of Zaire",
      "text": "On May 17, 1997, Laurent-Désiré Kabila's forces captured Kinshasa, and Mobutu fled the country. Kabila declared himself president and renamed the country the Democratic Republic of the Congo, marking the end of Zaire.",
      "date": "1997-05-17"
    }
  ]
}

