{
  "timeline": [
    {
      "headline": "Discovery of SSRIs",
      "text": "The concept of selective serotonin reuptake inhibition was first proposed in the late 1960s. Researchers began exploring the role of serotonin in depression and the potential for drugs to selectively inhibit its reuptake.",
      "date": "1960"
    },
    {
      "headline": "Development of Fluoxetine",
      "text": "Fluoxetine, the first SSRI, was developed by Eli Lilly and Company. It was discovered by Bryan Molloy and Robert Rathbun in 1972.",
      "date": "1972"
    },
    {
      "headline": "Approval of Fluoxetine by the FDA",
      "text": "Fluoxetine, marketed as Prozac, was approved by the U.S. Food and Drug Administration (FDA) for the treatment of major depressive disorder in December 1987.",
      "date": "1987-12"
    },
    {
      "headline": "Introduction of Other SSRIs",
      "text": "Following the success of fluoxetine, other SSRIs such as sertraline (Zoloft), paroxetine (Paxil), and citalopram (Celexa) were developed and introduced in the 1990s.",
      "date": "1990"
    },
    {
      "headline": "SSRIs Become Widely Prescribed",
      "text": "By the late 1990s and early 2000s, SSRIs had become some of the most commonly prescribed antidepressants worldwide due to their efficacy and relatively favorable side effect profile compared to older antidepressants.",
      "date": "2000"
    },
    {
      "headline": "Concerns About SSRIs and Adolescents",
      "text": "In the early 2000s, concerns arose about the use of SSRIs in children and adolescents, particularly regarding an increased risk of suicidal thoughts and behaviors. This led to warnings and changes in prescribing practices.",
      "date": "2003"
    },
    {
      "headline": "Continued Research and Development",
      "text": "Research into SSRIs continues, with ongoing studies into their mechanisms of action, long-term effects, and potential new therapeutic uses beyond depression and anxiety.",
      "date": "2023"
    }
  ]
}

