    {
      "headline": "Port Arthur Massacre",
      "text": "On 28 April 1996, a mass shooting occurred at Port Arthur, a tourist town in Tasmania, Australia. The perpetrator, Martin Bryant, killed 35 people and wounded 23 others, making it the deadliest massacre in modern Australian history.",
      "date": "1996-04-28"
    },
    {
      "headline": "Immediate Aftermath and Arrest",
      "text": "Following the massacre, Martin Bryant was captured by police the next day, on 29 April 1996, after setting fire to a guest house where he had taken hostages.",
      "date": "1996-04-29"
    },
    {
      "headline": "Gun Law Reforms",
      "text": "In response to the massacre, the Australian government, led by Prime Minister John Howard, implemented strict gun control laws. The National Firearms Agreement was established in May 1996, which included a ban on semi-automatic rifles and shotguns, and a buyback program for such firearms.",
      "date": "1996-05"
    },
    {
      "headline": "Martin Bryant's Sentencing",
      "text": "On 22 November 1996, Martin Bryant was sentenced to 35 life sentences without the possibility of parole, one for each of the victims he killed, plus an additional 1,035 years for other charges.",
      "date": "1996-11-22"
    }
  ]
}

