      "headline": "Birth of Arthur Schopenhauer",
      "text": "Arthur Schopenhauer was born on February 22, 1788, in Danzig, which is now Gdańsk, Poland.",
      "date": "1788-02-22"
    },
    {
      "headline": "Family Moves to Hamburg",
      "text": "In 1793, Schopenhauer's family moved to Hamburg after Danzig was annexed by Prussia.",
      "date": "1793"
    },
    {
      "headline": "Education in Gotha and Weimar",
      "text": "In 1803, Schopenhauer was sent to school in Gotha and later in Weimar, where he received a classical education.",
      "date": "1803"
    },
    {
      "headline": "University Studies",
      "text": "In 1809, Schopenhauer enrolled at the University of Göttingen to study medicine, but he soon switched to philosophy.",
      "date": "1809"
    },
    {
      "headline": "Transfer to the University of Berlin",
      "text": "In 1811, Schopenhauer transferred to the University of Berlin, where he attended lectures by prominent philosophers such as Johann Gottlieb Fichte.",
      "date": "1811"
    },
    {
      "headline": "Completion of Doctoral Dissertation",
      "text": "In 1813, Schopenhauer completed his doctoral dissertation, 'On the Fourfold Root of the Principle of Sufficient Reason', at the University of Jena.",
      "date": "1813"
    },
    {
      "headline": "Publication of The World as Will and Representation",
      "text": "In 1818, Schopenhauer published his most famous work, 'The World as Will and Representation', which laid out his philosophical system.",
      "date": "1818"
    },
    {
      "headline": "Lectures at the University of Berlin",
      "text": "In 1820, Schopenhauer began lecturing at the University of Berlin, though his lectures were poorly attended.",
      "date": "1820"
    },
    {
      "headline": "Move to Frankfurt",
      "text": "In 1833, Schopenhauer moved to Frankfurt, where he would live for the rest of his life.",
      "date": "1833"
    },
    {
      "headline": "Publication of Parerga and Paralipomena",
      "text": "In 1851, Schopenhauer published 'Parerga and Paralipomena', a collection of essays and aphorisms that gained him widespread recognition.",
      "date": "1851"
    },
    {
      "headline": "Death of Arthur Schopenhauer",
      "text": "Arthur Schopenhauer died on September 21, 1860, in Frankfurt, Germany.",
      "date": "1860-09-21"
    }
  ]
}

