    {
      "headline": "First Publication",
      "text": "The Protocols of the Elders of Zion was first published in 1903 in Russia. It was fabricated to purport a Jewish plot for global domination.",
      "date": "1903"
    },
    {
      "headline": "Publication in Znamya",
      "text": "In August 1903, the text was serialized in the Russian newspaper Znamya, which helped to spread its influence.",
      "date": "1903-08"
    },
    {
      "headline": "Translation and International Dissemination",
      "text": "During the early 1920s, The Protocols were translated into multiple languages and disseminated internationally, contributing to the spread of antisemitic beliefs.",
      "date": "1920"
    },
    {
      "headline": "Henry Ford's Endorsement",
      "text": "In 1920, American industrialist Henry Ford endorsed The Protocols in his newspaper, The Dearborn Independent, further popularizing the text in the United States.",
      "date": "1920"
    },
    {
      "headline": "Exposure as a Forgery",
      "text": "In 1921, The Times of London published articles exposing The Protocols as a forgery, significantly impacting its credibility.",
      "date": "1921"
    },
    {
      "headline": "Nazi Germany's Use",
      "text": "During the 1930s and 1940s, The Protocols were used by Nazi Germany as propaganda to justify antisemitic policies and actions.",
      "date": "1930"
    },
    {
      "headline": "Continued Influence",
      "text": "Despite being exposed as a forgery, The Protocols have continued to influence antisemitic groups and conspiracy theories into the 21st century.",
      "date": "2000"
    }
  ]
}

