{
  "timeline": [
    {
      "headline": "Founding of the National Action Party",
      "text": "The National Action Party (Partido Acción Nacional, PAN) was founded on September 16, 1939, in Mexico City. It was established as a conservative political party in response to the policies of the ruling Institutional Revolutionary Party (PRI).",
      "date": "1939-09-16"
    },
    {
      "headline": "First Participation in Presidential Elections",
      "text": "PAN participated in its first presidential election in 1940, with candidate Juan Andrew Almazán. Although he did not win, this marked the beginning of PAN's involvement in national elections.",
      "date": "1940"
    },
    {
      "headline": "First Electoral Victory",
      "text": "In 1946, PAN won its first electoral victory by securing a seat in the federal Chamber of Deputies, marking its initial success in Mexican politics.",
      "date": "1946"
    },
    {
      "headline": "First Governorship",
      "text": "PAN won its first governorship in 1989 when Ernesto Ruffo Appel was elected governor of Baja California, breaking the PRI's long-standing hold on state governorships.",
      "date": "1989"
    },
    {
      "headline": "First Presidential Victory",
      "text": "In 2000, PAN candidate Vicente Fox won the presidential election, ending the PRI's 71-year hold on the presidency. This was a significant milestone in Mexican political history.",
      "date": "2000"
    },
    {
      "headline": "Second Presidential Victory",
      "text": "PAN secured its second consecutive presidential victory in 2006 with the election of Felipe Calderón, who served as President of Mexico from 2006 to 2012.",
      "date": "2006"
    },
    {
      "headline": "Loss of Presidency",
      "text": "In the 2012 presidential election, PAN candidate Josefina Vázquez Mota was defeated, and the PRI regained the presidency with Enrique Peña Nieto's victory.",
      "date": "2012"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Gurkha Kingdom",
      "text": "In 1559, Dravya Shah established the Kingdom of Gorkha in the region that is now part of Nepal.",
      "date": "1559"
    },
    {
      "headline": "Unification of Nepal",
      "text": "In the mid-18th century, King Prithvi Narayan Shah, a ruler of the Gorkha Kingdom, initiated the unification of Nepal, which was completed in 1769.",
      "date": "1769"
    },
    {
      "headline": "Anglo-Nepalese War",
      "text": "The Anglo-Nepalese War, also known as the Gurkha War, took place from 1814 to 1816 between the Kingdom of Gorkha and the British East India Company.",
      "date": "1814"
    },
    {
      "headline": "Treaty of Sugauli",
      "text": "The Treaty of Sugauli was signed on December 2, 1815, and ratified in March 1816, ending the Anglo-Nepalese War and ceding some Nepalese territories to the British.",
      "date": "1816-03"
    },
    {
      "headline": "Recruitment into British Army",
      "text": "Following the Treaty of Sugauli, Gurkhas began to be recruited into the British Army, starting in 1815.",
      "date": "1815"
    },
    {
      "headline": "World War I Participation",
      "text": "During World War I (1914-1918), over 200,000 Gurkhas served in the British Army, fighting in various theaters including France, Gallipoli, and Mesopotamia.",
      "date": "1914"
    },
    {
      "headline": "World War II Participation",
      "text": "In World War II (1939-1945), Gurkhas served in the British Army, participating in campaigns in North Africa, Italy, and Southeast Asia.",
      "date": "1939"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, the partition of India led to the division of Gurkha regiments between the British and Indian armies.",
      "date": "1947"
    },
    {
      "headline": "Formation of the Brigade of Gurkhas",
      "text": "In 1948, the Brigade of Gurkhas was formed as part of the British Army, consisting of Gurkha regiments that remained with Britain after Indian independence.",
      "date": "1948"
    },
    {
      "headline": "Gurkhas in the Falklands War",
      "text": "In 1982, Gurkhas were deployed as part of the British Task Force in the Falklands War against Argentina.",
      "date": "1982"
    },
    {
      "headline": "Gurkha Justice Campaign",
      "text": "In the early 21st century, campaigns were launched to secure equal rights for Gurkhas who served in the British Army, leading to a landmark decision in 2009 allowing Gurkhas to settle in the UK.",
      "date": "2009"
    }
  ]
}

