{
  "timeline": [
    {
      "headline": "Development of Mosin–Nagant",
      "text": "The development of the Mosin–Nagant rifle began in the late 19th century in response to the need for a modern rifle for the Russian Imperial Army. The design was a collaboration between Russian and Belgian designers, with significant contributions from Sergei Mosin and Léon Nagant.",
      "date": "1880"
    },
    {
      "headline": "Adoption of the Mosin–Nagant",
      "text": "The Mosin–Nagant rifle was officially adopted by the Russian Imperial Army on April 13, 1891, as the 3-line rifle M1891.",
      "date": "1891-04-13"
    },
    {
      "headline": "First Production",
      "text": "The first production of the Mosin–Nagant rifles began in 1892 at the Tula Arsenal, with subsequent production at the Izhevsk and Sestroretsk arsenals.",
      "date": "1892"
    },
    {
      "headline": "Use in Russo-Japanese War",
      "text": "The Mosin–Nagant was used extensively by Russian forces during the Russo-Japanese War from 1904 to 1905.",
      "date": "1904"
    },
    {
      "headline": "World War I Deployment",
      "text": "The Mosin–Nagant was the standard issue rifle for Russian troops during World War I, starting in 1914.",
      "date": "1914"
    },
    {
      "headline": "Soviet Modifications",
      "text": "In 1930, the Soviet Union introduced the M91/30, a modernized version of the Mosin–Nagant, which became the most widely produced variant.",
      "date": "1930"
    },
    {
      "headline": "World War II Service",
      "text": "The Mosin–Nagant was used by Soviet forces throughout World War II, with millions of units produced during the war years.",
      "date": "1939"
    },
    {
      "headline": "Post-War Production",
      "text": "After World War II, the Mosin–Nagant continued to be produced and used by various countries, with production ceasing in the Soviet Union in 1965.",
      "date": "1965"
    },
    {
      "headline": "Legacy and Collectibility",
      "text": "Today, the Mosin–Nagant is a popular collector's item and is still used by some military forces and civilian shooters worldwide.",
      "date": "2023"
    }
  ]
}

{
