{
  "timeline": [
    {
      "headline": "Donation of Pepin",
      "text": "In 756, Pepin the Short, King of the Franks, donated a large strip of land in central Italy to the Pope, marking the beginning of the Papal States.",
      "date": "0756"
    },
    {
      "headline": "Charlemagne's Confirmation",
      "text": "In 774, Charlemagne confirmed the Donation of Pepin, further solidifying the Papal States' territorial claims.",
      "date": "0774"
    },
    {
      "headline": "Papal States at its Height",
      "text": "During the 11th and 12th centuries, the Papal States reached their territorial height, encompassing a significant portion of central Italy.",
      "date": "1100"
    },
    {
      "headline": "Avignon Papacy",
      "text": "From 1309 to 1377, the Papacy resided in Avignon, France, which weakened the control over the Papal States.",
      "date": "1309"
    },
    {
      "headline": "Return to Rome",
      "text": "In 1377, Pope Gregory XI returned the Papacy to Rome, re-establishing direct control over the Papal States.",
      "date": "1377"
    },
    {
      "headline": "Sack of Rome",
      "text": "In 1527, Rome was sacked by the troops of Charles V, Holy Roman Emperor, which severely impacted the Papal States.",
      "date": "1527"
    },
    {
      "headline": "Treaty of Tolentino",
      "text": "In 1797, the Treaty of Tolentino was signed between the Papal States and Napoleonic France, resulting in territorial losses for the Papal States.",
      "date": "1797"
    },
    {
      "headline": "Restoration of the Papal States",
      "text": "In 1814, following the defeat of Napoleon, the Papal States were restored by the Congress of Vienna.",
      "date": "1814"
    },
    {
      "headline": "Revolution of 1848",
      "text": "In 1848, a revolution in Rome led to the temporary establishment of the Roman Republic, which was suppressed by French intervention in 1849.",
      "date": "1848"
    },
    {
      "headline": "Capture of Rome",
      "text": "On September 20, 1870, the Kingdom of Italy captured Rome, marking the end of the Papal States and the unification of Italy.",
      "date": "1870-09-20"
    }
  ]
}

