    {
      "headline": "Authorization for Combat 'V' Device",
      "text": "In 1947, the Department of the Army authorized the use of the 'V' device to denote acts of valor for the Bronze Star Medal.",
      "date": "1947"
    },
    {
      "headline": "Expansion of Eligibility",
      "text": "In 1962, eligibility for the Bronze Star Medal was expanded to include service members who distinguished themselves by meritorious achievement or service in connection with military operations against an armed enemy.",
      "date": "1962"
    },
    {
      "headline": "Vietnam War Recognition",
      "text": "During the Vietnam War, the Bronze Star Medal was widely awarded to U.S. military personnel for acts of heroism and meritorious service in the conflict.",
      "date": "1965"
    },
    {
      "headline": "Gulf War Awards",
      "text": "The Bronze Star Medal was awarded to service members for their actions during the Gulf War in 1990-1991, recognizing their contributions to Operation Desert Storm.",
      "date": "1991"
    },
    {
      "headline": "Global War on Terrorism",
      "text": "Since 2001, the Bronze Star Medal has been awarded to U.S. military personnel for their service in the Global War on Terrorism, including operations in Afghanistan and Iraq.",
      "date": "2001"
    }
  ]
}

