{
  "timeline": [
    {
      "headline": "Earliest Settlement",
      "text": "Jericho is considered one of the oldest inhabited cities in the world, with evidence of settlement dating back to around 9000 BCE.",
      "date": "-09000"
    },
    {
      "headline": "Natufian Culture",
      "text": "The Natufian culture, a Mesolithic culture, inhabited Jericho around 10,000 BCE, leaving behind evidence of early agriculture.",
      "date": "-10000"
    },
    {
      "headline": "Pre-Pottery Neolithic A",
      "text": "During the Pre-Pottery Neolithic A period (circa 8350 BCE to 7370 BCE), Jericho saw the construction of a massive stone wall and tower, indicating advanced social organization.",
      "date": "-08350"
    },
    {
      "headline": "Pre-Pottery Neolithic B",
      "text": "From approximately 7220 BCE to 5850 BCE, Jericho was part of the Pre-Pottery Neolithic B culture, which saw the development of rectangular mud-brick houses.",
      "date": "-07220"
    },
    {
      "headline": "Bronze Age City",
      "text": "By the Early Bronze Age (circa 3000 BCE), Jericho was a fortified city with a significant population.",
      "date": "-03000"
    },
    {
      "headline": "Destruction and Rebuilding",
      "text": "Jericho experienced several cycles of destruction and rebuilding during the Middle and Late Bronze Ages, reflecting its strategic importance.",
      "date": "-02000"
    },
    {
      "headline": "Biblical Conquest",
      "text": "According to the Hebrew Bible, Jericho was conquered by the Israelites led by Joshua around 1400 BCE, although archaeological evidence for this event is debated.",
      "date": "-01400"
    },
    {
      "headline": "Hellenistic Period",
      "text": "During the Hellenistic period (circa 332 BCE), Jericho became a part of the Seleucid Empire and later the Hasmonean Kingdom.",
      "date": "-00332"
    },
    {
      "headline": "Herodian Jericho",
      "text": "Herod the Great established a winter palace in Jericho around 30 BCE, transforming it into a major urban center.",
      "date": "-00030"
    },
    {
      "headline": "Roman and Byzantine Periods",
      "text": "Jericho continued to be an important city during the Roman and Byzantine periods, with significant architectural developments.",
      "date": "00030"
    },
    {
      "headline": "Islamic Conquest",
      "text": "In 638 CE, Jericho was conquered by Muslim armies during the Islamic expansion.",
      "date": "0638"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Jericho came under Ottoman rule in 1517 and remained part of the Ottoman Empire until the early 20th century.",
      "date": "1517"
    },
    {
      "headline": "British Mandate",
      "text": "Following World War I, Jericho became part of the British Mandate of Palestine in 1920.",
      "date": "1920"
    },
    {
      "headline": "Jordanian Control",
      "text": "After the 1948 Arab-Israeli War, Jericho came under Jordanian control until the Six-Day War in 1967.",
      "date": "1948"
    },
    {
      "headline": "Israeli Occupation",
      "text": "In 1967, Jericho was occupied by Israel during the Six-Day War.",
      "date": "1967"
    },
    {
      "headline": "Palestinian Authority",
      "text": "In 1994, Jericho became one of the first cities to be handed over to the Palestinian Authority as part of the Oslo Accords.",
      "date": "1994"
    }
  ]
}

