{
  "timeline": [
    {
      "headline": "Foundation of the Kingdom of France",
      "text": "The Kingdom of France was founded in 987 when Hugh Capet was crowned King of the Franks, marking the beginning of the Capetian dynasty.",
      "date": "0987"
    },
    {
      "headline": "Battle of Bouvines",
      "text": "On July 27, 1214, the French army led by King Philip II defeated an alliance of English, Flemish, and Holy Roman Empire forces at the Battle of Bouvines, solidifying French power in Europe.",
      "date": "1214-07-27"
    },
    {
      "headline": "Treaty of Paris",
      "text": "In 1259, the Treaty of Paris was signed between King Louis IX of France and King Henry III of England, ending hostilities and establishing territorial boundaries.",
      "date": "1259"
    },
    {
      "headline": "Hundred Years' War Begins",
      "text": "The Hundred Years' War between France and England began in 1337, lasting until 1453, and was marked by a series of conflicts over territorial claims.",
      "date": "1337"
    },
    {
      "headline": "Joan of Arc's Siege of Orléans",
      "text": "In 1429, Joan of Arc led French forces to lift the Siege of Orléans, a turning point in the Hundred Years' War.",
      "date": "1429"
    },
    {
      "headline": "End of the Hundred Years' War",
      "text": "The Hundred Years' War ended in 1453 with the French victory at the Battle of Castillon, solidifying French control over its territories.",
      "date": "1453"
    },
    {
      "headline": "Edict of Nantes",
      "text": "In 1598, King Henry IV issued the Edict of Nantes, granting religious tolerance to Huguenots and ending the French Wars of Religion.",
      "date": "1598"
    },
    {
      "headline": "Louis XIV's Reign Begins",
      "text": "Louis XIV, known as the Sun King, began his reign in 1643, eventually becoming one of the most powerful and influential monarchs in French history.",
      "date": "1643"
    },
    {
      "headline": "Revocation of the Edict of Nantes",
      "text": "In 1685, Louis XIV revoked the Edict of Nantes, leading to the persecution of Huguenots and their mass emigration from France.",
      "date": "1685"
    },
    {
      "headline": "French Revolution Begins",
      "text": "The French Revolution began in 1789, leading to the fall of the monarchy and the rise of the French Republic.",
      "date": "1789"
    },
    {
      "headline": "End of the Kingdom of France",
      "text": "The Kingdom of France was officially dissolved in 1848 during the February Revolution, which led to the establishment of the French Second Republic.",
      "date": "1848"
    }
  ]
}

