{
  "timeline": [
    {
      "headline": "Foundation of Timbuktu",
      "text": "Timbuktu was founded by the Tuareg Imashagan in the early 12th century. It started as a seasonal settlement and became a permanent settlement in the 12th century.",
      "date": "1100"
    },
    {
      "headline": "Timbuktu Becomes a Trade Hub",
      "text": "By the 14th century, Timbuktu had become an important trading post on the trans-Saharan caravan route, connecting West Africa with the Mediterranean and the Middle East.",
      "date": "1300"
    },
    {
      "headline": "Mansa Musa's Pilgrimage",
      "text": "In 1324, Mansa Musa, the ruler of the Mali Empire, visited Timbuktu during his pilgrimage to Mecca. His visit brought significant attention and wealth to the city.",
      "date": "1324"
    },
    {
      "headline": "Incorporation into the Mali Empire",
      "text": "In the 14th century, Timbuktu was incorporated into the Mali Empire, which contributed to its growth as a center of trade and Islamic learning.",
      "date": "1300"
    },
    {
      "headline": "Establishment of Sankore University",
      "text": "In the 15th century, the Sankore University was established in Timbuktu, becoming one of the leading centers of Islamic learning in the world.",
      "date": "1400"
    },
    {
      "headline": "Songhai Empire Control",
      "text": "In 1468, the Songhai Empire, under the leadership of Sunni Ali, captured Timbuktu, further enhancing its status as a center of trade and scholarship.",
      "date": "1468"
    },
    {
      "headline": "Moroccan Invasion",
      "text": "In 1591, Moroccan forces invaded Timbuktu, leading to a decline in its prosperity and influence.",
      "date": "1591"
    },
    {
      "headline": "French Colonial Rule",
      "text": "In 1893, Timbuktu came under French colonial rule, which lasted until Mali's independence in 1960.",
      "date": "1893"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1988, Timbuktu was designated as a UNESCO World Heritage Site due to its historical significance and cultural heritage.",
      "date": "1988"
    },
    {
      "headline": "Occupation by Islamist Militants",
      "text": "In 2012, Timbuktu was occupied by Islamist militants during the Northern Mali conflict, leading to significant damage to its cultural heritage.",
      "date": "2012"
    },
    {
      "headline": "Liberation of Timbuktu",
      "text": "In January 2013, French and Malian forces liberated Timbuktu from Islamist militants, restoring government control over the city.",
      "date": "2013-01"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Leonhard Euler",
      "text": "Leonhard Euler was born on April 15, 1707, in Basel, Switzerland.",
      "date": "1707-04-15"
    },
    {
      "headline": "Education at the University of Basel",
      "text": "In 1720, at the age of 13, Euler enrolled at the University of Basel, where he studied philosophy and mathematics.",
      "date": "1720"
    },
    {
      "headline": "Graduation from the University of Basel",
      "text": "Euler completed his Master's degree in philosophy in 1723, with a dissertation comparing the philosophies of Descartes and Newton.",
      "date": "1723"
    },
    {
      "headline": "Move to Saint Petersburg",
      "text": "In 1727, Euler moved to Saint Petersburg, Russia, to take up a position at the St. Petersburg Academy of Sciences.",
      "date": "1727"
    },
    {
      "headline": "Appointment as Professor of Physics",
      "text": "Euler was appointed as a professor of physics at the St. Petersburg Academy in 1730.",
      "date": "1730"
    },
    {
      "headline": "Marriage to Katharina Gsell",
      "text": "Euler married Katharina Gsell on January 7, 1734.",
      "date": "1734-01-07"
    },
    {
      "headline": "Move to Berlin",
      "text": "In 1741, Euler accepted an invitation from Frederick the Great to join the Berlin Academy of Sciences, where he worked for 25 years.",
      "date": "1741"
    },
    {
      "headline": "Publication of 'Introductio in analysin infinitorum'",
      "text": "In 1748, Euler published 'Introductio in analysin infinitorum', a foundational work in the field of mathematical analysis.",
      "date": "1748"
    },
    {
      "headline": "Return to Saint Petersburg",
      "text": "Euler returned to Saint Petersburg in 1766, where he continued his work at the St. Petersburg Academy.",
      "date": "1766"
    },
    {
      "headline": "Loss of Sight",
      "text": "Euler lost sight in his right eye in 1738 and became almost completely blind in 1766, yet continued to produce significant mathematical work.",
      "date": "1766"
    },
    {
      "headline": "Death of Leonhard Euler",
      "text": "Leonhard Euler died on September 18, 1783, in Saint Petersburg, Russia.",
      "date": "1783-09-18"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of Lucknow",
      "text": "The city of Lucknow is believed to have been founded by Lakshmana, a hero of the ancient Indian epic Ramayana. The city was originally called Lakshmanpur.",
      "date": "-1000"
    },
    {
      "headline": "Lucknow under Mughal Rule",
      "text": "During the Mughal era, Lucknow was part of the Awadh region and was governed by Mughal-appointed Nawabs.",
      "date": "1526"
    },
    {
      "headline": "Establishment of Nawabs of Awadh",
      "text": "In 1722, Saadat Ali Khan was appointed as the first Nawab of Awadh, marking the beginning of Nawabi rule in Lucknow.",
      "date": "1722"
    },
    {
      "headline": "Asaf-ud-Daula's Reign",
      "text": "Asaf-ud-Daula became the Nawab of Awadh in 1775 and moved the capital from Faizabad to Lucknow, initiating a period of architectural and cultural development.",
      "date": "1775"
    },
    {
      "headline": "Construction of Bara Imambara",
      "text": "In 1784, the Bara Imambara was constructed under the patronage of Nawab Asaf-ud-Daula, becoming a significant architectural landmark in Lucknow.",
      "date": "1784"
    },
    {
      "headline": "British Annexation of Awadh",
      "text": "In 1856, the British East India Company annexed the kingdom of Awadh, deposing the last Nawab, Wajid Ali Shah.",
      "date": "1856"
    },
    {
      "headline": "Indian Rebellion of 1857",
      "text": "Lucknow was a major center during the Indian Rebellion of 1857, with the Siege of Lucknow being a significant event in the uprising against British rule.",
      "date": "1857"
    },
    {
      "headline": "Lucknow Pact",
      "text": "In 1916, the Lucknow Pact was signed between the Indian National Congress and the All-India Muslim League, marking a significant step in the Indian independence movement.",
      "date": "1916"
    },
    {
      "headline": "Formation of Uttar Pradesh",
      "text": "In 1950, the state of Uttar Pradesh was formed, with Lucknow as its capital.",
      "date": "1950"
    },
    {
      "headline": "Metro Rail Project",
      "text": "The Lucknow Metro project was inaugurated in 2017, enhancing the city's public transportation infrastructure.",
      "date": "2017"
    }
  ]
}

