    },
    {
      "headline": "Austrian Chancellor Kurt Schuschnigg's Plebiscite Announcement",
      "text": "On March 9, 1938, Austrian Chancellor Kurt Schuschnigg announced a plebiscite to decide whether Austria should remain independent.",
      "date": "1938-03-09"
    },
    {
      "headline": "German Ultimatum to Austria",
      "text": "On March 11, 1938, Germany issued an ultimatum to Austria demanding that power be handed over to the Austrian Nazis or face invasion.",
      "date": "1938-03-11"
    },
    {
      "headline": "Resignation of Kurt Schuschnigg",
      "text": "On March 11, 1938, Austrian Chancellor Kurt Schuschnigg resigned under pressure from Germany, paving the way for the Anschluss.",
      "date": "1938-03-11"
    },
    {
      "headline": "German Troops Enter Austria",
      "text": "On March 12, 1938, German troops crossed the border into Austria, effectively annexing the country without resistance.",
      "date": "1938-03-12"
    },
    {
      "headline": "Proclamation of the Anschluss",
      "text": "On March 13, 1938, the Anschluss was officially proclaimed, and Austria was annexed into Nazi Germany.",
      "date": "1938-03-13"
    },
    {
      "headline": "Austrian Plebiscite on Anschluss",
      "text": "On April 10, 1938, a controlled plebiscite was held in Austria, with 99.7% reportedly voting in favor of the Anschluss.",
      "date": "1938-04-10"
    }
  ]
}

