{
  "timeline": [
    {
      "headline": "IMAX Corporation Founded",
      "text": "IMAX Corporation was founded in 1967 by Graeme Ferguson, Roman Kroitor, Robert Kerr, and William C. Shaw in Canada.",
      "date": "1967"
    },
    {
      "headline": "First IMAX Film Released",
      "text": "The first IMAX film, 'Tiger Child', was released at Expo '70 in Osaka, Japan, showcasing the new format to the world.",
      "date": "1970"
    },
    {
      "headline": "First Permanent IMAX Theatre",
      "text": "The first permanent IMAX theatre opened at Ontario Place in Toronto, Canada, in 1971, allowing audiences to experience the large-format films regularly.",
      "date": "1971"
    },
    {
      "headline": "IMAX Dome (OMNIMAX) Introduced",
      "text": "In 1973, IMAX introduced the IMAX Dome (OMNIMAX) system, which projects images onto a domed screen, enhancing the immersive experience.",
      "date": "1973"
    },
    {
      "headline": "IMAX Expands Internationally",
      "text": "Throughout the 1980s, IMAX expanded internationally, opening theaters in countries such as the United States, France, and Australia.",
      "date": "1980s"
    },
    {
      "headline": "IMAX 3D Technology Developed",
      "text": "IMAX developed its 3D technology in the mid-1980s, allowing for the creation of 3D films that could be shown in IMAX theaters.",
      "date": "1986"
    },
    {
      "headline": "IMAX DMR Process Introduced",
      "text": "In 2002, IMAX introduced the Digital Media Remastering (DMR) process, allowing Hollywood films to be converted into the IMAX format.",
      "date": "2002"
    },
    {
      "headline": "First Hollywood Film Released in IMAX",
      "text": "The first Hollywood film to be released in IMAX using the DMR process was 'Apollo 13', re-released in IMAX theaters in 2002.",
      "date": "2002"
    },
    {
      "headline": "IMAX Digital Projection System Launched",
      "text": "In 2008, IMAX launched its digital projection system, making it easier and more cost-effective for theaters to screen IMAX films.",
      "date": "2008"
    },
