{
  "timeline": [
    {
      "headline": "Birth of James Clerk Maxwell",
      "text": "James Clerk Maxwell was born on June 13, 1831, in Edinburgh, Scotland.",
      "date": "1831-06-13"
    },
    {
      "headline": "Education at Edinburgh Academy",
      "text": "In 1841, at the age of 10, Maxwell began his formal education at the Edinburgh Academy.",
      "date": "1841"
    },
    {
      "headline": "Enrollment at the University of Edinburgh",
      "text": "In 1847, Maxwell enrolled at the University of Edinburgh to study mathematics and natural philosophy.",
      "date": "1847"
    },
    {
      "headline": "Transfer to the University of Cambridge",
      "text": "In 1850, Maxwell transferred to the University of Cambridge, where he attended Peterhouse before transferring to Trinity College.",
      "date": "1850"
    },
    {
      "headline": "Graduation from Cambridge",
      "text": "Maxwell graduated from the University of Cambridge in 1854 with a degree in mathematics.",
      "date": "1854"
    },
    {
      "headline": "Publication of 'On Faraday's Lines of Force'",
      "text": "In 1856, Maxwell published his paper 'On Faraday's Lines of Force', which laid the groundwork for his later work on electromagnetism.",
      "date": "1856"
    },
    {
      "headline": "Appointment at Marischal College, Aberdeen",
      "text": "In 1856, Maxwell was appointed as a professor of Natural Philosophy at Marischal College, Aberdeen.",
      "date": "1856"
    },
    {
      "headline": "Marriage to Katherine Mary Dewar",
      "text": "On June 2, 1858, Maxwell married Katherine Mary Dewar, the daughter of the principal of Marischal College.",
      "date": "1858-06-02"
    },
    {
      "headline": "Publication of 'On Physical Lines of Force'",
      "text": "In 1861, Maxwell published his paper 'On Physical Lines of Force', which further developed his ideas on electromagnetism.",
      "date": "1861"
    },
    {
      "headline": "Publication of Maxwell's Equations",
      "text": "In 1865, Maxwell published his famous equations in the paper 'A Dynamical Theory of the Electromagnetic Field', unifying electricity, magnetism, and light.",
      "date": "1865"
    },
    {
      "headline": "Director of the Cavendish Laboratory",
      "text": "In 1871, Maxwell became the first Cavendish Professor of Physics at the University of Cambridge and the first director of the Cavendish Laboratory.",
      "date": "1871"
    },
    {
      "headline": "Publication of 'Theory of Heat'",
      "text": "In 1871, Maxwell published 'Theory of Heat', contributing significantly to the field of statistical mechanics.",
      "date": "1871"
    },
    {
      "headline": "Publication of 'A Treatise on Electricity and Magnetism'",
      "text": "In 1873, Maxwell published 'A Treatise on Electricity and Magnetism', which contained his comprehensive theory of electromagnetism.",
      "date": "1873"
    },
    {
      "headline": "Death of James Clerk Maxwell",
      "text": "James Clerk Maxwell died on November 5, 1879, in Cambridge, England, at the age of 48.",
      "date": "1879-11-05"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Rembrandt",
      "text": "Rembrandt Harmenszoon van Rijn was born on July 15, 1606, in Leiden, Dutch Republic.",
      "date": "1606-07-15"
    },
    {
      "headline": "Rembrandt's Early Education",
      "text": "In 1620, Rembrandt enrolled at the University of Leiden, but he soon left to pursue an apprenticeship with painter Jacob van Swanenburgh.",
      "date": "1620"
    },
    {
      "headline": "Apprenticeship with Pieter Lastman",
      "text": "In 1624, Rembrandt moved to Amsterdam to study under Pieter Lastman, a history painter known for his narrative compositions.",
      "date": "1624"
    },
    {
      "headline": "Establishment of Studio in Leiden",
      "text": "In 1625, Rembrandt returned to Leiden and opened his own studio, where he began to gain recognition for his work.",
      "date": "1625"
    },
    {
      "headline": "Move to Amsterdam",
      "text": "In 1631, Rembrandt moved to Amsterdam, where he began to receive numerous portrait commissions, establishing his reputation as a leading portraitist.",
      "date": "1631"
    },
    {
      "headline": "Marriage to Saskia van Uylenburgh",
      "text": "Rembrandt married Saskia van Uylenburgh on June 22, 1634. Saskia was the cousin of his art dealer, Hendrick van Uylenburgh.",
      "date": "1634-06-22"
    },
    {
      "headline": "The Night Watch",
      "text": "In 1642, Rembrandt completed one of his most famous works, 'The Night Watch', a large group portrait of a city militia company.",
      "date": "1642"
    },
    {
      "headline": "Death of Saskia van Uylenburgh",
      "text": "Saskia van Uylenburgh, Rembrandt's wife, died on June 14, 1642, shortly after the birth of their son Titus.",
      "date": "1642-06-14"
    },
    {
      "headline": "Financial Troubles",
      "text": "By 1656, Rembrandt faced severe financial difficulties and declared bankruptcy, leading to the auction of his house and collections.",
      "date": "1656"
    },
    {
      "headline": "Death of Titus van Rijn",
      "text": "Rembrandt's son, Titus van Rijn, died on September 4, 1668, at the age of 27.",
      "date": "1668-09-04"
    },
    {
      "headline": "Death of Rembrandt",
      "text": "Rembrandt died on October 4, 1669, in Amsterdam, Dutch Republic, and was buried in an unmarked grave in the Westerkerk.",
      "date": "1669-10-04"
    }
  ]
}

