  "timeline": [
    {
      "headline": "Start of the Battle of Verdun",
      "text": "The Battle of Verdun began on 21 February 1916, when the German 5th Army launched an attack on the French defences of the Fortified Region of Verdun on the Western Front in France.",
      "date": "1916-02-21"
    },
    {
      "headline": "German Capture of Fort Douaumont",
      "text": "On 25 February 1916, German forces captured Fort Douaumont, one of the key defensive positions in the Verdun region, marking a significant early success for the German offensive.",
      "date": "1916-02-25"
    },
    {
      "headline": "French Counterattacks Begin",
      "text": "In March 1916, the French forces began a series of counterattacks to recapture lost ground and halt the German advance.",
      "date": "1916-03"
    },
    {
      "headline": "Battle of Mort-Homme",
      "text": "From March to April 1916, intense fighting occurred at Mort-Homme, a strategic ridge west of the Meuse River, as French forces attempted to repel German advances.",
      "date": "1916-03"
    },
    {
      "headline": "German Capture of Fort Vaux",
      "text": "On 7 June 1916, German forces captured Fort Vaux after a prolonged and fierce battle, further threatening the French defensive line.",
      "date": "1916-06-07"
    },
    {
      "headline": "French Recapture of Fort Douaumont",
      "text": "On 24 October 1916, French forces successfully recaptured Fort Douaumont, marking a turning point in the battle as French forces began to regain lost territory.",
      "date": "1916-10-24"
    },
    {
      "headline": "French Recapture of Fort Vaux",
      "text": "On 2 November 1916, French forces recaptured Fort Vaux, continuing their successful counteroffensive against the German positions.",
      "date": "1916-11-02"
    },
    {
      "headline": "End of the Battle of Verdun",
      "text": "The Battle of Verdun officially ended on 18 December 1916, after nearly 10 months of continuous fighting, with French forces successfully defending Verdun and regaining much of the lost territory.",
      "date": "1916-12-18"
    }
  ]
}

