      "headline": "Council of Piacenza",
      "text": "In March 1095, Byzantine Emperor Alexios I Komnenos requested military support from the Council of Piacenza to aid in the empire's conflict with the Seljuk Turks.",
      "date": "1095-03"
    },
    {
      "headline": "Council of Clermont",
      "text": "In November 1095, Pope Urban II called for the First Crusade at the Council of Clermont, urging Christians to undertake an armed pilgrimage to Jerusalem.",
      "date": "1095-11"
    },
    {
      "headline": "Departure of the People's Crusade",
      "text": "In April 1096, the People's Crusade, a popular movement led by Peter the Hermit, departed for the Holy Land.",
      "date": "1096-04"
    },
    {
      "headline": "Massacre of Jews in the Rhineland",
      "text": "In May 1096, as part of the People's Crusade, crusaders attacked Jewish communities in the Rhineland, resulting in widespread massacres.",
      "date": "1096-05"
    },
    {
      "headline": "Departure of the Princes' Crusade",
      "text": "In August 1096, the main body of the First Crusade, known as the Princes' Crusade, began to depart from Europe.",
      "date": "1096-08"
    },
    {
      "headline": "Siege of Nicaea",
      "text": "In May 1097, the crusaders began the Siege of Nicaea, which resulted in the city's surrender to the Byzantine Empire in June 1097.",
      "date": "1097-05"
    },
    {
      "headline": "Battle of Dorylaeum",
      "text": "On July 1, 1097, the crusaders won a decisive victory against the Seljuk Turks at the Battle of Dorylaeum.",
      "date": "1097-07-01"
    },
    {
      "headline": "Siege of Antioch",
      "text": "The Siege of Antioch began in October 1097 and lasted until June 1098, when the crusaders captured the city.",
      "date": "1097-10"
    },
    {
      "headline": "Capture of Jerusalem",
      "text": "On July 15, 1099, the crusaders captured Jerusalem, marking the climax of the First Crusade.",
      "date": "1099-07-15"
    },
    {
      "headline": "Establishment of the Kingdom of Jerusalem",
      "text": "In July 1099, following the capture of Jerusalem, the Kingdom of Jerusalem was established as a Christian state.",
      "date": "1099-07"
    }
  ]
}

