{
  "timeline": [
    {
      "headline": "Disbandment of World War I German Air Forces",
      "text": "In May 1920, the Luftstreitkräfte of the Imperial Army and the Marine-Fliegerabteilung of the Imperial Navy were disbanded in accordance with the Treaty of Versailles, which banned Germany from having any air force.",
      "date": "1920-05"
    },
    {
      "headline": "Formation of the Luftwaffe",
      "text": "The Luftwaffe was officially established on February 26, 1935, as the aerial-warfare branch of the Wehrmacht, marking the re-establishment of Germany's air force in defiance of the Treaty of Versailles.",
      "date": "1935-02-26"
    },
    {
      "headline": "Spanish Civil War Involvement",
      "text": "The Luftwaffe participated in the Spanish Civil War from 1936 to 1939, providing support to Francisco Franco's Nationalist forces, which served as a testing ground for new tactics and aircraft.",
      "date": "1936"
    },
    {
      "headline": "World War II Outbreak",
      "text": "On September 1, 1939, the Luftwaffe played a crucial role in the invasion of Poland, marking the beginning of World War II.",
      "date": "1939-09-01"
    },
    {
      "headline": "Battle of Britain",
      "text": "From July to October 1940, the Luftwaffe engaged in the Battle of Britain, a significant air campaign against the United Kingdom, which ultimately ended in failure for Germany.",
      "date": "1940-07"
    },
    {
      "headline": "Operation Barbarossa",
      "text": "On June 22, 1941, the Luftwaffe supported Operation Barbarossa, the German invasion of the Soviet Union, which marked the beginning of a prolonged and costly conflict on the Eastern Front.",
      "date": "1941-06-22"
    },
    {
      "headline": "Battle of Stalingrad",
      "text": "The Luftwaffe was heavily involved in the Battle of Stalingrad from August 23, 1942, to February 2, 1943, a turning point in the war that resulted in a decisive Soviet victory.",
      "date": "1942-08-23"
    },
    {
      "headline": "D-Day and Allied Invasion of Normandy",
      "text": "On June 6, 1944, the Luftwaffe was unable to effectively counter the Allied invasion of Normandy, marking a significant step towards the liberation of Western Europe.",
      "date": "1944-06-06"
    },
    {
      "headline": "End of World War II and Luftwaffe Dissolution",
      "text": "In May 1945, following Germany's defeat in World War II, the Luftwaffe was disbanded as part of the Allied occupation and demilitarization of Germany.",
      "date": "1945-05"
    }
  ]
}

