{
  "timeline": [
    {
      "headline": "First Recorded Description of Scurvy",
      "text": "The first recorded description of scurvy was by Hippocrates, who noted symptoms consistent with the disease.",
      "date": "-0400"
    },
    {
      "headline": "Scurvy in the Age of Sail",
      "text": "During the Age of Sail, scurvy was a major problem for sailors on long voyages, as fresh fruits and vegetables were not available.",
      "date": "1500"
    },
    {
      "headline": "James Lind's Experiment",
      "text": "In 1747, James Lind, a Scottish surgeon in the Royal Navy, conducted experiments that demonstrated the effectiveness of citrus fruits in curing scurvy.",
      "date": "1747"
    },
    {
      "headline": "Publication of 'A Treatise of the Scurvy'",
      "text": "In 1753, James Lind published 'A Treatise of the Scurvy', detailing his findings and advocating for the use of citrus fruits to prevent the disease.",
      "date": "1753"
    },
    {
      "headline": "Adoption of Lemon Juice in the British Navy",
      "text": "By the late 18th century, the British Navy had adopted the use of lemon juice as a preventative measure against scurvy.",
      "date": "1795"
    },
    {
      "headline": "Isolation of Vitamin C",
      "text": "In 1932, vitamin C was isolated by Albert Szent-Györgyi and Charles Glen King, confirming its role in preventing scurvy.",
      "date": "1932"
    },
    {
      "headline": "Synthesis of Vitamin C",
      "text": "In 1933, the first synthetic vitamin C was produced, making it widely available as a dietary supplement.",
      "date": "1933"
    }
  ]
}

