    {
      "headline": "Development Begins",
      "text": "In 1979, the United States Army issued a contract for a new tactical vehicle to replace the M151 Jeep and other light vehicles. This led to the development of the High Mobility Multipurpose Wheeled Vehicle (HMMWV), commonly known as the Humvee.",
      "date": "1979"
    },
    {
      "headline": "First Prototype Completed",
      "text": "The first prototype of the Humvee was completed by AM General in 1982, marking the beginning of testing and evaluation by the U.S. military.",
      "date": "1982"
    },
    {
      "headline": "Production Contract Awarded",
      "text": "In 1983, AM General was awarded a contract to produce 55,000 Humvees for the U.S. military, marking the start of mass production.",
      "date": "1983"
    },
    {
      "headline": "Introduction into Service",
      "text": "The Humvee was officially introduced into service with the United States military in 1984, replacing several older vehicles.",
      "date": "1984"
    },
    {
      "headline": "First Combat Use",
      "text": "The Humvee saw its first combat use during the United States invasion of Panama in December 1989, demonstrating its versatility and effectiveness in military operations.",
      "date": "1989-12"
    },
    {
      "headline": "Gulf War Deployment",
      "text": "During the Gulf War in 1991, the Humvee was extensively used by U.S. forces, gaining widespread recognition for its performance in desert conditions.",
      "date": "1991"
    },
    {
      "headline": "Civilian Version Introduced",
      "text": "In 1992, AM General introduced a civilian version of the Humvee, known as the Hummer H1, making the vehicle available to the general public.",
      "date": "1992"
    },
    {
      "headline": "Hummer Brand Sold",
      "text": "In 1999, AM General sold the rights to the Hummer brand to General Motors, which continued to produce civilian versions of the vehicle.",
      "date": "1999"
    },
    {
      "headline": "Up-armored Humvees",
      "text": "In response to the increased threat of improvised explosive devices (IEDs) during the Iraq War, up-armored versions of the Humvee were developed and deployed starting in the early 2000s.",
      "date": "2000"
    },
