  "timeline": [
    {
      "headline": "Birth of the Lost Generation",
      "text": "The Lost Generation refers to the demographic cohort born from 1883 to 1900. This generation reached early adulthood during World War I and came of age in the 1900s or 1910s.",
      "date": "1883"
    },
    {
      "headline": "World War I",
      "text": "World War I, lasting from 1914 to 1918, significantly impacted the Lost Generation. Many members of this generation served in the war, experiencing its horrors firsthand.",
      "date": "1914"
    },
    {
      "headline": "Post-World War I Disillusionment",
      "text": "After World War I ended in 1918, many members of the Lost Generation felt disillusioned and disoriented, struggling to find meaning in the postwar world.",
      "date": "1918"
    },
    {
      "headline": "Gertrude Stein Coins the Term",
      "text": "Gertrude Stein is credited with coining the term 'Lost Generation' to describe the disoriented and directionless spirit of many war survivors. The term was popularized by Ernest Hemingway.",
      "date": "1920s"
    },
    {
      "headline": "Expatriate Writers in Paris",
      "text": "During the 1920s, a group of American expatriate writers, including Ernest Hemingway, F. Scott Fitzgerald, and T.S. Eliot, lived in Paris and became associated with the Lost Generation.",
      "date": "1920s"
    },
    {
      "headline": "Publication of 'The Sun Also Rises'",
      "text": "In 1926, Ernest Hemingway published 'The Sun Also Rises', which included the epigraph 'You are all a lost generation', further popularizing the term.",
      "date": "1926"
    }
  ]
}

