{
  "timeline": [
    {
      "headline": "Early Development of Deism",
      "text": "Deism began to develop in the late 17th century as a rationalistic approach to religion, emphasizing reason and the observation of the natural world as the basis for belief in God.",
      "date": "1600"
    },
    {
      "headline": "Publication of 'De Veritate' by Lord Herbert of Cherbury",
      "text": "In 1624, Lord Herbert of Cherbury published 'De Veritate', which is considered one of the first major works of Deism. It laid the groundwork for Deist thought by arguing for a religion based on reason and nature.",
      "date": "1624"
    },
    {
      "headline": "John Toland's 'Christianity Not Mysterious'",
      "text": "In 1696, John Toland published 'Christianity Not Mysterious', which argued that all religious truths could be discovered through reason and should not be considered mysterious or beyond human understanding.",
      "date": "1696"
    },
    {
      "headline": "Matthew Tindal's 'Christianity as Old as the Creation'",
      "text": "In 1730, Matthew Tindal published 'Christianity as Old as the Creation', often referred to as the 'Deist's Bible'. It argued that true religion is as old as creation itself and can be understood through reason.",
      "date": "1730"
    },
    {
      "headline": "Influence on the Founding Fathers of the United States",
      "text": "During the late 18th century, Deism influenced several of the Founding Fathers of the United States, including Thomas Jefferson and Benjamin Franklin, who incorporated Deist principles into their political and philosophical beliefs.",
      "date": "1776"
    },
    {
      "headline": "Decline of Deism",
      "text": "By the early 19th century, Deism began to decline as a distinct movement, overshadowed by the rise of other philosophical and religious movements, including Romanticism and evangelical Christianity.",
      "date": "1800"
    }
  ]
}

