    },
    {
      "headline": "Operation Husky (D-Day)",
      "text": "On July 9, 1943, Operation Husky, the Allied invasion of Sicily, commenced. This operation marked the beginning of the Italian Campaign and led to the downfall of Mussolini.",
      "date": "1943-07-09"
    },
    {
