      "date": "1944-08-15"
    },
    {
      "headline": "Operation Shingle (D-Day)",
      "text": "On January 22, 1944, Operation Shingle, the Allied amphibious landing at Anzio, Italy, took place. This operation aimed to outflank German forces and facilitate the capture of Rome.",
      "date": "1944-01-22"
    }
  ]
}

