{
  "timeline": [
    {
      "headline": "Birth of Confucius",
      "text": "Confucius, the founder of Confucianism, was born in 551 BC in the state of Lu, in what is now Shandong province, China.",
      "date": "-0551"
    },
    {
      "headline": "Confucius's Death",
      "text": "Confucius died in 479 BC, leaving behind a legacy of teachings that would later form the basis of Confucianism.",
      "date": "-0479"
    },
    {
      "headline": "Suppression during the Qin Dynasty",
      "text": "During the Qin dynasty (221–206 BC), Confucianism was suppressed as the ruling ideology was Legalism, which was more autocratic and centralized.",
      "date": "-0221"
    },
    {
      "headline": "Confucianism Becomes State Ideology",
      "text": "During the Han dynasty (206 BC–220 AD), Confucianism was adopted as the official state ideology, replacing the 'proto-Taoist' Huang–Lao thought.",
      "date": "-0206"
    },
    {
      "headline": "Establishment of Confucian Academies",
      "text": "Throughout the Han dynasty, Confucian academies were established to educate government officials, further cementing Confucianism's role in Chinese society.",
      "date": "-0206"
    },
    {
      "headline": "Confucianism during the Tang Dynasty",
      "text": "During the Tang dynasty (618–907 AD), Confucianism was revitalized and integrated with Buddhism and Taoism, leading to the development of Neo-Confucianism.",
      "date": "0618"
    },
    {
      "headline": "Neo-Confucianism",
      "text": "In the Song dynasty (960–1279 AD), Neo-Confucianism emerged, which sought to reinterpret Confucian thought in response to Buddhist and Taoist influences.",
      "date": "0960"
    },
    {
      "headline": "Confucianism in the Ming Dynasty",
      "text": "During the Ming dynasty (1368–1644 AD), Confucianism was further institutionalized, and the civil service examination system was based on Confucian texts.",
      "date": "1368"
    },
    {
      "headline": "Confucianism in Modern China",
      "text": "In the 20th century, Confucianism faced challenges from modernization and political changes, but it remains an influential cultural and philosophical force in China and beyond.",
      "date": "1900"
    }
  ]
}

