      "headline": "Construction Begins",
      "text": "Construction of the Brandenburg Gate began in 1788 by orders of King Frederick William II of Prussia. It was designed by the royal architect Carl Gotthard Langhans.",
      "date": "1788"
    },
    {
      "headline": "Completion of the Brandenburg Gate",
      "text": "The Brandenburg Gate was completed in 1791. It is an 18th-century neoclassical monument in Berlin, marking the start of the road from Berlin to Brandenburg an der Havel.",
      "date": "1791"
    },
    {
      "headline": "Quadriga Sculpture Added",
      "text": "The bronze sculpture of the quadriga, created by sculptor Johann Gottfried Schadow, was added to the top of the Brandenburg Gate.",
      "date": "1793"
    },
    {
      "headline": "Napoleon's Victory Parade",
      "text": "In 1806, after the Prussian defeat at the Battle of Jena-Auerstedt, Napoleon used the Brandenburg Gate for a triumphal procession.",
      "date": "1806"
    },
    {
      "headline": "Quadriga Taken to Paris",
      "text": "Following his victory, Napoleon took the quadriga sculpture to Paris as a trophy of war.",
      "date": "1806"
    },
    {
      "headline": "Quadriga Returned to Berlin",
      "text": "After Napoleon's defeat in 1814, the quadriga was returned to Berlin and restored to the top of the Brandenburg Gate.",
      "date": "1814"
    },
    {
      "headline": "Symbol of Division",
      "text": "During the Cold War, the Brandenburg Gate was located in the no-man's land just behind the Berlin Wall, symbolizing the division between East and West Berlin.",
      "date": "1961"
    },
    {
      "headline": "Reopening of the Brandenburg Gate",
      "text": "On December 22, 1989, the Brandenburg Gate was reopened after the fall of the Berlin Wall, symbolizing German reunification.",
      "date": "1989-12-22"
    },
    {
      "headline": "Restoration Completed",
      "text": "A major restoration of the Brandenburg Gate was completed in 2002, preserving its historical significance and structural integrity.",
      "date": "2002"
    }
  ]
}

