{
  "timeline": [
    {
      "headline": "Proto-Semitic Origins",
      "text": "Arabic, as a member of the Central Semitic languages, is believed to have descended from Proto-Semitic, which dates back to around 3750 BCE.",
      "date": "-3750"
    },
    {
      "headline": "Old Arabic",
      "text": "Old Arabic, the precursor to Classical Arabic, began to emerge around the 1st century CE. It was spoken by various tribes in the Arabian Peninsula.",
      "date": "0001"
    },
    {
      "headline": "Classical Arabic Development",
      "text": "Classical Arabic developed as the language of the Qur'an, which was revealed to the Prophet Muhammad between 610 and 632 CE. This period marks the formalization of Arabic grammar and vocabulary.",
      "date": "0610"
    },
    {
      "headline": "Standardization of Arabic Grammar",
      "text": "The standardization of Arabic grammar began in the 8th century CE, primarily through the works of scholars such as Sibawayh, who wrote the first comprehensive grammar of Arabic.",
      "date": "0750"
    },
    {
      "headline": "Emergence of Modern Standard Arabic",
      "text": "Modern Standard Arabic (MSA) emerged in the 19th and 20th centuries as a standardized form of Arabic used in formal settings, media, and literature. It is based on Classical Arabic but incorporates modern vocabulary and expressions.",
      "date": "1800"
    },
    {
      "headline": "Arabic as an Official Language of the United Nations",
      "text": "On December 18, 1973, Arabic was made an official language of the United Nations, reflecting its importance and widespread use in international diplomacy and communication.",
      "date": "1973-12-18"
    }
  ]
}

