{
  "timeline": [
    {
      "headline": "Coining of the Term 'Manifest Destiny'",
      "text": "The term 'Manifest Destiny' was first coined by journalist John L. O'Sullivan in 1845. He used it to advocate for the annexation of Texas and the Oregon Country, suggesting that the United States was destined to expand across the continent.",
      "date": "1845"
    },
    {
      "headline": "Annexation of Texas",
      "text": "In 1845, the United States annexed the Republic of Texas, which had declared independence from Mexico in 1836. This event was a significant step in the westward expansion of the United States, in line with the concept of Manifest Destiny.",
      "date": "1845"
    },
    {
      "headline": "Oregon Treaty",
      "text": "The Oregon Treaty was signed on June 15, 1846, between the United States and Great Britain. It settled the boundary dispute in the Oregon Country, extending U.S. territory to the Pacific Ocean.",
      "date": "1846-06-15"
    },
    {
      "headline": "Mexican-American War",
      "text": "The Mexican-American War began in 1846 and ended in 1848. It was a conflict between the United States and Mexico, resulting in the U.S. acquiring territories in the present-day southwestern United States, including California and New Mexico.",
      "date": "1846"
    },
    {
      "headline": "Treaty of Guadalupe Hidalgo",
      "text": "Signed on February 2, 1848, the Treaty of Guadalupe Hidalgo ended the Mexican-American War. Mexico ceded large portions of its northern territories to the United States, fulfilling part of the Manifest Destiny vision.",
      "date": "1848-02-02"
    },
    {
      "headline": "California Gold Rush",
      "text": "The discovery of gold at Sutter's Mill in 1848 led to the California Gold Rush, which began in 1849. This event accelerated westward migration and settlement, embodying the Manifest Destiny ideology.",
      "date": "1848"
    },
    {
      "headline": "Gadsden Purchase",
      "text": "In 1853, the United States purchased a region of present-day southern Arizona and southwestern New Mexico from Mexico. This acquisition was part of the Manifest Destiny expansion efforts.",
      "date": "1853"
    },
    {
      "headline": "Homestead Act",
      "text": "The Homestead Act was signed into law by President Abraham Lincoln on May 20, 1862. It encouraged westward migration by providing settlers with 160 acres of public land in exchange for a small filing fee and the requirement to live on and improve the land for five years.",
      "date": "1862-05-20"
    },
    {
      "headline": "Completion of the First Transcontinental Railroad",
      "text": "On May 10, 1869, the First Transcontinental Railroad was completed at Promontory Summit, Utah. This achievement connected the eastern and western United States, facilitating further expansion and settlement.",
      "date": "1869-05-10"
    }
  ]
}

