      "headline": "Birth of Harvey Milk",
      "text": "Harvey Bernard Milk was born on May 22, 1930, in Woodmere, New York.",
      "date": "1930-05-22"
    },
    {
      "headline": "Graduation from College",
      "text": "Harvey Milk graduated from the New York State College for Teachers (now known as the University at Albany, SUNY) in 1951.",
      "date": "1951"
