    {
      "headline": "Service in the U.S. Navy",
      "text": "Milk served in the United States Navy during the Korean War, from 1951 until he was honorably discharged in 1955.",
      "date": "1951"
    },
    {
      "headline": "Move to San Francisco",
      "text": "In 1972, Harvey Milk moved to San Francisco, where he became a prominent gay rights activist.",
      "date": "1972"
    },
    {
      "headline": "Opening of Castro Camera",
      "text": "In 1973, Milk opened a camera store called Castro Camera on Castro Street in San Francisco, which became a community center for the gay community.",
      "date": "1973"
    },
    {
      "headline": "First Run for Public Office",
      "text": "Harvey Milk ran for a seat on the San Francisco Board of Supervisors in 1973 but was unsuccessful.",
      "date": "1973"
    },
    {
      "headline": "Election to the San Francisco Board of Supervisors",
      "text": "On November 8, 1977, Harvey Milk was elected to the San Francisco Board of Supervisors, becoming the first openly gay man to be elected to public office in California.",
      "date": "1977-11-08"
    },
    {
      "headline": "Passing of the Gay Rights Ordinance",
      "text": "In 1978, Milk sponsored a bill that banned discrimination in public accommodations, housing, and employment on the basis of sexual orientation, which was passed by the Board of Supervisors.",
      "date": "1978"
    },
    {
      "headline": "Assassination of Harvey Milk",
      "text": "Harvey Milk was assassinated on November 27, 1978, by Dan White, a former city supervisor, at San Francisco City Hall.",
