{
  "timeline": [
    {
      "headline": "Start of Dunkirk Evacuation",
      "text": "The Dunkirk evacuation, codenamed Operation Dynamo, began on 26 May 1940. It was initiated to evacuate Allied soldiers from the beaches and harbour of Dunkirk, France, after they were surrounded by German forces during the Battle of France.",
      "date": "1940-05-26"
    },
    {
      "headline": "Evacuation Efforts Intensify",
      "text": "By 27 May 1940, the evacuation efforts intensified as the situation became more desperate. The British Expeditionary Force (BEF) and other Allied troops were under heavy attack from German forces.",
      "date": "1940-05-27"
    },
    {
      "headline": "Civilian Boats Join the Evacuation",
      "text": "On 28 May 1940, civilian vessels, famously known as the 'Little Ships of Dunkirk,' began to assist in the evacuation, helping to transport soldiers from the beaches to larger ships.",
      "date": "1940-05-28"
    },
    {
      "headline": "Belgian Army Surrenders",
      "text": "The Belgian Army surrendered on 28 May 1940, which increased the urgency of the evacuation as German forces could now focus entirely on Dunkirk.",
      "date": "1940-05-28"
    },
    {
      "headline": "Peak of Evacuation",
      "text": "The peak of the evacuation occurred on 29 May 1940, when the largest number of troops were evacuated in a single day, with over 47,000 soldiers rescued.",
      "date": "1940-05-29"
    },
    {
      "headline": "Continued Evacuation",
      "text": "The evacuation continued through 30 May to 2 June 1940, with thousands more soldiers being evacuated each day under difficult conditions.",
      "date": "1940-05-30"
    },
    {
      "headline": "Operation Dynamo Concludes",
      "text": "Operation Dynamo concluded on 4 June 1940. By this time, over 338,000 Allied soldiers had been successfully evacuated from Dunkirk.",
      "date": "1940-06-04"
    }
  ]
}

