      "headline": "Birth of Darius the Great",
      "text": "Darius I, commonly known as Darius the Great, was born in 550 BCE. He was a member of the Achaemenid dynasty.",
      "date": "-0550"
    },
    {
      "headline": "Darius Becomes King of Kings",
      "text": "In 522 BCE, Darius I ascended to the throne of the Achaemenid Empire after the death of Cambyses II and the defeat of the usurper Gaumata.",
      "date": "-0522"
    },
    {
      "headline": "Reorganization of the Empire",
      "text": "Darius reorganized the Achaemenid Empire into satrapies, or provinces, and established a system of taxation and tribute in 518 BCE.",
      "date": "-0518"
    },
    {
      "headline": "Construction of Persepolis",
      "text": "Around 515 BCE, Darius began the construction of the ceremonial capital of Persepolis, which became a symbol of the empire's power.",
      "date": "-0515"
    },
    {
      "headline": "Invasion of Scythia",
      "text": "In 513 BCE, Darius launched a military campaign against the Scythians, crossing the Danube River, although the campaign did not result in a decisive victory.",
      "date": "-0513"
    },
    {
      "headline": "First Persian Invasion of Greece",
      "text": "In 492 BCE, Darius initiated the first Persian invasion of Greece, which included the Battle of Marathon in 490 BCE, where the Persians were defeated by the Athenians.",
      "date": "-0492"
    },
    {
      "headline": "Death of Darius the Great",
      "text": "Darius I died in 486 BCE, after a reign of 36 years, and was succeeded by his son Xerxes I.",
      "date": "-0486"
    }
  ]
}

