    {
      "headline": "Start of the Tet Offensive",
      "text": "On January 30, 1968, the Viet Cong (VC) and North Vietnamese People's Army of Vietnam (PAVN) launched a surprise attack against the forces of the South Vietnamese Army of the Republic of Vietnam (ARVN), the United States Armed Forces, and their allies. This marked the beginning of the Tet Offensive, a campaign of surprise attacks against military and civilian command and control centers throughout South Vietnam.",
      "date": "1968-01-30"
    },
    {
      "headline": "Attack on the U.S. Embassy in Saigon",
      "text": "In the early hours of January 31, 1968, a VC sapper team attacked the U.S. Embassy in Saigon. Although they were eventually repelled, the attack shocked the American public and media, highlighting the vulnerability of U.S. positions in Vietnam.",
      "date": "1968-01-31"
    },
    {
      "headline": "Battle of Hue",
      "text": "The Battle of Hue began on January 31, 1968, and lasted until March 2, 1968. It was one of the longest and bloodiest battles of the Tet Offensive, resulting in significant casualties on both sides and extensive damage to the city.",
      "date": "1968-01-31"
    },
    {
      "headline": "Battle of Khe Sanh",
      "text": "The Battle of Khe Sanh began on January 21, 1968, and continued during the Tet Offensive. It was a major battle in which U.S. Marines defended the Khe Sanh Combat Base against a prolonged siege by the PAVN.",
      "date": "1968-01-21"
    },
    {
      "headline": "End of the Tet Offensive",
      "text": "By March 28, 1968, the Tet Offensive had largely concluded, although sporadic fighting continued. The offensive failed to achieve its primary objective of triggering widespread rebellion and defections in South Vietnam but had a significant psychological impact on the U.S. and its perception of the Vietnam War.",
      "date": "1968-03-28"
    }
  ]
}

