{
  "timeline": [
    {
      "headline": "Earliest Documentation of Catalan",
      "text": "The earliest written records of Catalan date back to the 9th century, found in the Homilies d'Organyà, a collection of religious sermons.",
      "date": "0900"
    },
    {
      "headline": "Catalan Becomes a Literary Language",
      "text": "In the 13th century, Catalan began to be used in literature, with notable works such as the 'Llibre dels fets' by King James I of Aragon.",
      "date": "1200"
    },
    {
      "headline": "Golden Age of Catalan Literature",
      "text": "The 14th and 15th centuries marked the Golden Age of Catalan literature, with authors like Ramon Llull and Ausiàs March contributing significantly to its development.",
      "date": "1300"
    },
    {
      "headline": "Decline of Catalan Language",
      "text": "Following the union of the crowns of Castile and Aragon in 1469, Catalan began to decline in official use, especially after the War of the Spanish Succession in the early 18th century.",
      "date": "1469"
    },
    {
      "headline": "Nova Planta Decrees",
      "text": "In 1716, the Nueva Planta decrees were issued, which suppressed the institutions of Catalonia and imposed the use of Spanish in official documents.",
      "date": "1716"
    },
    {
      "headline": "Renaixença Movement",
      "text": "The 19th century saw the Renaixença, a cultural and literary revival of the Catalan language and culture.",
      "date": "1800"
    },
    {
      "headline": "Official Status in the Second Spanish Republic",
      "text": "During the Second Spanish Republic (1931-1939), Catalan was granted official status in Catalonia.",
      "date": "1931"
    },
    {
      "headline": "Suppression Under Franco",
      "text": "Under Francisco Franco's regime (1939-1975), the use of Catalan was severely restricted in public life and education.",
      "date": "1939"
    },
    {
      "headline": "Restoration of Catalan Language Rights",
      "text": "After Franco's death in 1975, Catalan regained its official status in Catalonia and other regions, with the Statute of Autonomy of Catalonia in 1979.",
      "date": "1979"
    },
    {
      "headline": "Catalan as an Official Language of Andorra",
      "text": "In 1993, Catalan was declared the official language of Andorra with the adoption of its constitution.",
      "date": "1993"
    }
  ]
}

