    {
      "headline": "Death of Charles II of Spain",
      "text": "On November 1, 1700, Charles II of Spain died childless, leading to a succession crisis over the Spanish Empire.",
      "date": "1700-11-01"
    },
    {
      "headline": "Philip of Anjou Named Heir",
      "text": "Charles II named Philip of Anjou, grandson of Louis XIV of France, as his heir, leading to tensions between France and other European powers.",
      "date": "1700-11"
    },
    {
      "headline": "Start of the War of the Spanish Succession",
      "text": "The War of the Spanish Succession began in 1701 as European powers contested the succession of Philip of Anjou to the Spanish throne.",
      "date": "1701"
    },
    {
      "headline": "Grand Alliance Formed",
      "text": "In 1701, the Grand Alliance was formed, consisting of Austria, the Dutch Republic, and Great Britain, to oppose the Bourbon claim to the Spanish throne.",
      "date": "1701"
    },
    {
      "headline": "Battle of Blenheim",
      "text": "On August 13, 1704, the Battle of Blenheim was fought, resulting in a decisive victory for the Grand Alliance and marking a turning point in the war.",
      "date": "1704-08-13"
    },
    {
      "headline": "Treaty of Utrecht",
      "text": "The Treaty of Utrecht was signed in 1713, ending hostilities between France and the Grand Alliance, and recognizing Philip V as King of Spain while ceding various territories.",
      "date": "1713"
    },
    {
      "headline": "Treaty of Rastatt",
      "text": "The Treaty of Rastatt was signed on March 7, 1714, between France and Austria, further concluding the War of the Spanish Succession.",
      "date": "1714-03-07"
    },
    {
      "headline": "Treaty of Baden",
      "text": "The Treaty of Baden was signed on September 7, 1714, between France and the Holy Roman Empire, marking the final end of the War of the Spanish Succession.",
      "date": "1714-09-07"
    }
  ]
}

