{
  "timeline": [
    {
      "headline": "First Mention of Nazareth",
      "text": "Nazareth is first mentioned in historical records as a small village in the region of Galilee. The exact date is uncertain, but it is believed to have been inhabited during the time of Jesus.",
      "date": "-0004"
    },
    {
      "headline": "Jesus of Nazareth",
      "text": "According to the New Testament, Jesus grew up in Nazareth. This association has made the city a significant site for Christian pilgrimage. The exact years of Jesus's life are debated, but it is generally accepted that he lived in Nazareth during his early years.",
      "date": "0000"
    },
    {
      "headline": "Byzantine Period",
      "text": "During the Byzantine period, Nazareth became a center for Christian pilgrimage. Churches were built to commemorate events in the life of Jesus.",
      "date": "0325"
    },
    {
      "headline": "Muslim Conquest",
      "text": "Nazareth came under Muslim rule following the Muslim conquest of the Levant in the 7th century. The city continued to be a site of Christian pilgrimage.",
      "date": "0638"
    },
    {
      "headline": "Crusader Period",
      "text": "Nazareth was captured by the Crusaders in the 11th century and became part of the Kingdom of Jerusalem. The Crusaders built the Church of the Annunciation during this time.",
      "date": "1099"
    },
    {
      "headline": "Mamluk Rule",
      "text": "The Mamluks took control of Nazareth in the 13th century, leading to a decline in the Christian population and pilgrimage.",
      "date": "1263"
    },
    {
      "headline": "Ottoman Period",
      "text": "Nazareth became part of the Ottoman Empire in the early 16th century. The city saw a revival of Christian pilgrimage during this time.",
      "date": "1517"
    },
    {
      "headline": "British Mandate",
      "text": "Following World War I, Nazareth came under British control as part of the British Mandate for Palestine.",
      "date": "1918"
    },
    {
      "headline": "State of Israel",
      "text": "Nazareth became part of the newly established State of Israel in 1948. It has since developed into a major cultural and economic center for Arab citizens of Israel.",
      "date": "1948"
    },
    {
      "headline": "Modern Nazareth",
      "text": "In 2022, Nazareth's population was 78,007, with a majority of Arab citizens of Israel, predominantly Muslim and Christian. It continues to be a significant cultural, political, and religious center.",
      "date": "2022"
    }
  ]
}

