  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Georg Wilhelm Friedrich Hegel",
      "text": "Georg Wilhelm Friedrich Hegel was born on August 27, 1770, in Stuttgart, in the Duchy of Württemberg, which was part of the Holy Roman Empire.",
      "date": "1770-08-27"
    },
    {
      "headline": "Hegel's Education",
      "text": "In 1788, Hegel entered the Tübinger Stift, a Protestant seminary of the University of Tübingen, where he studied philosophy and theology.",
      "date": "1788"
    },
    {
      "headline": "Graduation from Tübinger Stift",
      "text": "Hegel graduated from the Tübinger Stift in 1793 with a degree in theology.",
      "date": "1793"
    },
    {
      "headline": "Hegel's Early Career",
      "text": "After graduation, Hegel worked as a tutor in Bern (1793-1796) and then in Frankfurt (1797-1801).",
      "date": "1793"
    },
    {
      "headline": "Move to Jena",
      "text": "In 1801, Hegel moved to Jena, where he became a Privatdozent (unsalaried lecturer) at the University of Jena.",
      "date": "1801"
    },
    {
      "headline": "Publication of 'Phenomenology of Spirit'",
      "text": "In 1807, Hegel published his first major work, 'Phenomenology of Spirit', which is considered one of his most important philosophical works.",
      "date": "1807"
    },
    {
      "headline": "Professorship in Heidelberg",
      "text": "Hegel was appointed as a professor of philosophy at the University of Heidelberg in 1816.",
      "date": "1816"
    },
    {
      "headline": "Publication of 'Science of Logic'",
      "text": "Hegel published 'Science of Logic' between 1812 and 1816, which is a significant work in his philosophical system.",
      "date": "1816"
    },
    {
      "headline": "Professorship in Berlin",
      "text": "In 1818, Hegel accepted a professorship at the University of Berlin, where he became a central figure in the philosophical community.",
      "date": "1818"
    },
    {
      "headline": "Publication of 'Encyclopedia of the Philosophical Sciences'",
      "text": "In 1817, Hegel published the first edition of 'Encyclopedia of the Philosophical Sciences', which was later expanded in 1827 and 1830.",
      "date": "1817"
    },
    {
      "headline": "Publication of 'Philosophy of Right'",
      "text": "In 1820, Hegel published 'Elements of the Philosophy of Right', which outlines his views on political philosophy.",
      "date": "1820"
    },
    {
      "headline": "Death of Georg Wilhelm Friedrich Hegel",
      "text": "Hegel died on November 14, 1831, in Berlin, Kingdom of Prussia, due to a cholera epidemic.",
      "date": "1831-11-14"
    }
  ]
}

