    {
      "headline": "Inception of the Grammy Awards",
      "text": "The Grammy Awards were established to honor artistic achievement, technical proficiency, and overall excellence in the recording industry, without regard to album sales, chart position, or critical reception. The first ceremony took place in 1959.",
      "date": "1959"
    },
    {
      "headline": "First Grammy Award for Album of the Year",
      "text": "The first Grammy Award for Album of the Year was presented at the 1st Annual Grammy Awards in 1959. The award was given to Henry Mancini for the album 'The Music from Peter Gunn'.",
      "date": "1959"
    },
    {
      "headline": "Stevie Wonder's Historic Wins",
      "text": "Stevie Wonder became the first artist to win the Album of the Year award three times, with wins in 1974 for 'Innervisions', 1975 for 'Fulfillingness' First Finale', and 1977 for 'Songs in the Key of Life'.",
      "date": "1977"
    },
    {
      "headline": "First Female Solo Artist to Win",
      "text": "Judy Garland was the first female solo artist to win the Album of the Year award in 1962 for her live recording 'Judy at Carnegie Hall'.",
      "date": "1962"
    },
    {
      "headline": "First Non-English Album to Win",
      "text": "The first non-English album to win Album of the Year was 'Come Away with Me' by Norah Jones in 2003, which included songs in English and one in French.",
      "date": "2003"
    },
    {
      "headline": "First Hip-Hop Album to Win",
      "text": "Lauryn Hill's 'The Miseducation of Lauryn Hill' became the first hip-hop album to win the Album of the Year award in 1999.",
      "date": "1999"
    },
    {
      "headline": "First Album of the Year Win for a Streaming-Only Album",
      "text": "In 2017, '24K Magic' by Bruno Mars became the first album to win Album of the Year that was also available on streaming platforms at the time of its release.",
      "date": "2017"
    },
    {
      "headline": "Billie Eilish's Historic Win",
      "text": "In 2020, Billie Eilish became the youngest solo artist to win Album of the Year for her album 'When We All Fall Asleep, Where Do We Go?' at the age of 18.",
      "date": "2020"
    }
  ]
}

