    {
      "headline": "Founding of Tenochtitlan",
      "text": "Tenochtitlan was founded on March 13, 1325, on an island in Lake Texcoco in the Valley of Mexico. This date was chosen in 1925 to celebrate the 600th anniversary of the city.",
      "date": "1325-03-13"
    },
    {
      "headline": "Tenochtitlan Becomes Capital of the Aztec Empire",
      "text": "In the 15th century, Tenochtitlan became the capital of the expanding Aztec Empire, serving as the political, economic, and cultural center.",
      "date": "1400"
    },
    {
      "headline": "Construction of the Templo Mayor",
      "text": "The Templo Mayor, the main temple of Tenochtitlan, was constructed and expanded multiple times, with significant construction phases occurring in the 15th century.",
      "date": "1487"
    },
    {
      "headline": "Spanish Conquest of Tenochtitlan",
      "text": "On August 13, 1521, Tenochtitlan was captured by the Spanish conquistadors led by Hernán Cortés, with the help of their indigenous allies, including the Tlaxcaltec.",
      "date": "1521-08-13"
    },
    {
      "headline": "Destruction and Rebuilding as Mexico City",
      "text": "Following its capture, Tenochtitlan was largely destroyed by the Spanish, and the site was rebuilt as Mexico City, which became the capital of New Spain.",
      "date": "1521"
    }
  ]
}

