{
  "timeline": [
    {
      "headline": "Viking Raids on West Francia",
      "text": "Beginning in the late 8th century, Norse Viking settlers from Denmark, Norway, and Sweden began raiding the northern coast of what is now France, targeting the region of West Francia.",
      "date": "-0799"
    },
    {
      "headline": "Siege of Chartres",
      "text": "In 911, the Scandinavian Viking leader Rollo led a siege on the city of Chartres in West Francia. This event was pivotal in the eventual establishment of the Normans in the region.",
      "date": "0911"
    },
    {
      "headline": "Treaty of Saint-Clair-sur-Epte",
      "text": "In 911, following the siege of Chartres, Rollo agreed to swear fealty to King Charles III of West Francia. This agreement, known as the Treaty of Saint-Clair-sur-Epte, granted Rollo land in what would become the County of Rouen.",
      "date": "0911"
    },
    {
      "headline": "Formation of the Duchy of Normandy",
      "text": "Through kinship and expansion, the County of Rouen grew into the Duchy of Normandy in the early 10th century. This marked the beginning of the Norman identity, characterized by the intermixing of Norse and Frankish cultures.",
      "date": "0911-0950"
    },
    {
      "headline": "Norman Conquest of England",
      "text": "In 1066, the Normans, led by Duke William II of Normandy, invaded and conquered England. This event, known as the Norman Conquest, significantly impacted English culture, language, and governance.",
      "date": "1066"
    },
    {
      "headline": "Norman Expansion in Southern Italy",
      "text": "During the 11th century, Norman adventurers and mercenaries expanded into Southern Italy, establishing control over regions such as Sicily and Naples.",
      "date": "1050-1100"
    },
    {
      "headline": "Norman Influence in the Crusades",
      "text": "The Normans played a significant role in the Crusades during the late 11th and early 12th centuries, contributing to the establishment of Crusader states in the Levant.",
      "date": "1096-1204"
    }
  ]
}

