{
  "timeline": [
    {
      "headline": "Foundation of Medina",
      "text": "Medina, originally known as Yathrib, is one of the oldest cities in the Arabian Peninsula. It was established long before the advent of Islam.",
      "date": "-1500"
    },
    {
      "headline": "Migration of Prophet Muhammad",
      "text": "In 622 CE, Prophet Muhammad migrated from Mecca to Yathrib, which was later renamed Medina. This event, known as the Hijra, marks the beginning of the Islamic calendar.",
      "date": "0622"
    },
    {
      "headline": "Battle of Badr",
      "text": "The Battle of Badr took place in 624 CE near Medina. It was a key battle in early Islamic history where Muslims, led by Prophet Muhammad, achieved a significant victory.",
      "date": "0624"
    },
    {
      "headline": "Battle of Uhud",
      "text": "In 625 CE, the Battle of Uhud was fought between the early Muslims and the Quraysh of Mecca. It took place near Mount Uhud, close to Medina.",
      "date": "0625"
    },
    {
      "headline": "Treaty of Hudaybiyyah",
      "text": "In 628 CE, the Treaty of Hudaybiyyah was signed between the Muslims of Medina and the Quraysh of Mecca, allowing for a period of peace.",
      "date": "0628"
    },
    {
      "headline": "Conquest of Mecca",
      "text": "In 630 CE, Prophet Muhammad and his followers from Medina conquered Mecca, marking a significant turning point in Islamic history.",
      "date": "0630"
    },
    {
      "headline": "Death of Prophet Muhammad",
      "text": "Prophet Muhammad passed away in Medina in 632 CE. His death marked the end of the prophetic era in Islam.",
      "date": "0632"
    },
    {
      "headline": "Establishment of the Rashidun Caliphate",
      "text": "Following the death of Prophet Muhammad, the Rashidun Caliphate was established in Medina, with Abu Bakr as the first caliph.",
      "date": "0632"
    },
    {
      "headline": "Battle of the Trench",
      "text": "In 627 CE, the Battle of the Trench was fought in Medina. The city was besieged by a coalition of tribes, but the Muslims successfully defended it.",
      "date": "0627"
    },
    {
      "headline": "Medina as a Center of Islamic Learning",
      "text": "Throughout the early Islamic period, Medina became a center of Islamic learning and jurisprudence, attracting scholars from across the Muslim world.",
      "date": "0700"
    }
  ]
}

