{
  "timeline": [
    {
      "headline": "Conceptualization of the Panopticon",
      "text": "In 1785, Jeremy Bentham conceptualized the design of the Panopticon, a type of institutional building intended to allow all inmates to be observed by a single watchman without them being able to tell whether or not they are being watched.",
      "date": "1785"
    },
    {
      "headline": "Publication of 'Panopticon; or, The Inspection-House'",
      "text": "In 1791, Jeremy Bentham published 'Panopticon; or, The Inspection-House', a series of letters detailing his ideas for the Panopticon and its potential applications in prisons, schools, and other institutions.",
      "date": "1791"
    },
    {
      "headline": "Bentham's Efforts to Build a Panopticon",
      "text": "Throughout the 1790s, Bentham made efforts to have a Panopticon built, including negotiations with the British government. However, these efforts ultimately did not result in the construction of a Panopticon during his lifetime.",
      "date": "1790"
    },
    {
      "headline": "Influence on Prison Design",
      "text": "In the 19th century, the Panopticon concept influenced the design of several prisons, including the Eastern State Penitentiary in Philadelphia, which opened in 1829, and the Pentonville Prison in London, which opened in 1842.",
      "date": "1829"
    },
    {
      "headline": "Michel Foucault's Analysis",
      "text": "In 1975, French philosopher Michel Foucault analyzed the Panopticon in his book 'Discipline and Punish', using it as a metaphor for modern disciplinary societies and their pervasive inclination to observe and normalize.",
      "date": "1975"
    }
  ]
}

