{
  "timeline": [
    {
      "headline": "UN Partition Plan",
      "text": "On November 29, 1947, the United Nations General Assembly adopted Resolution 181, recommending the partition of Palestine into independent Arab and Jewish states and a special international regime for the city of Jerusalem.",
      "date": "1947-11-29"
    },
    {
      "headline": "Civil War Begins",
      "text": "The civil war in Mandatory Palestine began on November 30, 1947, the day after the UN partition plan was adopted, with violence erupting between Jewish and Arab communities.",
      "date": "1947-11-30"
    },
    {
      "headline": "British Withdrawal",
      "text": "On May 14, 1948, the British Mandate over Palestine officially ended, and British forces withdrew from the region.",
      "date": "1948-05-14"
    },
    {
      "headline": "Declaration of the State of Israel",
      "text": "On May 14, 1948, David Ben-Gurion, the head of the Jewish Agency, proclaimed the establishment of the State of Israel.",
      "date": "1948-05-14"
    },
    {
      "headline": "Arab Invasion",
      "text": "On May 15, 1948, the day after Israel declared independence, neighboring Arab states, including Egypt, Transjordan, Syria, and Iraq, invaded the newly declared State of Israel, marking the beginning of the Arab-Israeli War.",
      "date": "1948-05-15"
    },
    {
      "headline": "Operation Danny",
      "text": "From July 9 to July 19, 1948, Israeli forces launched Operation Danny, capturing the towns of Lydda and Ramle, leading to the expulsion of thousands of Palestinian Arabs.",
      "date": "1948-07-09"
    },
    {
      "headline": "First Truce",
      "text": "A United Nations-mediated truce came into effect on June 11, 1948, lasting for four weeks.",
      "date": "1948-06-11"
    },
    {
      "headline": "Second Truce",
      "text": "A second truce was declared on July 18, 1948, after renewed fighting following the first truce.",
      "date": "1948-07-18"
    },
    {
      "headline": "Operation Yoav",
      "text": "From October 15 to October 22, 1948, Israeli forces conducted Operation Yoav, breaking the Egyptian siege of the Negev and capturing Beersheba.",
      "date": "1948-10-15"
    },
    {
      "headline": "Operation Hiram",
      "text": "From October 29 to October 31, 1948, Israeli forces launched Operation Hiram, capturing the Upper Galilee region.",
      "date": "1948-10-29"
    },
    {
      "headline": "Armistice Agreements",
      "text": "Between February and July 1949, Israel signed armistice agreements with Egypt, Lebanon, Jordan, and Syria, effectively ending the 1948 Palestine war.",
      "date": "1949"
    }
  ]
}

