    {
      "headline": "Composition of the Book of Revelation",
      "text": "The Book of Revelation, where the number of the beast is mentioned, is traditionally believed to have been written by John of Patmos. It is estimated to have been composed around 95 AD.",
      "date": "0095"
    },
    {
      "headline": "Earliest Manuscripts",
      "text": "The earliest known manuscripts of the New Testament, including the Book of Revelation, date back to the 2nd century. These manuscripts contain the number of the beast as 666.",
      "date": "0200"
    },
    {
      "headline": "Papyrus 115 Discovery",
      "text": "Papyrus 115, an ancient manuscript discovered in the 20th century, dates back to the 3rd century and contains the number of the beast as 616, providing a significant variant to the traditionally accepted 666.",
      "date": "0200"
    },
    {
      "headline": "Codex Ephraemi Rescriptus",
      "text": "The Codex Ephraemi Rescriptus, a 5th-century manuscript, also records the number of the beast as 616, supporting the variant reading found in Papyrus 115.",
      "date": "0450"
    },
    {
      "headline": "Novum Testamentum Graece",
      "text": "The Novum Testamentum Graece, a critical edition of the Greek New Testament, notes the variant reading of 616 for the number of the beast, acknowledging the textual variations found in ancient manuscripts.",
      "date": "1881"
    }
  ]
}

