{
  "timeline": [
    {
      "headline": "Start of the Guadalcanal Campaign",
      "text": "The Guadalcanal Campaign began on 7 August 1942 when Allied forces, primarily from the United States, launched an amphibious landing on the islands of Guadalcanal, Tulagi, and Florida in the Solomon Islands.",
      "date": "1942-08-07"
    },
    {
      "headline": "Battle of Savo Island",
      "text": "On 8-9 August 1942, the Battle of Savo Island took place. It was a night naval battle in which Japanese forces achieved a significant victory, sinking four Allied cruisers.",
      "date": "1942-08-08"
    },
    {
      "headline": "Battle of the Eastern Solomons",
      "text": "The Battle of the Eastern Solomons occurred on 24-25 August 1942. It was a carrier battle in which the Allies managed to repel a Japanese counter-offensive, sinking the Japanese light carrier Ryūjō.",
      "date": "1942-08-24"
    },
    {
      "headline": "Battle of Edson's Ridge",
      "text": "From 12-14 September 1942, the Battle of Edson's Ridge, also known as the Battle of Bloody Ridge, took place. U.S. Marines successfully defended Henderson Field against a Japanese attack.",
      "date": "1942-09-12"
    },
    {
      "headline": "Battle of Cape Esperance",
      "text": "On 11-12 October 1942, the Battle of Cape Esperance was fought. It was a naval battle in which U.S. forces intercepted and defeated a Japanese reinforcement convoy.",
      "date": "1942-10-11"
    },
    {
      "headline": "Battle of the Santa Cruz Islands",
      "text": "The Battle of the Santa Cruz Islands occurred on 25-27 October 1942. It was a carrier battle where the Japanese inflicted heavy damage on the U.S. fleet but failed to achieve a decisive victory.",
      "date": "1942-10-25"
    },
    {
      "headline": "Naval Battle of Guadalcanal",
      "text": "From 12-15 November 1942, the Naval Battle of Guadalcanal took place. It was a series of air and sea engagements that resulted in a strategic victory for the Allies, preventing Japanese forces from retaking Henderson Field.",
      "date": "1942-11-12"
    },
    {
      "headline": "Battle of Tassafaronga",
      "text": "On 30 November 1942, the Battle of Tassafaronga was fought. Japanese destroyers successfully delivered supplies to their forces on Guadalcanal despite suffering heavy losses.",
      "date": "1942-11-30"
    },
    {
      "headline": "End of the Guadalcanal Campaign",
      "text": "The Guadalcanal Campaign ended on 9 February 1943 when Japanese forces completed their evacuation from the island, marking a significant strategic victory for the Allies in the Pacific theater.",
      "date": "1943-02-09"
    }
  ]
}

