{
  "timeline": [
    {
      "headline": "Emergence of Postmodern Architecture",
      "text": "In the late 1960s, postmodern architecture began to emerge as a reaction against the austerity, formality, and lack of variety of modern architecture, particularly the International Style advocated by Le Corbusier and Ludwig Mies van der Rohe.",
      "date": "1960"
    },
    {
      "headline": "Publication of 'The Postmodern Condition'",
      "text": "In 1979, Jean-François Lyotard published 'The Postmodern Condition: A Report on Knowledge', which is considered one of the foundational texts of postmodern theory. It introduced the idea of the 'incredulity towards metanarratives'.",
      "date": "1979"
    },
    {
      "headline": "Postmodernism in Literature",
      "text": "Postmodern literature emerged in the mid-20th century, characterized by reliance on narrative techniques such as fragmentation, paradox, and unreliable narrators. Notable works include Thomas Pynchon's 'Gravity's Rainbow' (1973) and Don DeLillo's 'White Noise' (1985).",
      "date": "1973"
    },
    {
      "headline": "Postmodernism in Art",
      "text": "Postmodern art emerged as a reaction against modernism and its principles. It is characterized by a deliberate mixing of different styles and media, and a focus on irony and parody. This movement gained prominence in the 1970s and 1980s.",
      "date": "1970"
    },
    {
      "headline": "Postmodernism in Music",
      "text": "Postmodern music emerged in the late 20th century, characterized by the blending of different styles and genres, and the use of pastiche and irony. It challenges the boundaries between 'high' and 'low' art.",
      "date": "1980"
    },
    {
      "headline": "Postmodernism in Philosophy",
      "text": "Postmodern philosophy is a late 20th-century movement characterized by broad skepticism, subjectivism, or relativism; a general suspicion of reason; and an acute sensitivity to the role of ideology in asserting and maintaining political and economic power.",
      "date": "1980"
    },
    {
      "headline": "Postmodernism in Film",
      "text": "Postmodern film emerged in the late 20th century, characterized by the use of pastiche, intertextuality, and a self-reflexive approach. Films such as Quentin Tarantino's 'Pulp Fiction' (1994) are considered quintessentially postmodern.",
      "date": "1994"
    }
  ]
}

