    {
      "headline": "Formation of The Black Keys",
      "text": "The Black Keys were formed in Akron, Ohio in 2001 by Dan Auerbach and Patrick Carney. The duo began as an independent act, recording music in basements and self-producing their records.",
      "date": "2001"
    },
    {
      "headline": "Release of Debut Album 'The Big Come Up'",
      "text": "The Black Keys released their debut album, 'The Big Come Up', in 2002. The album was recorded in Carney's basement and showcased their raw blues rock sound.",
      "date": "2002"
    },
    {
      "headline": "Release of 'Thickfreakness'",
      "text": "In 2003, The Black Keys released their second studio album, 'Thickfreakness'. The album was recorded in a single 14-hour session in Carney's basement.",
      "date": "2003"
    },
    {
      "headline": "Release of 'Rubber Factory'",
      "text": "The Black Keys released their third studio album, 'Rubber Factory', in 2004. The album was recorded in an abandoned tire factory in Akron.",
      "date": "2004"
    },
    {
      "headline": "Release of 'Magic Potion'",
      "text": "In 2006, The Black Keys released their fourth studio album, 'Magic Potion'. This was their first album to be recorded in a professional studio.",
      "date": "2006"
    },
    {
      "headline": "Release of 'Attack & Release'",
      "text": "The Black Keys released 'Attack & Release' in 2008. The album was produced by Danger Mouse and marked a shift towards a more polished sound.",
      "date": "2008"
    },
    {
      "headline": "Breakthrough with 'Brothers'",
      "text": "In 2010, The Black Keys released 'Brothers', which became their commercial breakthrough. The album won three Grammy Awards, including Best Alternative Music Album.",
      "date": "2010"
    },
    {
      "headline": "Release of 'El Camino'",
      "text": "The Black Keys released 'El Camino' in 2011. The album was a critical and commercial success, earning the duo three Grammy Awards.",
      "date": "2011"
    },
    {
      "headline": "Release of 'Turn Blue'",
      "text": "In 2014, The Black Keys released their eighth studio album, 'Turn Blue'. The album debuted at number one on the Billboard 200 chart.",
      "date": "2014"
    },
    {
      "headline": "Release of 'Let's Rock'",
      "text": "The Black Keys released 'Let's Rock' in 2019. The album marked a return to their roots with a more straightforward rock sound.",
      "date": "2019"
    },
    {
      "headline": "Release of 'Delta Kream'",
      "text": "In 2021, The Black Keys released 'Delta Kream', an album of hill country blues covers, paying homage to their blues influences.",
      "date": "2021"
