{
  "timeline": [
    {
      "headline": "Settlement in Anatolia",
      "text": "The Hittites, an Indo-European people, settled in modern-day Turkey in the early 2nd millennium BC, forming a series of polities in north-central Anatolia.",
      "date": "-02000"
    },
    {
      "headline": "Formation of the Kingdom of Kussara",
      "text": "The Hittites established the Kingdom of Kussara, one of the early polities in the region, which played a significant role in the formation of the Hittite state.",
      "date": "-01800"
    },
    {
      "headline": "Establishment of the Hittite Old Kingdom",
      "text": "The Hittite Old Kingdom was established around 1650 BC, marking the beginning of a centralized Hittite state under the rule of Hattusili I.",
      "date": "-01650"
    },
    {
      "headline": "Reign of Hattusili I",
      "text": "Hattusili I reigned from approximately 1650 BC to 1620 BC, consolidating power and expanding the Hittite territories.",
      "date": "-01650"
    },
    {
      "headline": "Reign of Mursili I",
      "text": "Mursili I, who reigned from around 1620 BC to 1590 BC, is known for his conquest of Babylon, which marked a significant expansion of Hittite influence.",
      "date": "-01620"
    },
    {
      "headline": "Hittite Middle Kingdom",
      "text": "The period following the Old Kingdom, known as the Hittite Middle Kingdom, was marked by internal strife and less centralized control.",
      "date": "-01500"
    },
    {
      "headline": "Reign of Tudhaliya I",
      "text": "Tudhaliya I, who reigned around 1430 BC, began the process of re-centralizing the Hittite state, setting the stage for the New Kingdom.",
      "date": "-01430"
    },
    {
      "headline": "Hittite New Kingdom (Empire Period)",
      "text": "The Hittite New Kingdom, also known as the Empire Period, began around 1400 BC, characterized by territorial expansion and increased political power.",
      "date": "-01400"
    },
    {
      "headline": "Reign of Šuppiluliuma I",
      "text": "Šuppiluliuma I reigned from approximately 1350 BC to 1322 BC, during which the Hittite Empire reached its peak, encompassing most of Anatolia and parts of the northern Levant and Upper Mesopotamia.",
      "date": "-01350"
    },
    {
      "headline": "Battle of Kadesh",
      "text": "The Battle of Kadesh, fought around 1274 BC between the Hittites under Muwatalli II and the Egyptians under Ramses II, is one of the most famous battles of the ancient world.",
      "date": "-01274"
    },
    {
      "headline": "Collapse of the Hittite Empire",
      "text": "The Hittite Empire collapsed around 1178 BC due to a combination of internal strife, invasions, and economic difficulties, marking the end of Hittite dominance in the region.",
      "date": "-01178"
    }
  ]
}

{
  "timeline": [
