{
  "timeline": [
    {
      "headline": "Mycenaean Greek Period Begins",
      "text": "The Mycenaean Greek period, the earliest attested phase of the Greek language, begins around 1500 BC. This period is characterized by the use of Linear B script.",
      "date": "-1500"
    },
    {
      "headline": "End of Mycenaean Civilization",
      "text": "Around 1100 BC, the Mycenaean civilization collapses, marking the end of the Mycenaean Greek period and the beginning of the Greek Dark Ages.",
      "date": "-1100"
    },
    {
      "headline": "Greek Dark Ages",
      "text": "The Greek Dark Ages, a period of decline and reduced literacy, spans from approximately 1100 BC to 800 BC. During this time, the use of Linear B script disappears.",
      "date": "-1100"
    },
    {
      "headline": "Archaic Period Begins",
      "text": "Around 800 BC, the Archaic period begins, marked by the reintroduction of writing with the Greek alphabet and the composition of the Homeric epics.",
      "date": "-0800"
    },
    {
      "headline": "Homeric Epics Composed",
      "text": "The Iliad and the Odyssey, attributed to the poet Homer, are composed during the 8th century BC, becoming foundational works of ancient Greek literature.",
      "date": "-0800"
    },
    {
      "headline": "Classical Period Begins",
      "text": "The Classical period of Ancient Greek begins around 500 BC, characterized by significant developments in art, philosophy, and politics.",
      "date": "-0500"
    },
    {
      "headline": "Golden Age of Athens",
      "text": "The Golden Age of Athens occurs in the 5th century BC, marked by the leadership of Pericles and the construction of the Parthenon.",
      "date": "-0500"
    },
    {
      "headline": "Peloponnesian War",
      "text": "The Peloponnesian War, a conflict between Athens and Sparta, takes place from 431 BC to 404 BC, leading to the eventual downfall of Athens.",
      "date": "-0431"
    },
    {
      "headline": "End of Classical Period",
      "text": "The Classical period ends around 300 BC, transitioning into the Hellenistic period following the conquests of Alexander the Great.",
      "date": "-0300"
    }
  ]
}

