    {
      "headline": "Change of Name to Akhenaten",
      "text": "In the fifth year of his reign, around 1348 BCE, Amenhotep IV changed his name to Akhenaten, meaning 'Effective for Aten', marking the beginning of his religious reforms.",
      "date": "-1348"
    },
    {
      "headline": "Religious Reforms and Atenism",
      "text": "Akhenaten introduced Atenism, a monotheistic worship of the sun disk Aten, and began to diminish the traditional polytheistic practices of Egypt.",
      "date": "-1348"
    },
    {
      "headline": "Founding of Akhetaten",
      "text": "Around 1346 BCE, Akhenaten founded a new capital city, Akhetaten (modern-day Amarna), dedicated to the worship of Aten.",
      "date": "-1346"
    },
    {
      "headline": "Amarna Period",
      "text": "The period of Akhenaten's reign, known as the Amarna Period, was marked by significant artistic and cultural changes, including more naturalistic art styles.",
      "date": "-1346"
    },
    {
      "headline": "Death of Akhenaten",
      "text": "Akhenaten died around 1336 BCE, ending his reign and leading to the restoration of traditional religious practices by his successors.",
      "date": "-1336"
    }
  ]
}

