    },
    {
      "headline": "Indian Independence",
      "text": "On 15 August 1947, the first Prime Minister of India, Jawaharlal Nehru, raised the Indian national flag above the Lahori Gate of the Red Fort, marking the country's independence from British rule.",
      "date": "1947-08-15"
