  "timeline": [
    {
      "headline": "Birth of Michael Faraday",
      "text": "Michael Faraday was born on September 22, 1791, in Newington Butts, England.",
      "date": "1791-09-22"
    },
    {
      "headline": "Apprenticeship to a Bookbinder",
      "text": "In 1805, at the age of 14, Faraday began an apprenticeship with George Riebau, a local bookbinder and bookseller.",
      "date": "1805"
    },
    {
      "headline": "Attends Humphry Davy's Lectures",
      "text": "In 1812, Faraday attended lectures by the eminent chemist Humphry Davy at the Royal Institution, which inspired him to pursue a career in science.",
      "date": "1812"
    },
    {
      "headline": "Joins the Royal Institution",
      "text": "In 1813, Faraday was appointed as a chemical assistant at the Royal Institution of Great Britain.",
      "date": "1813"
    },
    {
      "headline": "European Tour with Humphry Davy",
      "text": "From 1813 to 1815, Faraday accompanied Humphry Davy on a European tour, which provided him with valuable scientific exposure.",
      "date": "1813"
    },
    {
      "headline": "Discovery of Electromagnetic Rotation",
      "text": "In 1821, Faraday discovered the principle of electromagnetic rotation, which is the basis for the electric motor.",
      "date": "1821"
    },
    {
      "headline": "Discovery of Electromagnetic Induction",
      "text": "In 1831, Faraday discovered electromagnetic induction, demonstrating that a changing magnetic field produces an electric current.",
      "date": "1831"
    },
    {
      "headline": "Faraday's Laws of Electrolysis",
      "text": "In 1834, Faraday formulated the laws of electrolysis, which describe the quantitative aspects of electrochemical reactions.",
      "date": "1834"
    },
    {
      "headline": "Discovery of Diamagnetism",
      "text": "In 1845, Faraday discovered diamagnetism, a property of materials that causes them to be repelled by magnetic fields.",
      "date": "1845"
    },
    {
      "headline": "Faraday Effect",
      "text": "In 1845, Faraday discovered that a magnetic field can rotate the plane of polarization of light, known as the Faraday Effect.",
      "date": "1845"
    },
    {
      "headline": "Retirement from the Royal Institution",
      "text": "In 1858, Faraday retired from his position at the Royal Institution due to declining health.",
      "date": "1858"
    },
    {
      "headline": "Death of Michael Faraday",
      "text": "Michael Faraday passed away on August 25, 1867, in Hampton Court, Surrey, England.",
      "date": "1867-08-25"
    }
  ]
}

