    {
      "headline": "Original Construction",
      "text": "The original Palace of Westminster was built in the 11th century, serving as the primary residence of the Kings of England until a fire destroyed much of the complex in 1512.",
      "date": "1000"
    },
    {
      "headline": "Fire of 1512",
      "text": "In 1512, a fire destroyed much of the original Palace of Westminster, leading to its transformation into the home of the Parliament of England.",
      "date": "1512"
    },
    {
      "headline": "Fire of 1834",
      "text": "On October 16, 1834, a fire ravaged the Palace of Westminster, destroying the majority of the structure, including the House of Commons and the House of Lords.",
      "date": "1834-10-16"
    },
    {
      "headline": "Reconstruction Begins",
      "text": "In 1840, construction began on the new Palace of Westminster, designed by architect Charles Barry with the assistance of Augustus Pugin.",
      "date": "1840"
    },
    {
      "headline": "Completion of the New Palace",
      "text": "The reconstruction of the Palace of Westminster was largely completed in 1876, although some work continued into the 20th century.",
      "date": "1876"
    },
    {
      "headline": "Grade I Listing",
      "text": "In 1970, the Palace of Westminster was designated as a Grade I listed building, recognizing its exceptional architectural and historic interest.",
      "date": "1970"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1987, the Palace of Westminster, along with Westminster Abbey and Saint Margaret's Church, was designated a UNESCO World Heritage Site.",
      "date": "1987"
    }
  ]
}

