{
  "timeline": [
    {
      "headline": "Birth of Menachem Begin",
      "text": "Menachem Begin was born on August 16, 1913, in Brest-Litovsk, which was then part of the Russian Empire.",
      "date": "1913-08-16"
    },
    {
      "headline": "Joining Betar",
      "text": "In 1929, Menachem Begin joined the Betar youth movement, which was a Revisionist Zionist group.",
      "date": "1929"
    },
    {
      "headline": "Graduation from University of Warsaw",
      "text": "Menachem Begin graduated from the University of Warsaw with a law degree in 1935.",
      "date": "1935"
    },
    {
      "headline": "Leader of Betar in Poland",
      "text": "In 1939, Begin became the head of Betar in Poland, leading the organization until the outbreak of World War II.",
      "date": "1939"
    },
    {
      "headline": "Arrest by Soviet authorities",
      "text": "In 1940, Begin was arrested by Soviet authorities and sentenced to eight years in a labor camp in Siberia.",
      "date": "1940"
    },
    {
      "headline": "Release from Soviet labor camp",
      "text": "Menachem Begin was released from the Soviet labor camp in 1941 following the Sikorski-Mayski Agreement.",
      "date": "1941"
    },
    {
      "headline": "Joining the Polish Anders' Army",
      "text": "After his release, Begin joined the Polish Anders' Army and traveled with them to the Middle East.",
      "date": "1942"
    },
    {
      "headline": "Commander of the Irgun",
      "text": "In 1944, Menachem Begin became the commander of the Irgun, a Zionist paramilitary organization.",
      "date": "1944"
    },
    {
      "headline": "Declaration of Revolt against British rule",
      "text": "On February 1, 1944, Begin declared a revolt against British rule in Palestine.",
      "date": "1944-02-01"
    },
    {
      "headline": "King David Hotel bombing",
      "text": "On July 22, 1946, the Irgun, under Begin's command, carried out the King David Hotel bombing, targeting the British administrative headquarters.",
      "date": "1946-07-22"
    },
    {
      "headline": "Founding of Herut",
      "text": "In 1948, after the establishment of the State of Israel, Begin founded the Herut party.",
      "date": "1948"
    },
    {
      "headline": "Elected to the Knesset",
      "text": "Menachem Begin was elected to the first Knesset in 1949 as a member of Herut.",
      "date": "1949"
    },
    {
      "headline": "Formation of Likud",
      "text": "In 1973, Begin played a key role in the formation of the Likud party, a coalition of right-wing parties.",
      "date": "1973"
    },
    {
      "headline": "Prime Minister of Israel",
      "text": "Menachem Begin became the Prime Minister of Israel on June 20, 1977, after Likud's victory in the elections.",
      "date": "1977-06-20"
    },
    {
      "headline": "Signing of the Camp David Accords",
      "text": "On September 17, 1978, Begin signed the Camp David Accords with Egyptian President Anwar Sadat, leading to a peace treaty between Israel and Egypt.",
      "date": "1978-09-17"
    },
    {
      "headline": "Nobel Peace Prize",
      "text": "In 1978, Menachem Begin was awarded the Nobel Peace Prize, along with Anwar Sadat, for their efforts in achieving peace between Israel and Egypt.",
      "date": "1978"
    },
    {
      "headline": "Israel-Egypt Peace Treaty",
      "text": "On March 26, 1979, Begin signed the Israel-Egypt Peace Treaty, formally ending the state of war between the two countries.",
      "date": "1979-03-26"
    },
    {
      "headline": "Operation Opera",
      "text": "On June 7, 1981, Begin ordered the Israeli Air Force to destroy the Osirak nuclear reactor in Iraq, an operation known as Operation Opera.",
      "date": "1981-06-07"
    },
    {
      "headline": "Resignation as Prime Minister",
      "text": "Menachem Begin resigned as Prime Minister of Israel on October 10, 1983, citing personal reasons.",
      "date": "1983-10-10"
    },
    {
      "headline": "Death of Menachem Begin",
      "text": "Menachem Begin passed away on March 9, 1992, in Tel Aviv, Israel.",
      "date": "1992-03-09"
    }
  ]
}

