{
  "timeline": [
    {
      "headline": "Origin of the Term 'Shibboleth'",
      "text": "The term 'shibboleth' originates from the Hebrew Bible, specifically in the Book of Judges 12:5-6. It was used as a linguistic test by the Gileadites to identify and kill fleeing Ephraimites, who could not pronounce the word correctly. This event is estimated to have occurred around 1100 BCE.",
      "date": "-1100"
    },
    {
      "headline": "Use in the American Civil War",
      "text": "During the American Civil War (1861-1865), soldiers used shibboleths to identify friend from foe. For instance, the pronunciation of certain words could reveal whether someone was from the North or the South.",
      "date": "1861"
    },
    {
      "headline": "World War II Shibboleths",
      "text": "In World War II, shibboleths were used by American soldiers to identify Japanese infiltrators. The word 'lollapalooza' was used because it was difficult for non-native English speakers to pronounce correctly.",
      "date": "1941"
    },
    {
      "headline": "Modern Use in Computer Security",
      "text": "In modern times, the concept of a shibboleth has been adapted for use in computer security. It refers to a system that allows for the sharing of resources across security domains, often used in federated identity systems.",
      "date": "2000"
    }
  ]
}

