    {
      "headline": "Discovery of Penicillin",
      "text": "In 1928, Alexander Fleming discovered penicillin, the first true antibiotic, which marked the beginning of modern antibiotics.",
      "date": "1928"
    },
    {
      "headline": "Development of Penicillin for Medical Use",
      "text": "In the late 1930s and early 1940s, researchers including Howard Florey, Ernst Boris Chain, and Norman Heatley developed methods to produce penicillin for medical use, leading to its widespread use during World War II.",
      "date": "1940"
    },
    {
      "headline": "Introduction of Streptomycin",
      "text": "In 1943, Selman Waksman and his team discovered streptomycin, the first antibiotic effective against tuberculosis, which expanded the range of treatable bacterial infections.",
      "date": "1943"
    },
    {
      "headline": "Golden Age of Antibiotic Discovery",
      "text": "The period from the 1940s to the 1960s is known as the 'Golden Age of Antibiotic Discovery,' during which many new antibiotics were discovered and developed, including tetracyclines, macrolides, and cephalosporins.",
      "date": "1940-1960"
    },
    {
      "headline": "Emergence of Antibiotic Resistance",
      "text": "By the 1970s, antibiotic resistance began to emerge as a significant public health concern, as bacteria evolved mechanisms to resist the effects of antibiotics.",
      "date": "1970"
    },
    {
      "headline": "Development of New Antibiotics",
      "text": "In response to antibiotic resistance, new classes of antibiotics, such as fluoroquinolones and carbapenems, were developed in the 1980s and 1990s.",
      "date": "1980-1990"
    },
    {
      "headline": "Global Action Plan on Antimicrobial Resistance",
      "text": "In 2015, the World Health Organization adopted a Global Action Plan on Antimicrobial Resistance to combat the growing threat of antibiotic resistance worldwide.",
      "date": "2015"
    }
  ]
}

