{
  "timeline": [
    {
      "headline": "First Use of Ultrasound in Medicine",
      "text": "In 1953, Dr. Inge Edler and Dr. Carl Hellmuth Hertz used ultrasound technology to examine the heart, marking the first use of ultrasound in medicine.",
      "date": "1953"
    },
    {
      "headline": "Development of M-mode Echocardiography",
      "text": "In the late 1950s, M-mode (motion mode) echocardiography was developed, allowing for the recording of heart motion over time.",
      "date": "1950"
    },
    {
      "headline": "Introduction of 2D Echocardiography",
      "text": "In the 1970s, two-dimensional (2D) echocardiography was introduced, providing a more comprehensive view of the heart's structure and function.",
      "date": "1970"
    },
    {
      "headline": "Advancement with Doppler Echocardiography",
      "text": "In the 1980s, Doppler echocardiography was developed, enabling the measurement of blood flow velocities within the heart.",
      "date": "1980"
    },
    {
      "headline": "Development of Transesophageal Echocardiography",
      "text": "In the late 1980s, transesophageal echocardiography (TEE) was developed, allowing for clearer images of the heart by inserting the ultrasound probe into the esophagus.",
      "date": "1980"
    },
    {
      "headline": "Introduction of 3D Echocardiography",
      "text": "In the 1990s, three-dimensional (3D) echocardiography was introduced, providing more detailed images of the heart's anatomy.",
      "date": "1990"
    },
    {
      "headline": "Advancements in Real-Time 3D Echocardiography",
      "text": "In the 2000s, real-time 3D echocardiography became more widely used, offering dynamic and detailed views of the heart in motion.",
      "date": "2000"
    }
  ]
}

