{
  "timeline": [
    {
      "headline": "Creation of Rogue",
      "text": "Rogue, the game that inspired the roguelike genre, was created by Michael Toy and Glenn Wichman in 1980. It was developed for Unix-based systems and featured procedurally generated dungeons and permadeath.",
      "date": "1980"
    },
    {
      "headline": "Release of Hack",
      "text": "Hack, a game inspired by Rogue, was released in 1982. It introduced new features and improvements over Rogue, contributing to the evolution of the roguelike genre.",
      "date": "1982"
    },
    {
      "headline": "Development of Moria",
      "text": "Moria, another early roguelike, was developed by Robert Alan Koeneke in 1983. It was inspired by J.R.R. Tolkien's Middle-earth and introduced a town level and a more complex dungeon structure.",
      "date": "1983"
    },
    {
      "headline": "Release of NetHack",
      "text": "NetHack, a successor to Hack, was first released in 1987. It became one of the most popular and enduring roguelikes, known for its depth and humor.",
      "date": "1987"
    },
    {
      "headline": "Introduction of Angband",
      "text": "Angband, a roguelike inspired by Moria, was released in 1990. It expanded on the features of Moria and became known for its large dungeons and complex gameplay.",
      "date": "1990"
    },
    {
      "headline": "Berlin Interpretation",
      "text": "In 2008, the Berlin Interpretation was established to define the key features of roguelike games, such as procedural generation, permadeath, and turn-based gameplay.",
      "date": "2008"
    },
    {
      "headline": "Rise of Roguelike Elements in Mainstream Games",
      "text": "In the 2010s, elements of roguelikes, such as procedural generation and permadeath, began to appear in mainstream games, leading to the creation of the 'roguelite' subgenre.",
      "date": "2010"
    }
  ]
}

