{
  "timeline": [
    {
      "headline": "Bitcoin Whitepaper Published",
      "text": "On October 31, 2008, Satoshi Nakamoto published the Bitcoin whitepaper titled 'Bitcoin: A Peer-to-Peer Electronic Cash System', outlining the concept of a decentralized digital currency.",
      "date": "2008-10-31"
    },
    {
      "headline": "Bitcoin Network Created",
      "text": "On January 3, 2009, the Bitcoin network was created when Nakamoto mined the genesis block of Bitcoin (block number 0), which had a reward of 50 bitcoins.",
      "date": "2009-01-03"
    },
    {
      "headline": "First Bitcoin Transaction",
      "text": "On January 12, 2009, the first Bitcoin transaction took place between Satoshi Nakamoto and Hal Finney, a computer scientist and cryptography activist.",
      "date": "2009-01-12"
    },
    {
      "headline": "Bitcoin Exchange Rate Established",
      "text": "In October 2009, NewLibertyStandard published the first Bitcoin exchange rate, listing the value of 1,309.03 BTC at $1 USD, based on the cost of electricity to run a computer that generated bitcoins.",
      "date": "2009-10"
    },
    {
      "headline": "First Real-World Bitcoin Transaction",
      "text": "On May 22, 2010, Laszlo Hanyecz made the first real-world transaction by purchasing two pizzas for 10,000 BTC, marking the first time Bitcoin was used to purchase a tangible good.",
      "date": "2010-05-22"
    },
    {
      "headline": "Bitcoin Reaches Parity with US Dollar",
      "text": "On February 9, 2011, Bitcoin reached parity with the US dollar for the first time, with 1 BTC equaling $1 USD.",
      "date": "2011-02-09"
    },
    {
      "headline": "Mt. Gox Hacked",
      "text": "In June 2011, the Mt. Gox Bitcoin exchange was hacked, resulting in the loss of thousands of bitcoins and causing a significant drop in Bitcoin's value.",
      "date": "2011-06"
    },
    {
      "headline": "Bitcoin Reaches $1,000",
      "text": "In November 2013, Bitcoin's price surged to over $1,000 for the first time, driven by increased interest and adoption.",
      "date": "2013-11"
    },
    {
      "headline": "Mt. Gox Files for Bankruptcy",
      "text": "On February 28, 2014, Mt. Gox, once the largest Bitcoin exchange, filed for bankruptcy after losing approximately 850,000 bitcoins, leading to a significant crisis in the Bitcoin community.",
      "date": "2014-02-28"
    },
    {
      "headline": "Bitcoin Halving Event",
      "text": "On July 9, 2016, Bitcoin underwent its second halving event, reducing the block reward from 25 BTC to 12.5 BTC, which is a scheduled event to control inflation.",
      "date": "2016-07-09"
    },
    {
      "headline": "Bitcoin Reaches All-Time High",
      "text": "On December 17, 2017, Bitcoin reached an all-time high price of nearly $20,000, driven by speculative trading and increased mainstream interest.",
      "date": "2017-12-17"
    },
    {
      "headline": "Bitcoin Halving Event",
      "text": "On May 11, 2020, Bitcoin underwent its third halving event, reducing the block reward from 12.5 BTC to 6.25 BTC, further controlling the supply of new bitcoins.",
      "date": "2020-05-11"
    },
    {
      "headline": "Bitcoin Reaches New All-Time High",
      "text": "On December 16, 2020, Bitcoin surpassed its previous all-time high, reaching over $20,000, as institutional investors began to show increased interest.",
      "date": "2020-12-16"
    },
    {
      "headline": "El Salvador Adopts Bitcoin as Legal Tender",
      "text": "On September 7, 2021, El Salvador became the first country to adopt Bitcoin as legal tender, allowing it to be used for all transactions alongside the US dollar.",
      "date": "2021-09-07"
    }
  ]
}

