{
  "timeline": [
    {
      "headline": "Outbreak of the Peloponnesian War",
      "text": "The Peloponnesian War began in 431 BCE, marking the start of a protracted conflict between Athens and Sparta and their respective allies.",
      "date": "-0431"
    },
    {
      "headline": "The Plague of Athens",
      "text": "In 430 BCE, a devastating plague struck Athens, killing a large portion of its population, including the influential leader Pericles.",
      "date": "-0430"
    },
    {
      "headline": "Peace of Nicias",
      "text": "In 421 BCE, the Peace of Nicias was signed, temporarily halting hostilities between Athens and Sparta, although it failed to resolve underlying tensions.",
      "date": "-0421"
    },
    {
      "headline": "Sicilian Expedition",
      "text": "In 415 BCE, Athens launched a massive military expedition to Sicily, aiming to conquer Syracuse. The campaign ended disastrously for Athens by 413 BCE.",
      "date": "-0415"
    },
    {
      "headline": "Defeat of the Athenian Expedition in Sicily",
      "text": "By 413 BCE, the Athenian forces in Sicily were decisively defeated, resulting in the loss of a significant portion of the Athenian fleet and army.",
      "date": "-0413"
    },
    {
      "headline": "Battle of Arginusae",
      "text": "In 406 BCE, the Athenian navy achieved a significant victory against the Spartans at the Battle of Arginusae, although it was marred by controversy over the failure to rescue shipwrecked sailors.",
      "date": "-0406"
    },
    {
      "headline": "Battle of Aegospotami",
      "text": "In 405 BCE, the Spartan fleet, led by Lysander, decisively defeated the Athenian navy at the Battle of Aegospotami, effectively ending Athenian naval power.",
      "date": "-0405"
    },
    {
      "headline": "Fall of Athens",
      "text": "In 404 BCE, Athens surrendered to Sparta, marking the end of the Peloponnesian War and the beginning of Spartan hegemony over Greece.",
      "date": "-0404"
    }
  ]
}

