{
  "timeline": [
    {
      "headline": "Construction of the Great Sphinx",
      "text": "The Great Sphinx of Giza is believed to have been constructed during the reign of Pharaoh Khafre, around 2500 BCE. It was carved from the bedrock of the Giza Plateau and is one of the largest and oldest statues in the world.",
      "date": "-2500"
    },
    {
      "headline": "Restoration by Thutmose IV",
      "text": "In approximately 1400 BCE, Pharaoh Thutmose IV undertook a restoration of the Great Sphinx. He placed a granite stela between its paws, known as the Dream Stele, which records a dream he had in which the Sphinx spoke to him.",
      "date": "-1400"
    },
    {
      "headline": "Roman Period Repairs",
      "text": "During the Roman period, around the 1st century CE, the Great Sphinx underwent repairs. The Romans used small limestone blocks to restore parts of the statue.",
      "date": "0100"
    },
    {
      "headline": "Napoleon's Expedition",
      "text": "In 1798, during Napoleon Bonaparte's Egyptian campaign, the Great Sphinx was documented by the scholars and artists who accompanied the expedition. This brought renewed attention to the monument in the Western world.",
      "date": "1798"
    },
    {
      "headline": "20th Century Excavations and Restorations",
      "text": "Throughout the 20th century, the Great Sphinx underwent several excavations and restorations. Notably, in the 1920s and 1930s, French engineer Emile Baraize led a major excavation and restoration project.",
      "date": "1920"
    },
    {
      "headline": "Modern Restoration Efforts",
      "text": "In the late 20th and early 21st centuries, ongoing restoration efforts have been made to preserve the Great Sphinx. These efforts have included repairing erosion damage and stabilizing the structure.",
      "date": "2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Authorization for Construction",
      "text": "The USS Constitution was authorized for construction by the Naval Act of 1794, which called for the building of six frigates to form the core of the United States Navy.",
      "date": "1794"
    },
    {
      "headline": "Naming of the USS Constitution",
      "text": "In March 1795, Secretary of War Timothy Pickering submitted ten names to President George Washington for the new frigates, including the name 'Constitution'.",
      "date": "1795-03"
    },
    {
      "headline": "Launch of USS Constitution",
      "text": "USS Constitution was launched on October 21, 1797, from Edmund Hartt's shipyard in the North End of Boston, Massachusetts.",
      "date": "1797-10-21"
    },
    {
      "headline": "Quasi-War with France",
      "text": "USS Constitution's first duties included providing protection for American merchant shipping during the Quasi-War with France, which lasted from 1798 to 1800.",
      "date": "1798"
    },
    {
      "headline": "First Barbary War",
      "text": "USS Constitution played a significant role in defeating the Barbary pirates during the First Barbary War, which took place from 1801 to 1805.",
      "date": "1801"
    },
    {
      "headline": "War of 1812",
      "text": "During the War of 1812, USS Constitution earned the nickname 'Old Ironsides' after defeating the British frigate HMS Guerriere on August 19, 1812.",
      "date": "1812-08-19"
    },
    {
      "headline": "Battle with HMS Java",
      "text": "USS Constitution defeated the British frigate HMS Java on December 29, 1812, further cementing her reputation.",
      "date": "1812-12-29"
    },
    {
      "headline": "Preservation Efforts",
      "text": "In 1830, public sentiment saved USS Constitution from being scrapped, leading to her preservation as a symbol of American naval heritage.",
      "date": "1830"
    },
    {
      "headline": "Restoration and Museum Ship",
      "text": "USS Constitution underwent several restorations over the years and became a museum ship, serving as a symbol of American history and naval tradition.",
      "date": "1907"
    },
    {
      "headline": "World's Oldest Commissioned Naval Vessel Afloat",
      "text": "As of the 21st century, USS Constitution holds the title of the world's oldest commissioned naval vessel still afloat.",
      "date": "2000"
    }
  ]
}

