    {
      "headline": "Etsy Founded",
      "text": "Etsy was founded in June 2005 by Rob Kalin, Chris Maguire, and Haim Schoppik in Brooklyn, New York. The platform was created to provide a marketplace for handmade and vintage items.",
      "date": "2005-06"
    },
    {
      "headline": "Etsy's First Year of Operation",
      "text": "By the end of 2005, Etsy had grown significantly, attracting a community of crafters and artists who were looking for a platform to sell their handmade goods.",
      "date": "2005"
    },
    {
      "headline": "Etsy's First Funding Round",
      "text": "In 2006, Etsy raised $1 million in its first round of funding from a group of investors, which helped the company to expand its operations and improve its platform.",
      "date": "2006"
    },
    {
      "headline": "Etsy's Rapid Growth",
      "text": "By 2007, Etsy had over 450,000 registered sellers and was generating $26 million in annual sales, marking a period of rapid growth for the company.",
      "date": "2007"
    },
    {
      "headline": "Etsy's Series C Funding",
      "text": "In 2008, Etsy secured $27 million in Series C funding, which was used to further expand its platform and improve its infrastructure.",
      "date": "2008"
    },
    {
      "headline": "Etsy Introduces Direct Checkout",
      "text": "In 2012, Etsy introduced Direct Checkout, allowing buyers to purchase items directly through Etsy without being redirected to PayPal or other payment services.",
      "date": "2012"
    },
    {
      "headline": "Etsy Allows Mass-Manufactured Items",
      "text": "In 2013, Etsy changed its policies to allow sellers to list mass-manufactured items, expanding the range of products available on the platform.",
      "date": "2013"
    },
    {
      "headline": "Etsy Goes Public",
      "text": "On April 16, 2015, Etsy went public on the NASDAQ stock exchange under the ticker symbol ETSY, raising $237 million in its initial public offering.",
      "date": "2015-04-16"
    },
    {
      "headline": "Etsy Acquires Reverb",
      "text": "In 2019, Etsy acquired Reverb, a marketplace for new, used, and vintage musical instruments, for $275 million, expanding its reach into the music industry.",
      "date": "2019"
    },
