{
  "timeline": [
    {
      "headline": "Sabra and Shatila Massacre Begins",
      "text": "On September 16, 1982, the Sabra and Shatila massacre began. The Lebanese Forces, a Christian militia, entered the Sabra neighborhood and Shatila refugee camp in Beirut, Lebanon, and began killing civilians, mostly Palestinians and Lebanese Shias.",
      "date": "1982-09-16"
    },
    {
      "headline": "Massacre Continues",
      "text": "The massacre continued on September 17, 1982, with the Lebanese Forces militia systematically killing civilians in the Sabra and Shatila areas. The Israel Defense Forces (IDF), which had surrounded the area, allowed the militia to enter and did not intervene.",
      "date": "1982-09-17"
    },
    {
      "headline": "Massacre Ends",
      "text": "The massacre ended on September 18, 1982, after three days of violence. Reports estimated that between 1,300 and 3,500 civilians were killed during the massacre.",
      "date": "1982-09-18"
    },
    {
      "headline": "International Outcry and Investigation",
      "text": "Following the massacre, there was an international outcry and demands for an investigation. The Kahan Commission was established by the Israeli government to investigate the events and the role of the IDF.",
      "date": "1982"
    },
    {
      "headline": "Kahan Commission Report",
      "text": "In February 1983, the Kahan Commission released its report, which found that the Israeli Defense Minister Ariel Sharon bore personal responsibility for failing to prevent the massacre. The report led to Sharon's resignation from his post.",
      "date": "1983-02"
    }
  ]
}

