    {
      "headline": "Reign of Vlad the Impaler",
      "text": "Vlad III, also known as Vlad the Impaler, ruled Wallachia at various times between 1448 and 1476. He is known for his resistance against the Ottoman Empire and his brutal punishment methods.",
      "date": "1448"
    },
    {
      "headline": "Ottoman Suzerainty",
      "text": "In 1462, Wallachia became a vassal state of the Ottoman Empire, although it retained a degree of autonomy.",
      "date": "1462"
    },
    {
      "headline": "Michael the Brave's Unification",
      "text": "In 1600, Michael the Brave briefly united Wallachia, Transylvania, and Moldavia under his rule, marking the first time these regions were united.",
      "date": "1600"
    },
    {
      "headline": "Phanariot Rule",
      "text": "In 1715, the Phanariot era began in Wallachia, characterized by Greek administrators appointed by the Ottoman Empire, lasting until 1821.",
      "date": "1715"
    },
    {
      "headline": "Wallachian Revolution of 1848",
      "text": "In 1848, Wallachia experienced a revolution that was part of the wider Revolutions of 1848 in Europe, aiming for national independence and social reform.",
      "date": "1848"
    },
    {
      "headline": "Union with Moldavia",
      "text": "On January 24, 1859, Wallachia united with Moldavia under the leadership of Alexandru Ioan Cuza, forming the basis of modern Romania.",
      "date": "1859-01-24"
    },
    {
      "headline": "Romanian War of Independence",
      "text": "In 1877, Wallachia, as part of Romania, fought in the Romanian War of Independence against the Ottoman Empire, leading to the recognition of Romania's independence in 1878.",
      "date": "1877"
    }
  ]
}

