{
  "timeline": [
    {
      "headline": "First U-boat Commissioned",
      "text": "The first U-boat, U-1, was commissioned into the Imperial German Navy on December 14, 1906. It was a small submarine powered by a single gasoline engine for surface running and an electric motor for submerged operations.",
      "date": "1906-12-14"
    },
    {
      "headline": "World War I Begins",
      "text": "World War I began in 1914, marking the start of extensive U-boat operations by the German Navy. U-boats were used to enforce a naval blockade against the Allies.",
      "date": "1914"
    },
    {
      "headline": "Sinking of RMS Lusitania",
      "text": "On May 7, 1915, the German U-boat U-20 sank the British ocean liner RMS Lusitania, resulting in the deaths of 1,198 passengers and crew. This event significantly influenced public opinion against Germany in the United States.",
      "date": "1915-05-07"
    },
    {
      "headline": "Unrestricted Submarine Warfare",
      "text": "In February 1917, Germany resumed unrestricted submarine warfare, aiming to cut off supplies to the Allies. This decision contributed to the United States entering the war.",
      "date": "1917-02"
    },
    {
      "headline": "End of World War I",
      "text": "World War I ended on November 11, 1918. The Treaty of Versailles, signed in 1919, severely restricted Germany's ability to maintain a submarine fleet.",
      "date": "1918-11-11"
    },
    {
      "headline": "Rearmament and World War II",
      "text": "In the 1930s, Germany began rearming in violation of the Treaty of Versailles, including the development of a new U-boat fleet. By the start of World War II in 1939, Germany had a significant number of U-boats ready for combat.",
      "date": "1939"
    },
    {
      "headline": "Battle of the Atlantic",
      "text": "The Battle of the Atlantic was a prolonged naval campaign during World War II, lasting from 1939 to 1945. U-boats played a crucial role in attempting to blockade Britain and cut off its supply lines.",
      "date": "1939"
    },
    {
      "headline": "Sinking of HMS Royal Oak",
      "text": "On October 14, 1939, U-47, commanded by Günther Prien, penetrated the British naval base at Scapa Flow and sank the battleship HMS Royal Oak, killing 833 men.",
      "date": "1939-10-14"
    },
    {
      "headline": "Introduction of the Type XXI U-boat",
      "text": "In 1944, Germany introduced the Type XXI U-boat, the first submarine designed to operate primarily submerged. It featured advanced technology and influenced post-war submarine designs.",
      "date": "1944"
    },
    {
      "headline": "End of World War II",
      "text": "World War II ended in 1945, leading to the surrender of the remaining German U-boats. Many were scuttled or taken by the Allies as war prizes.",
      "date": "1945"
    }
  ]
}

