{
  "timeline": [
    {
      "headline": "Comstock Act Passed",
      "text": "In 1873, the Comstock Act was passed, making it illegal to send any 'obscene, lewd, or lascivious' materials through the mail, including contraceptive devices and information, which indirectly affected abortion access.",
      "date": "1873"
    },
    {
      "headline": "Roe v. Wade Decision",
      "text": "On January 22, 1973, the U.S. Supreme Court issued its landmark decision in Roe v. Wade, ruling that the Constitution of the United States protects a pregnant woman's liberty to choose to have an abortion without excessive government restriction.",
      "date": "1973-01-22"
    },
    {
      "headline": "Hyde Amendment Enacted",
      "text": "In 1976, the Hyde Amendment was enacted, barring the use of federal funds to pay for abortion except to save the life of the woman, or if the pregnancy arises from incest or rape.",
      "date": "1976"
    },
    {
      "headline": "Planned Parenthood v. Casey",
      "text": "On June 29, 1992, the Supreme Court reaffirmed the right to have an abortion in Planned Parenthood v. Casey but allowed states to impose some restrictions, provided they do not place an 'undue burden' on the woman.",
      "date": "1992-06-29"
    },
    {
      "headline": "Partial-Birth Abortion Ban Act",
      "text": "In 2003, the Partial-Birth Abortion Ban Act was signed into law by President George W. Bush, prohibiting a specific abortion procedure known as intact dilation and extraction.",
      "date": "2003"
    },
    {
      "headline": "Whole Woman's Health v. Hellerstedt",
      "text": "On June 27, 2016, the Supreme Court struck down Texas HB 2 in Whole Woman's Health v. Hellerstedt, ruling that the law's requirements placed an undue burden on women seeking abortions.",
      "date": "2016-06-27"
    },
    {
      "headline": "Dobbs v. Jackson Women's Health Organization",
      "text": "On June 24, 2022, the Supreme Court overturned Roe v. Wade in Dobbs v. Jackson Women's Health Organization, ruling that the Constitution does not confer a right to abortion, thus returning the authority to regulate abortion to the states.",
      "date": "2022-06-24"
    }
  ]
}

