{
  "timeline": [
    {
      "headline": "First Plague: Water Turned to Blood",
      "text": "The first plague that Yahweh inflicted on Egypt was turning the Nile River's water into blood. This event is described as occurring when Moses and Aaron confronted Pharaoh, and Aaron struck the water with his staff. The fish in the river died, and the river stank, making it undrinkable. This plague lasted for seven days.",
      "date": "-1500"  },
    {
      "headline": "Second Plague: Frogs",
      "text": "The second plague involved a massive infestation of frogs that emerged from the Nile and spread throughout Egypt. Frogs entered houses, bedrooms, and kitchens, causing great distress to the Egyptians.",
      "date": "-1500"
    },
    {
      "headline": "Third Plague: Gnats or Lice",
      "text": "The third plague was a swarm of gnats or lice that afflicted both people and animals. Aaron struck the dust of the earth with his staff, and the dust became gnats throughout the land of Egypt.",
      "date": "-1500"
    },
    {
      "headline": "Fourth Plague: Wild Animals or Flies",
      "text": "The fourth plague brought swarms of wild animals or flies into the homes of the Egyptians, causing destruction and chaos. This plague did not affect the land of Goshen, where the Israelites lived.",
      "date": "-1500"
    },
    {
      "headline": "Fifth Plague: Pestilence on Livestock",
      "text": "The fifth plague was a severe pestilence that struck the Egyptian livestock, including horses, donkeys, camels, cattle, sheep, and goats, causing them to die. The livestock of the Israelites was unharmed.",
      "date": "-1500"
    },
    {
      "headline": "Sixth Plague: Boils",
      "text": "The sixth plague caused painful boils to break out on the skin of the Egyptians and their animals. Moses and Aaron took handfuls of soot from a kiln and threw it into the air, which became fine dust over the land, causing the boils.",
      "date": "-1500"
    },
    {
      "headline": "Seventh Plague: Thunderstorm of Hail and Fire",
      "text": "The seventh plague was a destructive thunderstorm of hail and fire that struck Egypt, destroying crops and livestock in the fields. The land of Goshen was spared from this plague.",
      "date": "-1500"
    },
    {
      "headline": "Eighth Plague: Locusts",
      "text": "The eighth plague brought a swarm of locusts that covered the land and consumed all the remaining crops and vegetation that had survived the hailstorm.",
      "date": "-1500"
    },
    {
      "headline": "Ninth Plague: Darkness",
      "text": "The ninth plague was a darkness that fell over Egypt for three days. It was so thick that the Egyptians could not see each other or leave their homes. The Israelites, however, had light where they lived.",
      "date": "-1500"
    },
    {
      "headline": "Tenth Plague: Death of the Firstborn",
      "text": "The tenth and final plague was the death of all Egyptian firstborns, from the firstborn of Pharaoh to the firstborn of the prisoner in the dungeon, and the firstborn of all livestock. This event led Pharaoh to finally release the Israelites from bondage.",
      "date": "-1500"
    }
  ]
}

