    {
      "headline": "Camp David Accords",
      "text": "In September 1978, the Camp David Accords were signed by Egypt and Israel, leading to the Egypt-Israel Peace Treaty and setting a framework for peace in the Middle East, including a resolution to the Palestinian problem.",
      "date": "1978-09"
    },
    {
      "headline": "Oslo Accords",
      "text": "On September 13, 1993, the Oslo Accords were signed, marking the first face-to-face agreement between the government of Israel and the Palestine Liberation Organization (PLO), and establishing a framework for future negotiations.",
      "date": "1993-09-13"
    },
    {
      "headline": "Camp David Summit",
      "text": "In July 2000, the Camp David Summit was held between U.S. President Bill Clinton, Israeli Prime Minister Ehud Barak, and Palestinian Authority Chairman Yasser Arafat, but ended without an agreement.",
      "date": "2000-07"
    },
    {
      "headline": "Roadmap for Peace",
      "text": "In 2003, the 'Roadmap for Peace' was proposed by the United States, European Union, Russia, and the United Nations, outlining steps toward a two-state solution.",
      "date": "2003"
    },
    {
      "headline": "Annapolis Conference",
      "text": "On November 27, 2007, the Annapolis Conference was held in Maryland, USA, aiming to revive the Israeli-Palestinian peace process and implement the two-state solution.",
      "date": "2007-11-27"
    }
  ]
