    {
      "headline": "First Description of Tourette Syndrome",
      "text": "In 1825, French physician Jean Marc Gaspard Itard described the case of the Marquise de Dampierre, a noblewoman with motor and vocal tics, which is considered one of the earliest documented cases of Tourette syndrome.",
      "date": "1825"
    },
    {
      "headline": "Georges Gilles de la Tourette's Study",
      "text": "In 1885, French neurologist Georges Gilles de la Tourette published an account of nine patients with motor and vocal tics, which he termed 'maladie des tics'. This work led to the condition being named after him.",
      "date": "1885"
    },
    {
      "headline": "Tourette Syndrome Recognized in the United States",
      "text": "In the 1960s, Tourette syndrome began to be recognized in the United States, leading to increased research and awareness.",
      "date": "1960"
    },
    {
      "headline": "First Tourette Syndrome Association Founded",
      "text": "In 1972, the Tourette Syndrome Association (now known as the Tourette Association of America) was founded to support research and provide information and support to individuals with Tourette syndrome.",
      "date": "1972"
    },
    {
      "headline": "Genetic Link to Tourette Syndrome Identified",
      "text": "In the 1990s, researchers identified a genetic link to Tourette syndrome, suggesting that the disorder is hereditary.",
      "date": "1990"
    },
    {
      "headline": "Tourette Syndrome Included in DSM-IV",
      "text": "In 1994, Tourette syndrome was included in the Diagnostic and Statistical Manual of Mental Disorders, Fourth Edition (DSM-IV), which helped standardize the diagnosis.",
      "date": "1994"
    },
    {
      "headline": "Deep Brain Stimulation for Tourette Syndrome",
      "text": "In the early 2000s, deep brain stimulation emerged as a treatment option for severe cases of Tourette syndrome, providing relief for some patients.",
      "date": "2000"
    }
  ]
}

