{
  "timeline": [
    {
      "headline": "Birth of Tipu Sultan",
      "text": "Tipu Sultan was born on November 20, 1751, in Devanahalli, present-day Bangalore, India.",
      "date": "1751-11-20"
    },
    {
      "headline": "First Anglo-Mysore War",
      "text": "Tipu Sultan participated in the First Anglo-Mysore War (1767-1769) alongside his father, Sultan Hyder Ali, against the British East India Company.",
      "date": "1767"
    },
    {
      "headline": "Second Anglo-Mysore War",
      "text": "Tipu Sultan played a significant role in the Second Anglo-Mysore War (1780-1784), where he gained recognition for his military prowess.",
      "date": "1780"
    },
    {
      "headline": "Treaty of Mangalore",
      "text": "The Treaty of Mangalore was signed on March 11, 1784, ending the Second Anglo-Mysore War. Tipu Sultan and the British East India Company agreed to restore each other's conquered territories.",
      "date": "1784-03-11"
    },
    {
      "headline": "Coronation as Sultan of Mysore",
      "text": "Tipu Sultan was crowned as the Sultan of Mysore in 1782, following the death of his father, Hyder Ali.",
      "date": "1782"
    },
    {
      "headline": "Third Anglo-Mysore War",
      "text": "The Third Anglo-Mysore War (1789-1792) saw Tipu Sultan fighting against the British, Marathas, and Nizam of Hyderabad. The war ended with the Treaty of Seringapatam.",
      "date": "1789"
    },
    {
      "headline": "Treaty of Seringapatam",
      "text": "The Treaty of Seringapatam was signed on March 18, 1792, ending the Third Anglo-Mysore War. Tipu Sultan had to cede half of his kingdom to the British and their allies.",
      "date": "1792-03-18"
    },
    {
      "headline": "Fourth Anglo-Mysore War",
      "text": "The Fourth Anglo-Mysore War (1798-1799) was the final confrontation between Tipu Sultan and the British East India Company.",
      "date": "1798"
    },
    {
      "headline": "Death of Tipu Sultan",
      "text": "Tipu Sultan died on May 4, 1799, during the Siege of Srirangapatna, marking the end of the Fourth Anglo-Mysore War.",
      "date": "1799-05-04"
    }
  ]
}

