      "headline": "Earliest Evidence of Semitic Languages",
      "text": "The earliest evidence of Semitic languages dates back to the 3rd millennium BCE, with Akkadian texts from ancient Mesopotamia.",
      "date": "-03000"
    },
    {
      "headline": "Development of Akkadian",
      "text": "Akkadian becomes the lingua franca of Mesopotamia and the surrounding regions during the 2nd millennium BCE.",
      "date": "-02000"
    },
    {
      "headline": "Emergence of Aramaic",
      "text": "Aramaic emerges as a major language in the Near East around the 1st millennium BCE, eventually becoming the administrative language of empires such as the Neo-Assyrian and Achaemenid Empires.",
      "date": "-01000"
    },
    {
      "headline": "Hebrew Language Development",
      "text": "Hebrew develops as a distinct language and is used in the composition of biblical texts during the 1st millennium BCE.",
      "date": "-01000"
    },
    {
      "headline": "Spread of Arabic",
      "text": "Arabic spreads across the Arabian Peninsula and becomes the dominant language of the Islamic Caliphates following the 7th century CE.",
      "date": "0700"
    },
    {
      "headline": "Introduction of the Term 'Semitic Languages'",
      "text": "The term 'Semitic languages' is introduced in the 1780s by members of the Göttingen school of history, derived from Shem, one of the sons of Noah in the Book of Genesis.",
      "date": "1780"
    },
    {
      "headline": "Modern Recognition of Semitic Languages",
      "text": "In the modern era, Semitic languages are recognized as a branch of the Afroasiatic language family, spoken by more than 330 million people worldwide.",
      "date": "2023"
    }
  ]
}

