  "timeline": [
    {
      "headline": "Creation of the Doomsday Clock",
      "text": "The Doomsday Clock was created in 1947 by the Bulletin of the Atomic Scientists. It was designed to represent the likelihood of a human-made global catastrophe.",
      "date": "1947"
    },
    {
      "headline": "Initial Setting of the Clock",
      "text": "In 1947, the Doomsday Clock was initially set at 7 minutes to midnight.",
      "date": "1947"
    },
    {
      "headline": "First Adjustment of the Clock",
      "text": "In 1949, the Clock was moved to 3 minutes to midnight following the Soviet Union's first nuclear test.",
      "date": "1949"
    },
    {
      "headline": "Clock Moved to 2 Minutes to Midnight",
      "text": "In 1953, the Clock was set to 2 minutes to midnight after the United States and the Soviet Union tested thermonuclear weapons within nine months of one another.",
      "date": "1953"
    },
    {
      "headline": "Clock Moved to 12 Minutes to Midnight",
      "text": "In 1963, the Clock was set to 12 minutes to midnight following the signing of the Partial Test Ban Treaty by the United States and the Soviet Union.",
      "date": "1963"
    },
    {
      "headline": "Clock Moved to 17 Minutes to Midnight",
      "text": "In 1991, the Clock was set to 17 minutes to midnight, the furthest from midnight it has ever been, due to the end of the Cold War and the signing of the Strategic Arms Reduction Treaty.",
      "date": "1991"
    },
    {
      "headline": "Clock Moved to 3 Minutes to Midnight",
      "text": "In 2015, the Clock was set to 3 minutes to midnight due to unchecked climate change and the modernization of nuclear weapons.",
      "date": "2015"
    },
    {
      "headline": "Clock Moved to 2 Minutes to Midnight",
      "text": "In 2018, the Clock was set to 2 minutes to midnight, reflecting the failure of world leaders to deal with threats of nuclear war and climate change.",
      "date": "2018"
    },
    {
      "headline": "Clock Moved to 100 Seconds to Midnight",
      "text": "In 2020, the Clock was set to 100 seconds to midnight, the closest it has ever been, due to increased threats from nuclear weapons, climate change, and disruptive technologies.",
      "date": "2020"
    },
    {
      "headline": "Clock Remains at 100 Seconds to Midnight",
      "text": "In 2021, the Clock remained at 100 seconds to midnight, reflecting ongoing threats from nuclear risks, climate change, and the COVID-19 pandemic.",
      "date": "2021"
    },
    {
      "headline": "Clock Remains at 100 Seconds to Midnight",
      "text": "In 2022, the Clock remained at 100 seconds to midnight, continuing to highlight the persistent threats of nuclear war, climate change, and disruptive technologies.",
      "date": "2022"
    },
    {
      "headline": "Clock Moved to 90 Seconds to Midnight",
      "text": "In 2023, the Clock was set to 90 seconds to midnight, the closest it has ever been, due to the ongoing war in Ukraine, nuclear risks, and climate change.",
      "date": "2023"
    }
  ]
}

