{
  "timeline": [
    {
      "headline": "First Mention of Bethlehem",
      "text": "Bethlehem is first mentioned in the Amarna letters from the 14th century BCE, where it is referred to as a city in the land of Canaan.",
      "date": "-1400"
    },
    {
      "headline": "Birthplace of King David",
      "text": "According to the Hebrew Bible, Bethlehem is the birthplace of King David, who was anointed king by the prophet Samuel.",
      "date": "-1040"
    },
    {
      "headline": "Birth of Jesus",
      "text": "Bethlehem is traditionally considered the birthplace of Jesus, as described in the New Testament of the Bible. This event is believed to have occurred around 4 BCE.",
      "date": "-0004"
    },
    {
      "headline": "Construction of the Church of the Nativity",
      "text": "The Church of the Nativity was commissioned by Constantine the Great and his mother Helena in 327 CE, marking the site traditionally believed to be the birthplace of Jesus.",
      "date": "0327"
    },
    {
      "headline": "Persian Invasion",
      "text": "In 614 CE, Bethlehem was conquered by the Sassanid Empire during the Byzantine-Sassanid War.",
      "date": "0614"
    },
    {
      "headline": "Muslim Conquest",
      "text": "Bethlehem came under Muslim control in 637 CE following the Muslim conquest of the Levant.",
      "date": "0637"
    },
    {
      "headline": "Crusader Control",
      "text": "Bethlehem was captured by the Crusaders in 1099 CE during the First Crusade, and the Church of the Nativity was rebuilt.",
      "date": "1099"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Bethlehem became part of the Ottoman Empire in 1517 CE, following the Ottoman conquest of the Mamluk Sultanate.",
      "date": "1517"
    },
    {
      "headline": "British Mandate",
      "text": "After World War I, Bethlehem came under British control as part of the British Mandate of Palestine in 1920.",
      "date": "1920"
    },
    {
      "headline": "Jordanian Annexation",
      "text": "Following the 1948 Arab-Israeli War, Bethlehem was annexed by Jordan in 1950.",
      "date": "1950"
    },
    {
      "headline": "Israeli Occupation",
      "text": "Bethlehem was occupied by Israel during the Six-Day War in 1967.",
      "date": "1967"
    },
    {
      "headline": "Oslo Accords and Palestinian Authority",
      "text": "In 1995, as part of the Oslo Accords, Bethlehem was transferred to Palestinian Authority control.",
      "date": "1995"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Flight Departure",
      "text": "Korean Air Lines Flight 007 departed from New York City, bound for Seoul with a stopover in Anchorage, Alaska.",
      "date": "1983-08-31"
    },
    {
      "headline": "Stopover in Anchorage",
      "text": "The flight made a scheduled stopover in Anchorage, Alaska, for refueling and crew change before continuing to Seoul.",
      "date": "1983-09-01"
    },
    {
      "headline": "Flight Deviates from Planned Route",
      "text": "Due to a navigational mistake, the flight deviated from its planned route and entered Soviet prohibited airspace.",
      "date": "1983-09-01"
    },
    {
      "headline": "Soviet Interception",
      "text": "The Soviet Air Forces intercepted the aircraft, mistaking it for a U.S. spy plane, and fired warning shots.",
      "date": "1983-09-01"
    },
    {
      "headline": "Flight Shot Down",
      "text": "A Soviet Sukhoi Su-15 interceptor shot down Korean Air Lines Flight 007 with air-to-air missiles, leading to its crash near Moneron Island.",
      "date": "1983-09-01"
    },
    {
      "headline": "Casualties",
      "text": "All 246 passengers and 23 crew members aboard the flight were killed, including U.S. Representative Larry McDonald.",
      "date": "1983-09-01"
    },
    {
      "headline": "Wreckage Discovered",
      "text": "The Soviet Union discovered the wreckage of the aircraft under the sea two weeks later.",
      "date": "1983-09-15"
    },
    {
      "headline": "Flight Recorders Found",
      "text": "The Soviet authorities found the flight recorders in October, but kept this information secret until 1992.",
      "date": "1983-10"
    },
    {
      "headline": "Disclosure of Information",
      "text": "The information about the wreckage and flight recorders was disclosed by the Soviet authorities after the country's dissolution.",
      "date": "1992"
    }
  ]
}

