{
  "timeline": [
    {
      "headline": "Discovery of Naegleria fowleri",
      "text": "Naegleria fowleri was first identified in 1965 by Dr. Malcolm Fowler and Dr. Rodney Carter in Australia. They discovered the organism while investigating cases of fatal meningitis in children.",
      "date": "1965"
    },
    {
      "headline": "First Case of Naegleriasis in the United States",
      "text": "The first documented case of Naegleria fowleri infection in the United States occurred in 1966. The infection was identified in a young boy who had been swimming in a warm freshwater lake.",
      "date": "1966"
    },
    {
      "headline": "Classification as an Amoeboflagellate",
      "text": "Naegleria fowleri was classified as an amoeboflagellate, an organism capable of existing in both amoeboid and flagellate forms, during the late 1960s. This classification helped in understanding its life cycle and pathogenicity.",
      "date": "1960s"
    },
    {
      "headline": "First Successful Treatment of Naegleriasis",
      "text": "In 1978, the first successful treatment of a Naegleria fowleri infection was reported. The patient, a young girl, survived after receiving an experimental drug regimen.",
      "date": "1978"
    },
    {
      "headline": "Genome Sequencing of Naegleria fowleri",
      "text": "In 2010, the genome of Naegleria fowleri was sequenced, providing insights into its biology and potential targets for treatment.",
      "date": "2010"
    },
    {
      "headline": "Increased Awareness and Research",
      "text": "Throughout the 2010s, increased awareness and research efforts were directed towards understanding Naegleria fowleri, its ecology, and potential treatment options, due to its high fatality rate and the occurrence of cases in various parts of the world.",
      "date": "2010s"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Case Filed",
      "text": "The case Obergefell v. Hodges was filed in the United States District Court for the Southern District of Ohio. The case was initiated by James Obergefell, who sued the state of Ohio for refusing to recognize his marriage to John Arthur, which was performed in Maryland.",
      "date": "2013"
    },
    {
      "headline": "District Court Ruling",
      "text": "On December 23, 2013, the United States District Court for the Southern District of Ohio ruled in favor of Obergefell, ordering the state to recognize same-sex marriages performed out of state.",
      "date": "2013-12-23"
    },
    {
      "headline": "Appeal to Sixth Circuit",
      "text": "The state of Ohio appealed the district court's decision to the United States Court of Appeals for the Sixth Circuit.",
      "date": "2014"
    },
    {
      "headline": "Sixth Circuit Ruling",
      "text": "On November 6, 2014, the Sixth Circuit Court of Appeals reversed the district court's decision, upholding bans on same-sex marriage in Kentucky, Michigan, Ohio, and Tennessee.",
      "date": "2014-11-06"
    },
    {
      "headline": "Supreme Court Grants Certiorari",
      "text": "On January 16, 2015, the Supreme Court of the United States granted certiorari to hear the case, consolidating it with other cases challenging same-sex marriage bans.",
      "date": "2015-01-16"
    },
    {
      "headline": "Oral Arguments",
      "text": "Oral arguments for Obergefell v. Hodges were heard by the Supreme Court on April 28, 2015.",
      "date": "2015-04-28"
    },
    {
      "headline": "Supreme Court Decision",
      "text": "On June 26, 2015, the Supreme Court issued a 5–4 decision in Obergefell v. Hodges, ruling that the fundamental right to marry is guaranteed to same-sex couples by both the Due Process Clause and the Equal Protection Clause of the Fourteenth Amendment.",
      "date": "2015-06-26"
    }
  ]
}

