{
  "timeline": [
    {
      "headline": "Initial Development of TCP",
      "text": "The Transmission Control Protocol (TCP) was developed by Vint Cerf and Bob Kahn. The initial specification was published in a paper titled 'A Protocol for Packet Network Intercommunication' in 1974.",
      "date": "1974"
    },
    {
      "headline": "TCP/IP Protocol Suite",
      "text": "In 1978, TCP was split into TCP and IP, leading to the development of the TCP/IP protocol suite. This suite became the foundational protocol for the Internet.",
      "date": "1978"
    },
    {
      "headline": "Adoption by ARPANET",
      "text": "On January 1, 1983, ARPANET adopted TCP/IP as its standard networking protocol, marking the beginning of the modern Internet.",
      "date": "1983-01-01"
    },
    {
      "headline": "RFC 793 Published",
      "text": "The official specification for TCP, RFC 793, was published by the Internet Engineering Task Force (IETF) in September 1981.",
      "date": "1981-09"
    },
    {
      "headline": "Introduction of Congestion Control",
      "text": "In 1988, Van Jacobson introduced algorithms for congestion control in TCP, which significantly improved the protocol's performance and reliability.",
      "date": "1988"
    },
    {
      "headline": "Development of TCP Extensions",
      "text": "Throughout the 1990s and 2000s, various extensions and improvements were made to TCP, including selective acknowledgments (SACK) and window scaling to enhance performance over high-speed networks.",
      "date": "1990"
    },
    {
      "headline": "Implementation of SSL/TLS over TCP",
      "text": "In the mid-1990s, the Secure Sockets Layer (SSL) and later Transport Layer Security (TLS) protocols were developed to run on top of TCP, providing encrypted communication over the Internet.",
      "date": "1995"
    }
  ]
}

{
