      "headline": "Founding of the Revenue Cutter Service",
      "text": "On August 4, 1790, the United States Congress established the Revenue Cutter Service, the precursor to the United States Coast Guard, to enforce tariff and trade laws and to prevent smuggling.",
      "date": "1790-08-04"
    },
    {
      "headline": "Creation of the United States Life-Saving Service",
      "text": "In 1848, the United States Life-Saving Service was established to provide assistance to shipwrecked mariners and vessels in distress along the U.S. coastline.",
      "date": "1848"
    },
    {
      "headline": "Formation of the United States Coast Guard",
      "text": "On January 28, 1915, the Revenue Cutter Service and the United States Life-Saving Service were merged to form the United States Coast Guard, creating a single maritime service dedicated to saving life at sea and enforcing the nation's maritime laws.",
      "date": "1915-01-28"
    },
    {
      "headline": "Transfer to the Department of the Navy during World War I",
      "text": "During World War I, the Coast Guard was transferred to the Department of the Navy on April 6, 1917, to support wartime operations.",
      "date": "1917-04-06"
    },
    {
      "headline": "Return to the Department of the Treasury",
      "text": "After World War I, the Coast Guard returned to the Department of the Treasury on August 28, 1919.",
      "date": "1919-08-28"
    },
    {
      "headline": "Transfer to the Department of the Navy during World War II",
      "text": "The Coast Guard was again transferred to the Department of the Navy on November 1, 1941, to support operations during World War II.",
      "date": "1941-11-01"
    },
    {
      "headline": "Return to the Department of the Treasury post-World War II",
      "text": "Following World War II, the Coast Guard returned to the Department of the Treasury on January 1, 1946.",
      "date": "1946-01-01"
    },
    {
      "headline": "Transfer to the Department of Transportation",
      "text": "On April 1, 1967, the Coast Guard was transferred to the newly created Department of Transportation, reflecting its peacetime role in maritime safety and regulation.",
      "date": "1967-04-01"
    },
    {
      "headline": "Transfer to the Department of Homeland Security",
      "text": "Following the September 11 attacks, the Coast Guard was transferred to the Department of Homeland Security on March 1, 2003, to enhance its role in maritime security.",
      "date": "2003-03-01"
    }
  ]
}

