{
  "timeline": [
    {
      "headline": "Birth of Leslie Groves",
      "text": "Leslie Richard Groves Jr. was born on August 17, 1896, in Albany, New York.",
      "date": "1896-08-17"
    },
    {
      "headline": "Graduation from West Point",
      "text": "Leslie Groves graduated from the United States Military Academy at West Point in 1918.",
      "date": "1918"
    },
    {
      "headline": "Assignment to the Army Corps of Engineers",
      "text": "In 1918, Groves was commissioned into the United States Army Corps of Engineers.",
      "date": "1918"
    },
    {
      "headline": "Construction of the Pentagon",
      "text": "Groves was responsible for overseeing the construction of the Pentagon, which began in 1941 and was completed in 1943.",
      "date": "1941"
    },
    {
      "headline": "Appointment to the Manhattan Project",
      "text": "In September 1942, Groves was appointed to direct the Manhattan Project, the top-secret project to develop the atomic bomb.",
      "date": "1942-09"
    },
    {
      "headline": "First Atomic Bomb Test",
      "text": "Under Groves' direction, the first atomic bomb was successfully tested at the Trinity site in New Mexico on July 16, 1945.",
      "date": "1945-07-16"
    },
    {
      "headline": "End of World War II",
      "text": "The atomic bombs developed under the Manhattan Project were dropped on Hiroshima and Nagasaki in August 1945, leading to the end of World War II.",
      "date": "1945-08"
    },
    {
      "headline": "Retirement from the Army",
      "text": "Leslie Groves retired from the United States Army in 1948.",
      "date": "1948"
    },
    {
      "headline": "Publication of Memoir",
      "text": "Groves published his memoir, 'Now It Can Be Told: The Story of the Manhattan Project,' in 1962.",
      "date": "1962"
    },
    {
      "headline": "Death of Leslie Groves",
      "text": "Leslie Groves passed away on July 13, 1970, in Washington, D.C.",
      "date": "1970-07-13"
    }
  ]
}

