{
  "timeline": [
    {
      "headline": "Estimated Birth of Jesus",
      "text": "Most biblical scholars and historians estimate that Jesus was born between 6 and 4 BC. This estimation is based on historical references to King Herod's reign and the Gospel accounts.",
      "date": "-0006"
    },
    {
      "headline": "Herod's Reign Reference",
      "text": "The Gospel of Matthew states that Jesus was born during the reign of King Herod, who died in 4 BC. This is one of the key references used to estimate Jesus' birth year.",
      "date": "-0004"
    },
    {
      "headline": "Jesus Begins Preaching",
      "text": "According to the Gospel of Luke, Jesus began his ministry at about 30 years of age. This suggests a birth year around 6 to 4 BC if he began preaching around 27-29 AD.",
      "date": "0027"
    }
  ]
}

