{
  "timeline": [
    {
      "headline": "First COVID-19 Vaccine Trials Begin",
      "text": "In March 2020, the first human trials for a COVID-19 vaccine began, marking a significant step in the global effort to combat the pandemic.",
      "date": "2020-03"
    },
    {
      "headline": "Pfizer-BioNTech Vaccine Emergency Use Authorization",
      "text": "On December 11, 2020, the Pfizer-BioNTech COVID-19 vaccine received Emergency Use Authorization (EUA) from the U.S. Food and Drug Administration (FDA), becoming the first COVID-19 vaccine authorized for emergency use in the United States.",
      "date": "2020-12-11"
    },
    {
      "headline": "Moderna Vaccine Emergency Use Authorization",
      "text": "On December 18, 2020, the Moderna COVID-19 vaccine was granted Emergency Use Authorization by the FDA, making it the second vaccine available in the United States.",
      "date": "2020-12-18"
    },
    {
      "headline": "AstraZeneca Vaccine Approved in the UK",
      "text": "On December 30, 2020, the AstraZeneca COVID-19 vaccine was approved for use in the United Kingdom, expanding the options for vaccination in the country.",
      "date": "2020-12-30"
    },
    {
      "headline": "Johnson & Johnson Vaccine Emergency Use Authorization",
      "text": "On February 27, 2021, the Johnson & Johnson COVID-19 vaccine received Emergency Use Authorization from the FDA, providing a single-dose option for vaccination.",
      "date": "2021-02-27"
    },
    {
      "headline": "Global Vaccination Campaigns Begin",
      "text": "Throughout 2021, countries around the world began mass vaccination campaigns, aiming to immunize their populations against COVID-19 and curb the spread of the virus.",
      "date": "2021"
    },
    {
      "headline": "WHO Approves First COVID-19 Vaccine",
      "text": "On December 31, 2020, the World Health Organization (WHO) listed the Pfizer-BioNTech COVID-19 vaccine for emergency use, the first vaccine to receive such validation from the WHO.",
      "date": "2020-12-31"
    },
    {
      "headline": "COVAX Initiative Distributes Vaccines",
      "text": "In 2021, the COVAX initiative, co-led by Gavi, the Coalition for Epidemic Preparedness Innovations (CEPI), and the WHO, began distributing COVID-19 vaccines to low and middle-income countries to ensure equitable access.",
      "date": "2021"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of the New Democratic Party",
      "text": "The New Democratic Party (NDP) was founded in 1961 by the Co-operative Commonwealth Federation (CCF) and the Canadian Labour Congress (CLC).",
      "date": "1961"
    },
    {
      "headline": "First Federal Election",
      "text": "The NDP contested its first federal election in 1962, winning 19 seats in the House of Commons.",
      "date": "1962"
    },
    {
      "headline": "Tommy Douglas Leadership",
      "text": "Tommy Douglas, the first leader of the NDP, served from 1961 to 1971. He is often credited with the introduction of universal healthcare in Canada.",
      "date": "1961"
    },
    {
      "headline": "Ed Broadbent Leadership",
      "text": "Ed Broadbent led the NDP from 1975 to 1989, during which the party achieved its best federal election result in 1988, winning 43 seats.",
      "date": "1975"
    },
    {
      "headline": "Jack Layton Leadership",
      "text": "Jack Layton became the leader of the NDP in 2003 and led the party to its best-ever result in the 2011 federal election, becoming the Official Opposition with 103 seats.",
      "date": "2003"
    },
    {
      "headline": "2011 Federal Election Success",
      "text": "In the 2011 federal election, the NDP won 103 seats, becoming the Official Opposition for the first time in its history.",
      "date": "2011"
    },
    {
      "headline": "Death of Jack Layton",
      "text": "Jack Layton passed away on August 22, 2011, shortly after leading the NDP to its historic success in the federal election.",
      "date": "2011-08-22"
    },
    {
      "headline": "Thomas Mulcair Leadership",
      "text": "Thomas Mulcair was elected leader of the NDP in 2012 and led the party until 2017.",
      "date": "2012"
    },
    {
      "headline": "Jagmeet Singh Leadership",
      "text": "Jagmeet Singh became the leader of the NDP in 2017, becoming the first person of a visible minority group to lead a major federal political party in Canada.",
      "date": "2017"
    }
  ]
}

