    {
      "headline": "Start of Radium Dial Painting in New Jersey",
      "text": "In 1917, the United States Radium Corporation began operations in Orange, New Jersey, employing female workers to paint watch dials with radium-based luminous paint.",
      "date": "1917"
    },
    {
      "headline": "First Signs of Health Issues",
      "text": "By the early 1920s, many of the women working at the Orange, New Jersey plant began to suffer from serious health issues, including anemia, bone fractures, and necrosis of the jaw, later known as 'radium jaw'.",
      "date": "1920"
    },
    {
      "headline": "Radium Dial Company Opens in Illinois",
      "text": "In the early 1920s, the Radium Dial Company began operations in Ottawa, Illinois, employing women to paint dials with radium paint.",
      "date": "1920"
    },
    {
      "headline": "Health Issues in Illinois",
      "text": "Similar health issues began to appear among the workers at the Ottawa, Illinois plant, mirroring those seen in New Jersey.",
      "date": "1920"
    },
    {
      "headline": "Waterbury Clock Company Begins Radium Dial Painting",
      "text": "In the 1920s, the Waterbury Clock Company in Connecticut also employed women to paint dials with radium paint.",
      "date": "1920"
    },
    {
      "headline": "Lawsuit Against United States Radium Corporation",
      "text": "In 1927, five women from the New Jersey plant, known as the 'Radium Girls', filed a lawsuit against the United States Radium Corporation for the health issues they suffered due to radium exposure.",
      "date": "1927"
    },
    {
      "headline": "Settlement of the Lawsuit",
      "text": "In 1928, the lawsuit was settled in favor of the Radium Girls, who received compensation and coverage for medical expenses.",
      "date": "1928"
    },
    {
      "headline": "Impact on Labor Rights and Safety Standards",
      "text": "The case of the Radium Girls led to increased awareness of occupational hazards and contributed to the establishment of labor safety standards and regulations.",
      "date": "1928"
    }
  ]
}

