    {
      "headline": "Unix Epoch Begins",
      "text": "The Unix epoch is the starting point for Unix time, which began at 00:00:00 UTC on January 1, 1970. This is the point from which time is measured in Unix systems.",
      "date": "1970-01-01"
    },
    {
      "headline": "Y2K Problem",
      "text": "The Y2K problem, also known as the Millennium Bug, was a computer bug related to the formatting and storage of calendar data for dates beginning in the year 2000. Unix time was not directly affected by Y2K, but it was a significant event in computing history.",
      "date": "2000"
    },
    {
      "headline": "Unix Time Reaches 1 Billion Seconds",
      "text": "Unix time reached 1 billion seconds on September 9, 2001, at 01:46:40 UTC.",
      "date": "2001-09-09"
    },
    {
      "headline": "Unix Time Reaches 1.5 Billion Seconds",
      "text": "Unix time reached 1.5 billion seconds on July 14, 2017, at 02:40:00 UTC.",
      "date": "2017-07-14"
    },
    {
      "headline": "2038 Problem",
      "text": "The Year 2038 problem is a time formatting bug in computer systems that represent time as the number of seconds since the Unix epoch. It will occur on January 19, 2038, at 03:14:07 UTC, when the 32-bit signed integer representation of Unix time will overflow.",
      "date": "2038-01-19"
    }
  ]
}

