    {
      "headline": "First Published Poem",
      "text": "Pushkin's first published poem, 'To My Friend, the Poet,' appeared in the journal 'The Messenger of Europe' in 1814.",
      "date": "1814"
    },
    {
      "headline": "Graduation from the Lyceum",
      "text": "Pushkin graduated from the Imperial Lyceum in 1817, marking the beginning of his professional literary career.",
      "date": "1817"
    },
    {
      "headline": "Exile to Southern Russia",
      "text": "In 1820, due to his politically charged poems, Pushkin was exiled to Southern Russia, where he continued to write.",
      "date": "1820"
    },
    {
      "headline": "Publication of 'Ruslan and Ludmila'",
      "text": "Pushkin published his first major work, the narrative poem 'Ruslan and Ludmila,' in 1820, which was based on Russian folklore.",
      "date": "1820"
    },
    {
      "headline": "Return from Exile",
      "text": "In 1826, Pushkin was allowed to return from exile after a personal audience with Tsar Nicholas I.",
      "date": "1826"
    },
    {
      "headline": "Marriage to Natalia Goncharova",
      "text": "Pushkin married Natalia Goncharova on February 18, 1831, in Moscow.",
      "date": "1831-02-18"
    },
    {
      "headline": "Publication of 'Eugene Onegin'",
      "text": "Pushkin completed and published his novel in verse, 'Eugene Onegin,' in 1833, which is considered one of his masterpieces.",
      "date": "1833"
    },
    {
      "headline": "Duel and Death",
      "text": "Alexander Pushkin died on February 10, 1837, in St. Petersburg, Russia, after being mortally wounded in a duel with Georges d'Anthès.",
      "date": "1837-02-10"
    }
  ]
}

