    {
      "headline": "United Nations Convention on Psychotropic Substances",
      "text": "In 1971, psilocybin and psilocin were listed as Schedule I drugs under the United Nations Convention on Psychotropic Substances. Schedule I drugs are defined as drugs with a high potential for abuse or drugs that have no recognized medical uses.",
      "date": "1971"
    },
    {
      "headline": "Decriminalization in Denver, Colorado",
      "text": "On May 7, 2019, Denver, Colorado became the first city in the United States to decriminalize psilocybin mushrooms. The measure passed with a narrow margin, effectively making the personal use and possession of psilocybin mushrooms the lowest law enforcement priority.",
      "date": "2019-05-07"
    },
    {
      "headline": "Decriminalization in Oakland, California",
      "text": "On June 4, 2019, Oakland, California followed Denver's lead and decriminalized the use and possession of psilocybin mushrooms, as well as other entheogenic plants.",
      "date": "2019-06-04"
    },
    {
      "headline": "Decriminalization in Santa Cruz, California",
      "text": "On January 28, 2020, Santa Cruz, California decriminalized the possession, cultivation, and personal use of psilocybin mushrooms and other entheogenic plants.",
      "date": "2020-01-28"
    },
    {
      "headline": "Oregon Measure 109",
      "text": "On November 3, 2020, Oregon became the first U.S. state to legalize the therapeutic use of psilocybin mushrooms through Measure 109, which allows regulated medical use of psilocybin.",
      "date": "2020-11-03"
    },
    {
      "headline": "Decriminalization in Washington, D.C.",
      "text": "On November 3, 2020, Washington, D.C. passed Initiative 81, which decriminalized the use and possession of psilocybin mushrooms and other entheogenic plants.",
      "date": "2020-11-03"
    },
    {
      "headline": "Decriminalization in Somerville, Massachusetts",
      "text": "On January 14, 2021, Somerville, Massachusetts decriminalized the possession and use of psilocybin mushrooms and other entheogenic plants.",
      "date": "2021-01-14"
    },
    {
      "headline": "Decriminalization in Cambridge, Massachusetts",
      "text": "On February 3, 2021, Cambridge, Massachusetts decriminalized the possession and use of psilocybin mushrooms and other entheogenic plants.",
      "date": "2021-02-03"
    },
    {
      "headline": "Decriminalization in Seattle, Washington",
      "text": "On October 4, 2021, Seattle, Washington decriminalized the personal use and possession of psilocybin mushrooms and other entheogenic plants.",
      "date": "2021-10-04"
    }
