    {
      "headline": "Discovery of Madeira",
      "text": "In 1419, Portuguese explorers discovered the Madeira archipelago, which became one of the first overseas territories of the Portuguese Empire.",
      "date": "1419"
    },
    {
      "headline": "Discovery of the Azores",
      "text": "The Azores were discovered by Portuguese navigators in 1427, further expanding the empire's reach into the Atlantic Ocean.",
      "date": "1427"
    },
    {
      "headline": "Discovery of Cape Verde",
      "text": "In 1456, Portuguese explorers discovered the Cape Verde islands, which became an important stopover for ships traveling to the Americas.",
      "date": "1456"
    },
    {
      "headline": "Vasco da Gama's Voyage to India",
      "text": "In 1498, Vasco da Gama reached India by sea, establishing a direct maritime route from Europe to Asia and marking a significant expansion of the Portuguese Empire.",
      "date": "1498"
    },
    {
      "headline": "Treaty of Tordesillas",
      "text": "The Treaty of Tordesillas was signed on June 7, 1494, between Portugal and Spain, dividing the newly discovered lands outside Europe between them along a meridian 370 leagues west of the Cape Verde islands.",
      "date": "1494-06-07"
    },
    {
      "headline": "Establishment of Goa as a Portuguese Colony",
      "text": "In 1510, Afonso de Albuquerque captured Goa, which became the capital of Portuguese India and a key center of Portuguese trade in Asia.",
      "date": "1510"
    },
    {
      "headline": "Capture of Malacca",
      "text": "In 1511, the Portuguese captured Malacca, a strategic trading port in Southeast Asia, further expanding their influence in the region.",
      "date": "1511"
    },
    {
      "headline": "Discovery of Brazil",
      "text": "Pedro Álvares Cabral discovered Brazil on April 22, 1500, claiming it for Portugal and beginning the colonization of South America.",
      "date": "1500-04-22"
    },
    {
      "headline": "Union of the Crowns",
      "text": "In 1580, the Portuguese and Spanish crowns were united under King Philip II of Spain, leading to a period known as the Iberian Union.",
      "date": "1580"
    },
    {
      "headline": "Restoration of Portuguese Independence",
      "text": "On December 1, 1640, Portugal regained its independence from Spain, ending the Iberian Union and restoring the Portuguese monarchy.",
      "date": "1640-12-01"
    },
    {
      "headline": "Treaty of Lisbon",
      "text": "The Treaty of Lisbon, signed in 1668, recognized Portuguese sovereignty over Brazil and ended the Portuguese Restoration War with Spain.",
      "date": "1668"
