    {
      "headline": "First Theoretical Description of Nuclear Fusion",
      "text": "In 1920, British physicist Francis William Aston discovered that the mass of helium is less than the combined mass of four hydrogen nuclei, suggesting that energy could be released by fusing hydrogen into helium.",
      "date": "1920"
    },
    {
      "headline": "Bethe's Stellar Nucleosynthesis Theory",
      "text": "In 1939, Hans Bethe published a paper on the nuclear reactions that power the stars, explaining how nuclear fusion reactions between hydrogen nuclei could produce helium and release energy.",
      "date": "1939"
    },
    {
      "headline": "First Controlled Nuclear Fusion Reaction",
      "text": "In 1951, the first controlled nuclear fusion reaction was achieved in the laboratory by the team at the Los Alamos National Laboratory using a device called the 'Pinch' machine.",
      "date": "1951"
    },
    {
      "headline": "Development of the Tokamak",
      "text": "In 1958, Soviet physicists Igor Tamm and Andrei Sakharov developed the concept of the tokamak, a device that uses magnetic fields to confine plasma for nuclear fusion.",
      "date": "1958"
    },
    {
      "headline": "First Tokamak Achieves Plasma Confinement",
      "text": "In 1968, the T-3 Tokamak in the Soviet Union achieved plasma confinement, demonstrating the potential of the tokamak design for nuclear fusion.",
      "date": "1968"
    },
    {
      "headline": "Inception of ITER Project",
      "text": "In 1985, the ITER (International Thermonuclear Experimental Reactor) project was proposed as an international collaboration to demonstrate the feasibility of nuclear fusion as a large-scale and carbon-free source of energy.",
      "date": "1985"
    },
    {
      "headline": "Construction of ITER Begins",
      "text": "In 2007, construction of the ITER facility began in Cadarache, France, marking a significant step towards achieving practical nuclear fusion energy.",
      "date": "2007"
    },
    {
      "headline": "First Plasma in ITER",
      "text": "ITER is expected to achieve its first plasma in 2025, marking the beginning of its operational phase to demonstrate the feasibility of nuclear fusion as a power source.",
      "date": "2025"
    }
  ]
}

