{
  "timeline": [
    {
      "headline": "Berlin Conference",
      "text": "The Berlin Conference, held from November 15, 1884, to February 26, 1885, was organized by Otto von Bismarck, the Chancellor of Germany, to regulate European colonization and trade in Africa during the New Imperialism period. It resulted in the General Act of the Berlin Conference, which formalized the Scramble for Africa.",
      "date": "1884-11-15"
    },
    {
      "headline": "General Act of the Berlin Conference",
      "text": "On February 26, 1885, the General Act of the Berlin Conference was signed. It laid down the rules for the colonization of Africa, including the principle of effective occupation, which required European powers to establish authority in the areas they claimed.",
      "date": "1885-02-26"
    },
    {
      "headline": "Congo Free State Established",
      "text": "In 1885, King Leopold II of Belgium established the Congo Free State as his private possession, which marked a significant moment in the Scramble for Africa. The exploitation and atrocities committed in the Congo Free State later became infamous.",
      "date": "1885"
    },
    {
      "headline": "Anglo-Zulu War",
      "text": "The Anglo-Zulu War took place in 1879 between the British Empire and the Zulu Kingdom. The war resulted in the British annexation of the Zulu Kingdom, furthering British colonial interests in Southern Africa.",
      "date": "1879"
    },
    {
      "headline": "Battle of Adwa",
      "text": "On March 1, 1896, the Battle of Adwa took place between Ethiopian forces and Italian invaders. The Ethiopian victory secured Ethiopian sovereignty and is considered a significant event in resisting European colonization.",
      "date": "1896-03-01"
    },
    {
      "headline": "Fashoda Incident",
      "text": "The Fashoda Incident occurred in 1898 when French and British forces met in Fashoda (now Kodok, South Sudan). The confrontation was resolved diplomatically, and it marked the end of the territorial disputes between France and Britain in Africa.",
      "date": "1898"
    },
    {
      "headline": "Boer War Begins",
      "text": "The Second Boer War began on October 11, 1899, between the British Empire and the two Boer states: the South African Republic and the Orange Free State. It was part of the British efforts to consolidate control over South Africa.",
      "date": "1899-10-11"
    },
    {
      "headline": "Treaty of Vereeniging",
      "text": "The Treaty of Vereeniging was signed on May 31, 1902, ending the Second Boer War. The treaty resulted in the annexation of the Boer republics into the British Empire, furthering British dominance in Southern Africa.",
      "date": "1902-05-31"
    },
    {
      "headline": "Moroccan Crisis",
      "text": "The First Moroccan Crisis occurred in 1905-1906, involving a dispute between France and Germany over the status of Morocco. It was resolved at the Algeciras Conference, which upheld French interests in Morocco.",
      "date": "1905"
    }
  ]
}

