{
  "timeline": [
    {
      "headline": "Founding of AIADMK",
      "text": "The All India Anna Dravida Munnetra Kazhagam (AIADMK) was founded by M. G. Ramachandran (M.G.R.) on 17 October 1972 in Madurai. It was established as a breakaway faction from the Dravida Munnetra Kazhagam (DMK) after M. Karunanidhi expelled M.G.R. from the party.",
      "date": "1972-10-17"
    },
    {
      "headline": "First Electoral Victory",
      "text": "In 1977, the AIADMK won its first major electoral victory in the Tamil Nadu Legislative Assembly elections, securing a majority and forming the government with M.G.R. as the Chief Minister.",
      "date": "1977"
    },
    {
      "headline": "M.G.R.'s Tenure as Chief Minister",
      "text": "M.G.R. served as the Chief Minister of Tamil Nadu from 1977 until his death in 1987, leading the AIADMK to multiple electoral victories during this period.",
      "date": "1977"
    },
    {
      "headline": "Death of M.G. Ramachandran",
      "text": "M.G. Ramachandran, the founder of AIADMK and Chief Minister of Tamil Nadu, passed away on 24 December 1987.",
      "date": "1987-12-24"
    },
    {
      "headline": "Leadership of J. Jayalalithaa",
      "text": "After M.G.R.'s death, J. Jayalalithaa emerged as the leader of the AIADMK. She became the first woman to serve as the Chief Minister of Tamil Nadu in 1991.",
      "date": "1991"
    },
    {
      "headline": "Jayalalithaa's Tenure as Chief Minister",
      "text": "J. Jayalalithaa served multiple terms as the Chief Minister of Tamil Nadu, with her leadership spanning from 1991-1996, 2001-2006, 2011-2014, and 2015 until her death in 2016.",
      "date": "1991"
    },
    {
      "headline": "Death of J. Jayalalithaa",
      "text": "J. Jayalalithaa, the long-serving leader of the AIADMK and Chief Minister of Tamil Nadu, passed away on 5 December 2016.",
      "date": "2016-12-05"
    },
    {
      "headline": "AIADMK as Opposition",
      "text": "Following the 2021 Tamil Nadu Legislative Assembly elections, the AIADMK became the main opposition party in the Tamil Nadu Legislative Assembly.",
      "date": "2021"
    }
  ]
}

