{
  "timeline": [
    {
      "headline": "Origins of Neoconservatism",
      "text": "Neoconservatism began in the United States during the 1960s among liberal hawks who became disenchanted with the increasingly pacifist Democratic Party along with the growing New Left and counterculture of the 1960s.",
      "date": "1960"
    },
    {
      "headline": "Irving Kristol's Influence",
      "text": "Irving Kristol, often called the 'godfather of neoconservatism,' played a significant role in shaping the movement. His writings and ideas in the 1970s helped define neoconservative thought.",
      "date": "1970"
    },
    {
      "headline": "Formation of the Committee on the Present Danger",
      "text": "In 1976, the Committee on the Present Danger was formed by neoconservatives to advocate for a stronger stance against the Soviet Union, emphasizing the need for increased defense spending and a more assertive foreign policy.",
      "date": "1976"
    },
    {
      "headline": "Neoconservatism in the Reagan Administration",
      "text": "During the 1980s, neoconservatives gained influence in the Reagan administration, advocating for a hardline stance against the Soviet Union and promoting the idea of 'peace through strength.'",
      "date": "1980"
    },
    {
      "headline": "Project for the New American Century",
      "text": "In 1997, the Project for the New American Century (PNAC) was founded by leading neoconservatives, advocating for American global leadership and military strength.",
      "date": "1997"
    },
    {
      "headline": "Influence on the George W. Bush Administration",
      "text": "Neoconservatives played a significant role in shaping the foreign policy of the George W. Bush administration, particularly in the decision to invade Iraq in 2003.",
      "date": "2003"
    },
    {
      "headline": "Decline of Neoconservatism",
      "text": "Following the challenges and controversies of the Iraq War, neoconservatism faced criticism and a decline in influence during the late 2000s and 2010s.",
      "date": "2008"
    }
  ]
}

