{
  "timeline": [
    {
      "headline": "First Aliyah",
      "text": "The First Aliyah took place between 1882 and 1903. It was the first modern widespread wave of Zionist immigration to Palestine, then a part of the Ottoman Empire, and involved approximately 25,000–35,000 Jews, who mainly came from Eastern Europe and Yemen.",
      "date": "1882"
    },
    {
      "headline": "Second Aliyah",
      "text": "The Second Aliyah occurred between 1904 and 1914. Approximately 20,000–40,000 Jews immigrated to Palestine, primarily from Russia and Poland, driven by pogroms and anti-Semitic policies in Eastern Europe.",
      "date": "1904"
    },
    {
      "headline": "Third Aliyah",
      "text": "The Third Aliyah took place from 1919 to 1923, following World War I and the Balfour Declaration. Around 35,000 Jews, mainly from Eastern Europe, immigrated to Palestine, contributing to the establishment of the kibbutz movement and the Histadrut.",
      "date": "1919"
    },
    {
      "headline": "Fourth Aliyah",
      "text": "The Fourth Aliyah occurred between 1924 and 1928. Approximately 82,000 Jews, primarily from Poland and Hungary, immigrated to Palestine due to economic hardship and anti-Semitic policies in their home countries.",
      "date": "1924"
    },
    {
      "headline": "Fifth Aliyah",
      "text": "The Fifth Aliyah took place from 1929 to 1939, with around 250,000 Jews immigrating to Palestine. This wave was largely driven by the rise of Nazism in Germany and anti-Semitic policies in Europe.",
      "date": "1929"
    },
    {
      "headline": "Aliyah Bet",
      "text": "Aliyah Bet refers to the clandestine immigration of Jews to Palestine between 1934 and 1948, circumventing British immigration restrictions. It involved approximately 110,000 Jews, many of whom were Holocaust survivors.",
      "date": "1934"
    },
    {
      "headline": "Establishment of the State of Israel",
      "text": "On May 14, 1948, the State of Israel was established, leading to a significant increase in Jewish immigration, as Jews from around the world made aliyah to the newly founded state.",
      "date": "1948-05-14"
    },
    {
      "headline": "Operation Magic Carpet",
      "text": "Operation Magic Carpet was conducted between June 1949 and September 1950, airlifting approximately 49,000 Yemenite Jews to Israel.",
      "date": "1949-06"
    },
    {
      "headline": "Operation Ezra and Nehemiah",
      "text": "Between 1950 and 1952, Operation Ezra and Nehemiah brought over 120,000 Iraqi Jews to Israel, following increased persecution and anti-Jewish sentiment in Iraq.",
      "date": "1950"
    },
    {
      "headline": "Law of Return Enacted",
      "text": "The Law of Return was enacted by the Israeli Knesset on July 5, 1950, granting Jews the right to immigrate to Israel and gain citizenship.",
      "date": "1950-07-05"
    },
    {
      "headline": "Operation Moses",
      "text": "Operation Moses took place from November 21, 1984, to January 5, 1985, and involved the airlifting of approximately 8,000 Ethiopian Jews from Sudan to Israel.",
      "date": "1984-11-21"
    },
    {
      "headline": "Operation Solomon",
      "text": "On May 24-25, 1991, Operation Solomon airlifted about 14,500 Ethiopian Jews to Israel in a 36-hour period, amid political instability in Ethiopia.",
      "date": "1991-05-24"
    }
  ]
}

