{
  "timeline": [
    {
      "headline": "First Recorded Use of Endoscopy",
      "text": "The first recorded use of an endoscopic device was in 1806 by Philipp Bozzini, who developed a crude light-guiding instrument called the 'Lichtleiter' to examine the urinary tract, rectum, and pharynx.",
      "date": "1806"
    },
    {
      "headline": "Development of the Gastroscope",
      "text": "In 1868, Adolf Kussmaul performed the first esophagogastroduodenoscopy on a sword swallower using a rigid endoscope, marking the development of the gastroscope.",
      "date": "1868"
    },
    {
      "headline": "Introduction of the Flexible Endoscope",
      "text": "In 1932, Rudolf Schindler developed a semi-flexible gastroscope, which significantly improved the ability to examine the stomach.",
      "date": "1932"
    },
    {
      "headline": "Fiber Optic Endoscope Innovation",
      "text": "In 1957, Basil Hirschowitz and Larry Curtiss developed the first fiber optic endoscope, revolutionizing the field by allowing for more flexible and less invasive procedures.",
      "date": "1957"
    },
    {
      "headline": "Introduction of Video Endoscopy",
      "text": "In the 1980s, video endoscopy was introduced, allowing for the capture of images and videos during procedures, greatly enhancing diagnostic capabilities.",
      "date": "1980"
    },
    {
      "headline": "Advancements in Capsule Endoscopy",
      "text": "In 2000, capsule endoscopy was introduced, allowing for the examination of the small intestine using a swallowable camera capsule.",
      "date": "2000"
    }
  ]
}

