{
  "timeline": [
    {
      "headline": "Loving v. Virginia",
      "text": "In 1967, the Supreme Court of the United States ruled in Loving v. Virginia that marriage is a fundamental right guaranteed by both the Due Process Clause and the Equal Protection Clause of the Fourteenth Amendment.",
      "date": "1967"
    },
    {
      "headline": "Massachusetts Legalizes Same-Sex Marriage",
      "text": "On May 17, 2004, Massachusetts became the first U.S. state to legalize same-sex marriage following the Supreme Judicial Court's decision in Goodridge v. Department of Public Health.",
      "date": "2004-05-17"
    },
    {
      "headline": "California Supreme Court Legalizes Same-Sex Marriage",
      "text": "On May 15, 2008, the California Supreme Court ruled in In re Marriage Cases that same-sex couples have a constitutional right to marry.",
      "date": "2008-05-15"
    },
    {
      "headline": "Proposition 8 in California",
      "text": "On November 4, 2008, California voters approved Proposition 8, a ballot initiative that banned same-sex marriage in the state.",
      "date": "2008-11-04"
    },
    {
      "headline": "Iowa Supreme Court Legalizes Same-Sex Marriage",
      "text": "On April 3, 2009, the Iowa Supreme Court unanimously ruled in Varnum v. Brien that the state's ban on same-sex marriage was unconstitutional.",
      "date": "2009-04-03"
    },
    {
      "headline": "Vermont Legalizes Same-Sex Marriage",
      "text": "On September 1, 2009, Vermont became the first state to legalize same-sex marriage through legislative action.",
      "date": "2009-09-01"
    },
    {
      "headline": "New York Legalizes Same-Sex Marriage",
      "text": "On June 24, 2011, New York legalized same-sex marriage through legislative action, becoming the largest state at the time to do so.",
      "date": "2011-06-24"
    },
    {
      "headline": "United States v. Windsor",
      "text": "On June 26, 2013, the Supreme Court ruled in United States v. Windsor that the Defense of Marriage Act's definition of marriage as only between a man and a woman was unconstitutional.",
      "date": "2013-06-26"
    },
    {
      "headline": "Obergefell v. Hodges",
      "text": "On June 26, 2015, the Supreme Court ruled in Obergefell v. Hodges that same-sex marriage is a constitutional right, legalizing it across all fifty states.",
      "date": "2015-06-26"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Gustav Klimt",
      "text": "Gustav Klimt was born on July 14, 1862, in Baumgarten, near Vienna, Austria.",
      "date": "1862-07-14"
    },
    {
      "headline": "Enrollment at Vienna School of Arts and Crafts",
      "text": "In 1876, Klimt enrolled at the Vienna School of Arts and Crafts, where he studied until 1883.",
      "date": "1876"
    },
    {
      "headline": "Formation of the Company of Artists",
      "text": "In 1883, Klimt, his brother Ernst, and their friend Franz Matsch formed a team of artists known as the 'Company of Artists' (Künstler-Compagnie).",
      "date": "1883"
    },
    {
      "headline": "Awarded the Golden Order of Merit",
      "text": "In 1888, Klimt was awarded the Golden Order of Merit by Emperor Franz Josef I of Austria for his contributions to art.",
      "date": "1888"
    },
    {
      "headline": "Founding of the Vienna Secession",
      "text": "In 1897, Klimt became one of the founding members of the Vienna Secession, an art movement that sought to break away from traditional academic art.",
      "date": "1897"
    },
    {
      "headline": "Creation of 'Philosophy', 'Medicine', and 'Jurisprudence'",
      "text": "Between 1899 and 1907, Klimt created three paintings, 'Philosophy', 'Medicine', and 'Jurisprudence', for the ceiling of the Great Hall of the University of Vienna. These works were controversial and faced criticism for their radical style.",
      "date": "1899"
    },
    {
      "headline": "Completion of 'The Kiss'",
      "text": "In 1908, Klimt completed one of his most famous works, 'The Kiss', which is considered a masterpiece of the early 20th century.",
      "date": "1908"
    },
    {
      "headline": "Exhibition at the Kunstschau",
      "text": "In 1908, Klimt exhibited 'The Kiss' at the Kunstschau, an art exhibition in Vienna.",
      "date": "1908"
    },
    {
      "headline": "Death of Gustav Klimt",
      "text": "Gustav Klimt died on February 6, 1918, in Vienna, Austria, after suffering a stroke and pneumonia.",
      "date": "1918-02-06"
    }
  ]
}

