    {
      "headline": "Publication of the First Surrealist Manifesto",
      "text": "In 1924, André Breton published the First Surrealist Manifesto, which officially launched the Surrealist movement. The manifesto defined Surrealism as a means of reuniting conscious and unconscious realms of experience.",
      "date": "1924"
    },
    {
      "headline": "Foundation of La Révolution surréaliste",
      "text": "In December 1924, the first issue of La Révolution surréaliste was published. This magazine became the primary publication for Surrealist ideas and works.",
      "date": "1924-12"
    },
    {
      "headline": "Surrealist Exhibition in Paris",
      "text": "In 1925, the first Surrealist exhibition was held at the Galerie Pierre in Paris, showcasing works by artists such as Max Ernst, Man Ray, and Joan Miró.",
      "date": "1925"
    },
    {
      "headline": "Publication of Nadja by André Breton",
      "text": "In 1928, André Breton published 'Nadja', a novel that became one of the most important works of Surrealist literature, exploring themes of love and madness.",
      "date": "1928"
    },
    {
      "headline": "The Second Surrealist Manifesto",
      "text": "In 1929, André Breton published the Second Surrealist Manifesto, further defining the movement and addressing internal conflicts within the group.",
      "date": "1929"
    },
    {
      "headline": "International Surrealist Exhibition in London",
      "text": "In 1936, the International Surrealist Exhibition was held in London, marking the movement's expansion beyond France. It featured works by Salvador Dalí, René Magritte, and others.",
      "date": "1936"
    },
    {
      "headline": "Exposition Internationale du Surréalisme",
      "text": "In 1938, the Exposition Internationale du Surréalisme was held in Paris, organized by André Breton and Paul Éluard, featuring installations and performances.",
      "date": "1938"
    },
    {
      "headline": "Surrealism and World War II",
      "text": "During World War II, many Surrealists fled Europe, with several, including André Breton, relocating to the United States, where they continued to influence art and culture.",
      "date": "1939-1945"
    },
    {
      "headline": "Post-War Surrealism",
      "text": "After World War II, Surrealism continued to influence new generations of artists and writers, although the movement itself began to decline as a cohesive group.",
      "date": "1945"
    }
  ]
}

