    },
    {
      "headline": "The Dreyfus Affair",
      "text": "The Dreyfus Affair, a political scandal that divided France, began in 1894 when Captain Alfred Dreyfus was wrongfully convicted of treason. It highlighted issues of anti-Semitism and injustice within the French military and society.",
      "date": "1894"
    },
    {
      "headline": "Separation of Church and State",
      "text": "In 1905, the French Third Republic enacted the law on the Separation of the Churches and the State, establishing state secularism and ending the funding of religious groups by the state.",
      "date": "1905"
    },
    {
      "headline": "World War I",
      "text": "France was a major participant in World War I from 1914 to 1918, fighting alongside the Allies against the Central Powers. The war had significant social and economic impacts on the country.",
      "date": "1914"
