{
  "timeline": [
    {
      "headline": "Origin of Canidae Family",
      "text": "The Canidae family originated approximately 40 million years ago during the Eocene epoch. This family of dog-like carnivorans is part of the order Carnivora.",
      "date": "-40000000"
    },
    {
      "headline": "Emergence of Hesperocyoninae Subfamily",
      "text": "The Hesperocyoninae subfamily, one of the earliest subfamilies of Canidae, emerged around 40 million years ago. They were small, fox-like animals.",
      "date": "-40000000"
    },
    {
      "headline": "Emergence of Borophaginae Subfamily",
      "text": "The Borophaginae subfamily, known as 'bone-crushing dogs', appeared around 34 million years ago. They were more robust and larger than their predecessors.",
      "date": "-34000000"
    },
    {
      "headline": "Emergence of Caninae Subfamily",
      "text": "The Caninae subfamily, which includes modern dogs, wolves, and foxes, emerged around 34 million years ago. This subfamily is the only surviving lineage of the Canidae family.",
      "date": "-34000000"
    },
    {
      "headline": "Extinction of Hesperocyoninae Subfamily",
      "text": "The Hesperocyoninae subfamily became extinct approximately 15 million years ago during the Miocene epoch.",
      "date": "-15000000"
    },
    {
      "headline": "Extinction of Borophaginae Subfamily",
      "text": "The Borophaginae subfamily went extinct around 2 million years ago, leaving the Caninae as the sole surviving subfamily of the Canidae family.",
      "date": "-2000000"
    },
    {
      "headline": "Domestication of Dogs",
      "text": "The domestication of dogs from wolves is believed to have occurred between 20,000 and 40,000 years ago, marking a significant event in the history of the Caninae subfamily.",
      "date": "-20000"
    }
  ]
}

