    },
    {
      "headline": "Covers the Assassination of John F. Kennedy",
      "text": "On November 22, 1963, Cronkite famously reported the assassination of President John F. Kennedy, delivering the news with his signature calm and authoritative demeanor.",
      "date": "1963-11-22"
    },
    {
      "headline": "Covers the Moon Landing",
      "text": "On July 20, 1969, Cronkite covered the Apollo 11 moon landing, providing live commentary as Neil Armstrong became the first human to set foot on the moon.",
      "date": "1969-07-20"
