    {
      "headline": "Vietnam War Commentary",
      "text": "In 1968, after the Tet Offensive, Cronkite delivered a critical commentary on the Vietnam War, suggesting that it might end in a stalemate. This broadcast is often cited as influential in changing public opinion about the war.",
      "date": "1968"
    },
    {
      "headline": "Retirement from CBS Evening News",
      "text": "Walter Cronkite retired from the CBS Evening News on March 6, 1981, and was succeeded by Dan Rather.",
      "date": "1981-03-06"
