    {
      "headline": "Awarded Presidential Medal of Freedom",
      "text": "In 1981, Walter Cronkite was awarded the Presidential Medal of Freedom by President Jimmy Carter for his contributions to journalism.",
      "date": "1981"
    },
    {
      "headline": "Death of Walter Cronkite",
