      "headline": "Yom Kippur War Begins",
      "text": "On October 6, 1973, Egypt and Syria launched a surprise attack on Israel, marking the beginning of the Yom Kippur War.",
      "date": "1973-10-06"
    },
    {
      "headline": "OAPEC Announces Oil Embargo",
      "text": "In October 1973, the Organization of Arab Petroleum Exporting Countries (OAPEC) announced a total oil embargo against countries that supported Israel during the Yom Kippur War.",
      "date": "1973-10"
    },
    {
      "headline": "Countries Targeted by Embargo",
      "text": "The initial countries targeted by the OAPEC embargo were Canada, Japan, the Netherlands, the United Kingdom, and the United States. The list was later expanded to include Portugal, Rhodesia, and South Africa.",
      "date": "1973-10"
    },
    {
      "headline": "Oil Prices Skyrocket",
      "text": "By the end of the embargo, the price of oil had risen by nearly 300%, from US$3 per barrel to nearly US$12 per barrel globally.",
      "date": "1973-10"
    },
    {
      "headline": "Embargo Lifted",
      "text": "In March 1974, OAPEC lifted the oil embargo, but the effects on the global economy and politics were long-lasting.",
      "date": "1974-03"
    }
  ]
}

