{
  "timeline": [
    {
      "headline": "Development of Cuneiform",
      "text": "Cuneiform was developed around 3400 BCE in the ancient city of Uruk in southern Mesopotamia. It was initially created to write the Sumerian language.",
      "date": "-3400"
    },
    {
      "headline": "Early Dynastic Period",
      "text": "During the Early Dynastic Period (2900–2350 BCE), cuneiform was used extensively for administrative and economic purposes, as well as for recording literature and historical events.",
      "date": "-2900"
    },
    {
      "headline": "Akkadian Adoption",
      "text": "Around 2500 BCE, the Akkadians adopted cuneiform to write their Semitic language, marking the first time the script was used for a language other than Sumerian.",
      "date": "-2500"
    },
    {
      "headline": "Old Babylonian Period",
      "text": "In the Old Babylonian Period (2000–1600 BCE), cuneiform was used to write Akkadian, and it became the lingua franca of the Near East.",
      "date": "-2000"
    },
    {
      "headline": "Hittite Cuneiform",
      "text": "By 1600 BCE, the Hittites had adapted cuneiform to write their Indo-European language, marking its spread beyond Mesopotamia.",
      "date": "-1600"
    },
    {
      "headline": "Neo-Assyrian Empire",
      "text": "During the Neo-Assyrian Empire (911–609 BCE), cuneiform was used for official inscriptions, royal decrees, and scholarly texts.",
      "date": "-0911"
    },
    {
      "headline": "Decline of Cuneiform",
      "text": "By the 1st century CE, cuneiform had largely fallen out of use, replaced by alphabetic scripts. The last known cuneiform inscription dates to 75 CE.",
      "date": "0075"
    }
  ]
}

