      "headline": "Became a Member of the Central Committee",
      "text": "In 1921, Molotov became a full member of the Central Committee of the Communist Party.",
      "date": "1921"
    },
    {
      "headline": "Appointed Chairman of the Council of People's Commissars",
      "text": "Molotov was appointed Chairman of the Council of People's Commissars (Premier) of the Soviet Union in 1930, a position he held until 1941.",
      "date": "1930"
    },
    {
      "headline": "Molotov–Ribbentrop Pact",
      "text": "On August 23, 1939, Molotov, as Minister of Foreign Affairs, signed the Molotov–Ribbentrop Pact, a non-aggression treaty between the Soviet Union and Nazi Germany.",
      "date": "1939-08-23"
    },
    {
      "headline": "End of Tenure as Chairman of the Council of People's Commissars",
      "text": "Molotov's tenure as Chairman of the Council of People's Commissars ended in 1941.",
      "date": "1941"
    },
    {
      "headline": "Served as Minister of Foreign Affairs",
      "text": "Molotov served as the Minister of Foreign Affairs of the Soviet Union from 1939 to 1949, and again from 1953 to 1956.",
      "date": "1939"
    },
    {
      "headline": "Dismissal from Minister of Foreign Affairs",
      "text": "Molotov was dismissed from his position as Minister of Foreign Affairs in 1949.",
      "date": "1949"
    },
    {
      "headline": "Reappointed as Minister of Foreign Affairs",
      "text": "Molotov was reappointed as Minister of Foreign Affairs in 1953, following Stalin's death.",
      "date": "1953"
    },
    {
      "headline": "Final Dismissal from Minister of Foreign Affairs",
      "text": "Molotov was finally dismissed from his position as Minister of Foreign Affairs in 1956.",
      "date": "1956"
