    {
      "headline": "Emergence of the Huguenots",
      "text": "The Huguenots emerged as a distinct group of French Protestants who adhered to the Reformed (Calvinist) tradition during the Protestant Reformation in the mid-16th century.",
      "date": "1550"
    },
    {
      "headline": "First Huguenot War",
      "text": "The First Huguenot War began in 1562, marking the start of a series of religious conflicts in France known as the French Wars of Religion.",
      "date": "1562"
    },
    {
      "headline": "St. Bartholomew's Day Massacre",
      "text": "On August 24, 1572, the St. Bartholomew's Day Massacre occurred, where thousands of Huguenots were killed in Paris and throughout France.",
      "date": "1572-08-24"
    },
    {
      "headline": "Edict of Nantes",
      "text": "In 1598, King Henry IV of France issued the Edict of Nantes, granting substantial rights and freedoms to the Huguenots, effectively ending the French Wars of Religion.",
      "date": "1598"
    },
    {
      "headline": "Revocation of the Edict of Nantes",
      "text": "On October 18, 1685, King Louis XIV revoked the Edict of Nantes with the Edict of Fontainebleau, leading to renewed persecution of Huguenots and the emigration of many to other countries.",
      "date": "1685-10-18"
    },
    {
      "headline": "Huguenot Diaspora",
      "text": "Following the revocation of the Edict of Nantes, many Huguenots fled France, establishing communities in countries such as the Netherlands, England, Prussia, and the American colonies.",
      "date": "1685"
    },
    {
      "headline": "Edict of Versailles",
      "text": "In 1787, King Louis XVI issued the Edict of Versailles, also known as the Edict of Tolerance, which restored civil rights to the Huguenots in France.",
      "date": "1787"
    }
  ]
}

