{
  "timeline": [
    {
      "headline": "Formation of the Eastern Bloc",
      "text": "The Eastern Bloc was formed in the aftermath of World War II, as the Soviet Union established communist governments in Central and Eastern Europe. This process began in 1947, marking the start of the Cold War.",
      "date": "1947"
    },
    {
      "headline": "Cominform Established",
      "text": "In September 1947, the Communist Information Bureau (Cominform) was established to coordinate actions between Communist parties under Soviet direction.",
      "date": "1947-09"
    },
    {
      "headline": "Berlin Blockade and Airlift",
      "text": "From June 24, 1948, to May 12, 1949, the Soviet Union blocked the Western Allies' railway, road, and canal access to the sectors of Berlin under Western control. The Western Allies responded with the Berlin Airlift to supply the city.",
      "date": "1948-06-24"
    },
    {
      "headline": "Warsaw Pact Formed",
      "text": "On May 14, 1955, the Warsaw Pact was established as a collective defense treaty among eight communist states of Central and Eastern Europe during the Cold War.",
      "date": "1955-05-14"
    },
    {
      "headline": "Hungarian Revolution",
      "text": "In October 1956, a nationwide revolution against the Hungarian People's Republic and its Soviet-imposed policies erupted. It was brutally suppressed by Soviet forces.",
      "date": "1956-10"
    },
    {
      "headline": "Prague Spring",
      "text": "In 1968, the Prague Spring was a period of political liberalization in Czechoslovakia during its domination by the Soviet Union. It ended with the invasion of Czechoslovakia by Warsaw Pact troops in August 1968.",
      "date": "1968-08"
    },
    {
      "headline": "Solidarity Movement in Poland",
      "text": "In August 1980, the Solidarity movement, a trade union and social movement, was founded in Poland, challenging the communist government and gaining significant support.",
      "date": "1980-08"
    },
    {
      "headline": "Fall of the Berlin Wall",
      "text": "On November 9, 1989, the Berlin Wall fell, symbolizing the end of the Cold War and leading to the collapse of communist regimes in Central and Eastern Europe.",
      "date": "1989-11-09"
    },
    {
      "headline": "Dissolution of the Eastern Bloc",
      "text": "The Eastern Bloc effectively dissolved in 1991 with the collapse of the Soviet Union and the end of communist rule in Central and Eastern Europe.",
      "date": "1991"
    }
  ]
}

