    {
      "headline": "Founding of Creative Commons",
      "text": "Creative Commons was founded in 2001 by Lawrence Lessig, Hal Abelson, and Eric Eldred with support from the Center for the Public Domain. The organization was established to expand the range of creative works available for others to build upon legally and to share.",
      "date": "2001"
    },
    {
      "headline": "Release of First Creative Commons Licenses",
      "text": "In December 2002, Creative Commons released its first set of copyright licenses. These licenses allow authors to communicate which rights they reserve and which rights they waive for the benefit of recipients or other creators.",
      "date": "2002-12"
    },
    {
      "headline": "Launch of CC0 License",
      "text": "In 2009, Creative Commons introduced the CC0 license, which allows creators to waive all their copyright and related rights in their works, effectively placing them in the public domain.",
      "date": "2009"
    },
    {
      "headline": "Creative Commons 4.0 Licenses Released",
      "text": "In November 2013, Creative Commons released version 4.0 of its licenses. These licenses were designed to be more internationally applicable and to better accommodate the needs of users and creators.",
      "date": "2013-11"
    },
    {
      "headline": "Creative Commons Global Summit",
      "text": "In 2015, Creative Commons held its Global Summit in Seoul, South Korea, bringing together a diverse group of individuals and organizations to discuss the future of open access and sharing.",
      "date": "2015"
    },
    {
      "headline": "CC Search Launched",
      "text": "In 2019, Creative Commons launched CC Search, a tool that allows users to search for openly licensed and public domain content across multiple platforms.",
      "date": "2019"
    }
  ]
}

