{
  "timeline": [
    {
      "headline": "Acadian Settlement in Canada",
      "text": "The Acadians, ancestors of the Cajuns, originally settled in the region of Acadia in Canada, which includes parts of present-day Nova Scotia, New Brunswick, and Prince Edward Island. This settlement began in the early 1600s.",
      "date": "1600"
    },
    {
      "headline": "Treaty of Utrecht",
      "text": "The Treaty of Utrecht in 1713 resulted in Acadia being ceded to Great Britain, which led to tensions between the British and the Acadian settlers.",
      "date": "1713"
    },
    {
      "headline": "The Great Expulsion (Le Grand Dérangement)",
      "text": "Between 1755 and 1764, the British forcibly expelled the Acadians from their homeland in Canada. This event is known as the Great Expulsion or Le Grand Dérangement.",
      "date": "1755"
    },
    {
      "headline": "Arrival in Louisiana",
      "text": "Many Acadians settled in Louisiana after being expelled from Canada. The first groups arrived in Louisiana in 1764, where they eventually became known as Cajuns.",
      "date": "1764"
    },
    {
      "headline": "Spanish Rule in Louisiana",
      "text": "During the late 18th century, Louisiana was under Spanish rule, which allowed the Acadians to settle and thrive, preserving their culture and language.",
      "date": "1769"
    },
    {
      "headline": "Louisiana Purchase",
      "text": "In 1803, the United States acquired Louisiana from France through the Louisiana Purchase, which brought the Cajuns under American governance.",
      "date": "1803"
    },
    {
      "headline": "Cajun Cultural Revival",
      "text": "In the 20th century, there was a revival of Cajun culture, including music, language, and cuisine, which gained wider recognition and appreciation.",
      "date": "1900"
    },
    {
      "headline": "CODOFIL Establishment",
      "text": "The Council for the Development of French in Louisiana (CODOFIL) was established in 1968 to promote and preserve the French language and Cajun culture in Louisiana.",
      "date": "1968"
    }
  ]
}

