      "headline": "Founding of Quebec City",
      "text": "Quebec City was founded by Samuel de Champlain on July 3, 1608. It was established as a permanent settlement and trading post.",
      "date": "1608-07-03"
    },
    {
      "headline": "Battle of Quebec",
      "text": "The Battle of Quebec took place on September 13, 1759, during the Seven Years' War. British forces under General James Wolfe defeated French troops led by the Marquis de Montcalm.",
      "date": "1759-09-13"
    },
    {
      "headline": "Quebec Act",
      "text": "The Quebec Act was passed in 1774, which expanded the territory of Quebec and restored French civil law while maintaining British criminal law.",
      "date": "1774"
    },
    {
      "headline": "Quebec City becomes the capital",
      "text": "In 1867, Quebec City was designated as the capital of the newly formed province of Quebec when Canada became a confederation.",
      "date": "1867"
    },
    {
      "headline": "Quebec Conference",
      "text": "The Quebec Conference was held in 1864, where discussions took place that led to the formation of the Canadian Confederation.",
      "date": "1864"
    },
    {
      "headline": "Quebec Bridge Collapse",
      "text": "The Quebec Bridge collapsed on August 29, 1907, during construction, resulting in the deaths of 75 workers.",
      "date": "1907-08-29"
    },
    {
      "headline": "Winter Carnival Established",
      "text": "The Quebec Winter Carnival, one of the largest and most famous winter festivals in the world, was first held in 1955.",
      "date": "1955"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1985, Old Quebec was designated a UNESCO World Heritage Site, recognizing its historical significance and well-preserved architecture.",
      "date": "1985"
    },
    {
      "headline": "400th Anniversary Celebrations",
      "text": "Quebec City celebrated its 400th anniversary in 2008 with a series of events and festivities throughout the year.",
      "date": "2008"
    }
  ]
}

