{
  "timeline": [
    {
      "headline": "Domestication of Coca",
      "text": "Coca plants were first domesticated in the Andes mountains of South America. The exact date is unknown, but it is believed to have been cultivated by indigenous peoples for thousands of years.",
      "date": "-3000"
    },
    {
      "headline": "Coca in Inca Civilization",
      "text": "Coca leaves were an important part of Inca culture, used in religious ceremonies and as a form of currency. The use of coca was restricted to the nobility and religious leaders.",
      "date": "1400"
    },
    {
      "headline": "Spanish Conquest and Coca",
      "text": "During the Spanish conquest of the Inca Empire, the Spanish initially banned coca but later encouraged its use among indigenous laborers in the mines to increase productivity.",
      "date": "1533"
    },
    {
      "headline": "Scientific Study of Coca",
      "text": "In the 19th century, European scientists began studying coca and its effects. In 1859, Albert Niemann isolated cocaine, the active alkaloid in coca leaves.",
      "date": "1859"
    },
    {
      "headline": "Coca-Cola and Coca",
      "text": "Coca leaves were used in the original formula of Coca-Cola, invented by John Stith Pemberton in 1886. The drink initially contained cocaine, which was later removed in the early 20th century.",
      "date": "1886"
    },
    {
      "headline": "International Regulation of Coca",
      "text": "The 1961 Single Convention on Narcotic Drugs classified coca leaves as a Schedule I substance, leading to increased regulation and control of coca cultivation and distribution.",
      "date": "1961"
    },
    {
      "headline": "Cultural and Economic Impact",
      "text": "Coca remains a significant cultural and economic crop in South America, particularly in countries like Bolivia, Peru, and Colombia, where it is legally grown for traditional uses.",
      "date": "2023"
    }
  ]
}

