{
  "timeline": [
    {
      "headline": "Design and Development",
      "text": "The T-34 was designed by the Kharkiv Morozov Machine Building Design Bureau in the late 1930s. It was intended to replace the BT series of fast tanks.",
      "date": "1937"
    },
    {
      "headline": "First Prototype Completed",
      "text": "The first prototype of the T-34, known as the A-32, was completed in January 1940. It featured sloped armor and a 76.2 mm gun.",
      "date": "1940-01"
