    {
      "headline": "First Congo War",
      "text": "In 1996-1997, the First Congo War led to the overthrow of Mobutu Sese Seko, impacting Kinshasa as it became a center of political activity.",
      "date": "1996"
    },
    {
      "headline": "Second Congo War",
      "text": "From 1998 to 2003, the Second Congo War, also known as the Great African War, affected Kinshasa, although the city remained under government control.",
      "date": "1998"
    },
    {
      "headline": "Modern Growth",
      "text": "In the 21st century, Kinshasa has experienced rapid population growth, becoming one of the world's fastest-growing megacities.",
      "date": "2000"
    },
