    {
      "headline": "Indian Reservation System Established",
      "text": "The Indian reservation system was established in the United States during the 1850s as a means to manage relations with Native American tribes and to facilitate westward expansion by European settlers.",
      "date": "1850"
    },
    {
      "headline": "Dawes Act Enacted",
      "text": "On February 8, 1887, the Dawes Act was enacted, allowing for the division of tribal lands into individual allotments and the sale of surplus land to non-Native Americans. This resulted in significant fragmentation of reservation lands.",
      "date": "1887-02-08"
    },
    {
      "headline": "Indian Reorganization Act",
      "text": "The Indian Reorganization Act was passed on June 18, 1934, reversing the Dawes Act's policy of assimilation and allotment. It aimed to restore some self-governance to tribes and halt the sale of tribal lands.",
      "date": "1934-06-18"
    },
    {
      "headline": "Termination Policy",
      "text": "In the 1950s, the U.S. government adopted a policy of terminating the recognition of certain tribes, ending federal support and services. This policy led to the loss of tribal lands and sovereignty for many tribes.",
      "date": "1950"
    },
    {
      "headline": "Self-Determination Era",
      "text": "Beginning in the 1970s, the U.S. government shifted towards a policy of self-determination, allowing tribes greater control over their own affairs and resources. This era was marked by legislation such as the Indian Self-Determination and Education Assistance Act of 1975.",
      "date": "1970"
    },
    {
      "headline": "Indian Gaming Regulatory Act",
      "text": "The Indian Gaming Regulatory Act was passed on October 17, 1988, allowing tribes to operate gaming facilities on their reservations, which became a significant source of revenue for many tribes.",
      "date": "1988-10-17"
    }
  ]
}

