{
  "timeline": [
    {
      "headline": "Formation of State Legislative Assemblies",
      "text": "The State Legislative Assemblies in India were formed as part of the constitutional framework established by the Constitution of India, which came into effect on January 26, 1950. These assemblies serve as the legislative bodies in each of the states and certain union territories.",
      "date": "1950-01-26"
    },
    {
      "headline": "Bicameral Legislatures in Six States",
      "text": "In six Indian states, the legislative assembly serves as the lower house of a bicameral legislature, with the upper house being the State Legislative Council. These states include Bihar, Karnataka, Maharashtra, Telangana, Andhra Pradesh, and Uttar Pradesh.",
      "date": "1950"
    },
    {
      "headline": "Unicameral Legislatures in 28 States and 3 Union Territories",
      "text": "In 28 states and 3 union territories, the legislative assembly is the sole legislative body, making these legislatures unicameral.",
      "date": "1950"
    },
    {
      "headline": "Direct Governance by Union Government",
      "text": "Five union territories in India are governed directly by the Union Government and do not have a legislative assembly. These territories include Chandigarh, Lakshadweep, Dadra and Nagar Haveli and Daman and Diu, Andaman and Nicobar Islands, and Ladakh.",
      "date": "1950"
    },
    {
      "headline": "Reorganization of States",
      "text": "The States Reorganisation Act, 1956, led to the reorganization of state boundaries and the creation of new states, affecting the composition and number of state legislative assemblies.",
      "date": "1956-11-01"
    },
    {
      "headline": "Creation of New States and Assemblies",
      "text": "Over the years, new states have been created in India, leading to the establishment of new legislative assemblies. Notable examples include the creation of Chhattisgarh, Uttarakhand, and Jharkhand in 2000, and Telangana in 2014.",
      "date": "2000"
    }
  ]
}

