{
  "timeline": [
    {
      "headline": "Publication of General Relativity",
      "text": "Albert Einstein published the general theory of relativity in 1915, revolutionizing the understanding of gravity by describing it as a geometric property of space and time.",
      "date": "1915"
    },
    {
      "headline": "Einstein Field Equations",
      "text": "The Einstein field equations, which are a set of ten interrelated differential equations, were introduced in 1915 as part of the general theory of relativity. They describe how matter and energy in the universe influence the curvature of spacetime.",
      "date": "1915"
    },
    {
      "headline": "Confirmation of General Relativity",
      "text": "In 1919, during a solar eclipse, Arthur Eddington's expedition confirmed the predictions of general relativity by observing the bending of light from stars around the Sun, providing one of the first empirical validations of the theory.",
      "date": "1919"
    },
    {
      "headline": "Introduction of Black Holes",
      "text": "The concept of black holes, regions of spacetime exhibiting such strong gravitational effects that nothing can escape from inside it, was derived from the solutions to the Einstein field equations in the early 20th century, with significant contributions from Karl Schwarzschild in 1916.",
      "date": "1916"
    },
    {
      "headline": "Development of Cosmological Models",
      "text": "General relativity laid the foundation for modern cosmology, including the development of models of an expanding universe, notably by Alexander Friedmann in 1922 and Georges Lemaître in 1927.",
      "date": "1922"
    },
    {
      "headline": "Gravitational Waves Predicted",
      "text": "In 1916, Albert Einstein predicted the existence of gravitational waves, ripples in spacetime caused by some of the most violent and energetic processes in the universe.",
      "date": "1916"
    },
    {
      "headline": "First Direct Detection of Gravitational Waves",
      "text": "On September 14, 2015, the LIGO observatory made the first direct detection of gravitational waves, confirming a major prediction of general relativity and opening a new era in astrophysics.",
      "date": "2015-09-14"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First European Sightings",
      "text": "In 1616, Dutch explorer Dirk Hartog became the first European to land on the western coast of Australia, at what is now known as Shark Bay.",
      "date": "1616"
    },
    {
      "headline": "British Claim",
      "text": "In 1829, the British claimed the western third of the Australian continent and established the Swan River Colony, which later became known as Western Australia.",
