{
  "timeline": [
    {
      "headline": "Cuban Coup d'état",
      "text": "On March 10, 1952, Fulgencio Batista led a military coup d'état, overthrowing the Cuban government and establishing a dictatorship.",
      "date": "1952-03-10"
    },
    {
      "headline": "Attack on Moncada Barracks",
      "text": "On July 26, 1953, Fidel Castro and his brother Raúl led an armed attack on the Moncada Barracks in Santiago de Cuba, marking the beginning of the Cuban Revolution.",
      "date": "1953-07-26"
    },
    {
      "headline": "Castro's Trial and 'History Will Absolve Me' Speech",
      "text": "In October 1953, Fidel Castro was put on trial for the Moncada attack. He delivered his famous 'History Will Absolve Me' speech, defending his actions.",
      "date": "1953-10"
    },
    {
      "headline": "Castro's Imprisonment and Release",
      "text": "Fidel Castro was sentenced to 15 years in prison but was released in May 1955 as part of a general amnesty.",
      "date": "1955-05"
    },
    {
      "headline": "Castro's Exile to Mexico",
      "text": "After his release, Fidel Castro went into exile in Mexico, where he planned the next phase of the revolution.",
      "date": "1955"
    },
    {
      "headline": "Formation of the 26th of July Movement",
      "text": "In 1955, Fidel Castro formed the 26th of July Movement, named after the Moncada attack, to overthrow Batista.",
      "date": "1955"
    },
    {
      "headline": "Granma Expedition",
      "text": "On November 25, 1956, Fidel Castro and 81 revolutionaries set sail from Mexico to Cuba aboard the yacht Granma to start a guerrilla war.",
      "date": "1956-11-25"
    },
    {
      "headline": "Landing in Cuba",
      "text": "The Granma landed in Cuba on December 2, 1956, but the group was ambushed, and only a few, including Fidel and Raúl Castro, survived.",
      "date": "1956-12-02"
    },
    {
      "headline": "Guerrilla Warfare in the Sierra Maestra",
      "text": "From 1956 to 1958, Fidel Castro and his forces engaged in guerrilla warfare against Batista's army in the Sierra Maestra mountains.",
      "date": "1956"
    },
    {
      "headline": "Battle of La Plata",
      "text": "In July 1958, the rebels won the Battle of La Plata, marking a significant victory in the guerrilla campaign.",
      "date": "1958-07"
    },
    {
      "headline": "Battle of Santa Clara",
      "text": "On December 28, 1958, the Battle of Santa Clara began, leading to a decisive victory for the revolutionaries and the fall of Batista's regime.",
      "date": "1958-12-28"
    },
    {
      "headline": "Batista Flees Cuba",
      "text": "On January 1, 1959, Fulgencio Batista fled Cuba, marking the end of his dictatorship and the success of the Cuban Revolution.",
      "date": "1959-01-01"
    },
    {
      "headline": "Castro's Entry into Havana",
      "text": "On January 8, 1959, Fidel Castro and his forces entered Havana, solidifying the victory of the Cuban Revolution.",
      "date": "1959-01-08"
    }
  ]
}

