{
  "timeline": [
    {
      "headline": "Introduction of Convolutional Neural Networks",
      "text": "Convolutional Neural Networks (CNNs) were introduced in the 1980s by Yann LeCun and others. They were inspired by biological processes and are a type of artificial neural network used primarily in image processing.",
      "date": "1980"
    },
    {
      "headline": "Development of LeNet-5",
      "text": "In 1998, Yann LeCun and his collaborators developed LeNet-5, one of the first convolutional neural networks, which was used for character recognition tasks such as reading zip codes and digits.",
      "date": "1998"
    },
    {
      "headline": "AlexNet Wins ImageNet Competition",
      "text": "In 2012, AlexNet, a deep convolutional neural network developed by Alex Krizhevsky, Ilya Sutskever, and Geoffrey Hinton, won the ImageNet Large Scale Visual Recognition Challenge (ILSVRC) with a top-5 error rate of 15.3%, significantly outperforming the second place.",
      "date": "2012"
    },
    {
      "headline": "Introduction of VGGNet",
      "text": "In 2014, the Visual Geometry Group from the University of Oxford introduced VGGNet, a CNN architecture that emphasized depth using very small (3x3) convolution filters.",
      "date": "2014"
    },
    {
      "headline": "GoogleNet and Inception Modules",
      "text": "In 2014, Google introduced GoogleNet, which used inception modules to improve computational efficiency and accuracy in CNNs, winning the ILSVRC 2014.",
      "date": "2014"
    },
    {
      "headline": "ResNet and the Introduction of Residual Learning",
      "text": "In 2015, Microsoft Research introduced ResNet, a deep residual network that allowed for the training of networks with over 150 layers, winning the ILSVRC 2015 with a top-5 error rate of 3.57%.",
      "date": "2015"
    },
    {
      "headline": "Introduction of DenseNet",
      "text": "In 2017, DenseNet was introduced, which connected each layer to every other layer in a feed-forward fashion, improving efficiency and reducing the number of parameters.",
      "date": "2017"
    },
    {
      "headline": "CNNs in Various Applications",
      "text": "By the late 2010s, CNNs had become the de-facto standard for image processing tasks and were applied in various fields including medical image analysis, autonomous vehicles, and more.",
      "date": "2010s"
    }
  ]
}

