    {
      "headline": "Start of the Mexican Revolution",
      "text": "The Mexican Revolution began on November 20, 1910, as a response to the long-standing dictatorship of Porfirio Díaz and widespread social inequalities.",
      "date": "1910-11-20"
    },
    {
      "headline": "Plan of San Luis Potosí",
      "text": "On November 20, 1910, Francisco I. Madero issued the Plan of San Luis Potosí, calling for the overthrow of Díaz and the restoration of democracy.",
      "date": "1910-11-20"
    },
    {
      "headline": "Porfirio Díaz Resigns",
      "text": "On May 25, 1911, Porfirio Díaz resigned from the presidency and went into exile in France, marking the end of his 35-year rule.",
      "date": "1911-05-25"
    },
    {
      "headline": "Francisco I. Madero Becomes President",
      "text": "Francisco I. Madero was elected President of Mexico and took office on November 6, 1911, after the resignation of Díaz.",
      "date": "1911-11-06"
    },
    {
      "headline": "Assassination of Francisco I. Madero",
      "text": "On February 22, 1913, Francisco I. Madero was assassinated during a coup led by Victoriano Huerta.",
      "date": "1913-02-22"
    },
    {
      "headline": "Victoriano Huerta's Regime",
      "text": "Victoriano Huerta assumed power after the assassination of Madero, ruling as a dictator from February 1913 until his resignation in July 1914.",
      "date": "1913-02"
    },
    {
      "headline": "Huerta Resigns",
      "text": "Victoriano Huerta resigned from the presidency on July 15, 1914, under pressure from revolutionary forces and the United States.",
      "date": "1914-07-15"
    },
    {
      "headline": "Constitution of 1917",
      "text": "The Mexican Constitution of 1917 was promulgated on February 5, 1917, establishing a framework for land reform, labor rights, and the separation of church and state.",
      "date": "1917-02-05"
    },
    {
      "headline": "End of the Mexican Revolution",
      "text": "The Mexican Revolution officially ended on December 1, 1920, when Álvaro Obregón assumed the presidency, marking the beginning of a period of relative stability.",
      "date": "1920-12-01"
    }
  ]
}

