{
  "timeline": [
    {
      "headline": "Origin of the Term 'Third World'",
      "text": "The term 'Third World' was coined by French demographer Alfred Sauvy in an article published in the French magazine L'Observateur on August 14, 1952. Sauvy used the term to describe countries that were not aligned with either the capitalist NATO bloc or the communist Soviet bloc during the Cold War.",
      "date": "1952-08-14"
    },
    {
      "headline": "Bandung Conference",
      "text": "The Bandung Conference, held in April 1955 in Bandung, Indonesia, was a meeting of Asian and African states, most of which were newly independent. The conference was an important step in the development of the concept of the Third World, as it brought together countries that were neither aligned with the United States nor the Soviet Union.",
      "date": "1955-04"
    },
    {
      "headline": "Formation of the Non-Aligned Movement",
      "text": "In 1961, the Non-Aligned Movement was formally established in Belgrade, Yugoslavia. It was a group of states that were not formally aligned with or against any major power bloc. This movement became closely associated with the concept of the Third World.",
      "date": "1961"
    },
    {
      "headline": "Decline of the Term 'Third World'",
      "text": "By the end of the Cold War in 1991, the term 'Third World' began to decline in usage. The geopolitical landscape had changed, and the term was increasingly seen as outdated and pejorative.",
      "date": "1991"
    }
  ]
}

