    {
      "headline": "Inaugural DFB-Pokal Competition",
      "text": "The first DFB-Pokal competition took place in 1935. It was initially called the Tschammer-Pokal, named after Hans von Tschammer und Osten, the Reichssportführer at the time.",
      "date": "1935"
    },
    {
      "headline": "First DFB-Pokal Winner",
      "text": "The first winner of the DFB-Pokal was 1. FC Nürnberg, who won the competition in 1935.",
      "date": "1935"
    },
    {
      "headline": "Competition Halted Due to World War II",
      "text": "The DFB-Pokal was not held from 1944 to 1952 due to World War II and its aftermath.",
      "date": "1944"
    },
    {
      "headline": "Resumption of the DFB-Pokal",
      "text": "The DFB-Pokal resumed in 1952 after an eight-year hiatus due to World War II.",
      "date": "1952"
    },
    {
      "headline": "Renaming to DFB-Pokal",
      "text": "In 1952, the competition was renamed from Tschammer-Pokal to DFB-Pokal.",
      "date": "1952"
    },
    {
      "headline": "Introduction of Bundesliga Teams",
      "text": "With the formation of the Bundesliga in 1963, all Bundesliga teams began participating in the DFB-Pokal.",
      "date": "1963"
    },
    {
      "headline": "First Double Winner",
      "text": "In 1969, Bayern Munich became the first team to win both the Bundesliga and the DFB-Pokal in the same season.",
      "date": "1969"
    },
    {
      "headline": "DFB-Pokal Format Change",
      "text": "In 1974, the DFB-Pokal format was changed to include 128 teams, allowing more amateur teams to participate.",
      "date": "1974"
    },
    {
      "headline": "Introduction of Penalty Shootouts",
      "text": "In 1977, penalty shootouts were introduced to decide matches that ended in a draw after extra time.",
      "date": "1977"
    },
    {
      "headline": "Women's DFB-Pokal Established",
      "text": "The Women's DFB-Pokal was established in 1980, providing a similar knockout competition for women's football teams in Germany.",
      "date": "1980"
    },
    {
      "headline": "DFB-Pokal Final Moved to Berlin",
      "text": "Since 1985, the DFB-Pokal final has been held at the Olympiastadion in Berlin.",
      "date": "1985"
    },
    {
      "headline": "Introduction of 3. Liga Teams",
      "text": "In 2008, the format was adjusted to include the top four teams from the newly established 3. Liga.",
      "date": "2008"
    }
  ]
}

