    {
      "headline": "Development of V-2 Rocket Begins",
      "text": "The development of the V-2 rocket, initially known as the Aggregat 4 (A4), began in Nazi Germany as part of a military project to create a long-range guided ballistic missile.",
      "date": "1930s"
    },
    {
      "headline": "First Successful Launch",
      "text": "The first successful launch of the V-2 rocket took place on 3 October 1942 at Peenemünde, Germany. This marked a significant milestone in rocket technology.",
      "date": "1942-10-03"
    },
    {
      "headline": "First Rocket to Reach Space",
      "text": "On 20 June 1944, the V-2 rocket MW 18014 became the first artificial object to travel into space by crossing the Kármán line, the boundary of space, during a vertical test launch.",
      "date": "1944-06-20"
    },
    {
      "headline": "Operational Use in World War II",
      "text": "The V-2 rocket was used operationally by Nazi Germany starting in September 1944, targeting Allied cities such as London and Antwerp as a form of retaliation for Allied bombings.",
      "date": "1944-09"
    },
    {
      "headline": "End of World War II and V-2 Rocket Program",
      "text": "With the end of World War II in May 1945, the V-2 rocket program came to an end. Many of the scientists involved, including Wernher von Braun, were captured by Allied forces and later contributed to rocket development in the United States and the Soviet Union.",
      "date": "1945-05"
    }
  ]
}

