{
  "timeline": [
    {
      "headline": "Bretton Woods Conference",
      "text": "The Bretton Woods Conference, formally known as the United Nations Monetary and Financial Conference, was held from July 1 to July 22, 1944. Delegates from 44 Allied nations gathered at the Mount Washington Hotel in Bretton Woods, New Hampshire, to create a new international monetary order.",
      "date": "1944-07-01"
    },
    {
      "headline": "Establishment of the Bretton Woods System",
      "text": "The Bretton Woods system was established in 1944 following the conference. It set up a system of fixed exchange rates with the U.S. dollar as the central currency, convertible to gold at $35 per ounce. This system aimed to promote international economic stability and prevent competitive devaluations.",
      "date": "1944"
    },
    {
      "headline": "Creation of the International Monetary Fund (IMF)",
      "text": "As part of the Bretton Woods Agreement, the International Monetary Fund (IMF) was established in December 1945. The IMF was created to monitor exchange rates and lend reserve currencies to nations with balance of payments deficits.",
      "date": "1945-12"
    },
    {
      "headline": "Creation of the International Bank for Reconstruction and Development (IBRD)",
      "text": "The International Bank for Reconstruction and Development (IBRD), now part of the World Bank Group, was also established in 1944 as a result of the Bretton Woods Conference. It was created to provide financial and technical assistance for the reconstruction of war-torn Europe and the development of other countries.",
      "date": "1944"
    },
    {
      "headline": "End of the Bretton Woods System",
      "text": "The Bretton Woods system effectively ended in 1971 when President Richard Nixon announced the suspension of the dollar's convertibility into gold, a move known as the 'Nixon Shock.' This led to the transition to a system of floating exchange rates.",
      "date": "1971"
    }
  ]
}

