{
  "timeline": [
    {
      "headline": "Formation of LTTE",
      "text": "The Liberation Tigers of Tamil Eelam (LTTE) was founded in May 1976 by Velupillai Prabhakaran. The organization aimed to create an independent Tamil state called Tamil Eelam in the northeast of Sri Lanka.",
      "date": "1976-05"
    },
    {
      "headline": "First Major Attack",
      "text": "On July 23, 1983, the LTTE ambushed a Sri Lankan Army patrol in Jaffna, killing 13 soldiers. This attack is considered the start of the Sri Lankan Civil War.",
      "date": "1983-07-23"
    },
    {
      "headline": "Indian Peace Keeping Force (IPKF) Intervention",
      "text": "In July 1987, the Indian government intervened in the Sri Lankan Civil War by sending the Indian Peace Keeping Force (IPKF) to enforce a peace accord. The LTTE initially agreed but later engaged in conflict with the IPKF.",
      "date": "1987-07"
    },
    {
      "headline": "Assassination of Rajiv Gandhi",
      "text": "On May 21, 1991, the LTTE assassinated former Indian Prime Minister Rajiv Gandhi in Tamil Nadu, India, using a suicide bomber. This act led to the LTTE being banned in India.",
      "date": "1991-05-21"
    },
    {
      "headline": "Assassination of Sri Lankan President Ranasinghe Premadasa",
      "text": "On May 1, 1993, the LTTE assassinated Sri Lankan President Ranasinghe Premadasa in Colombo using a suicide bomber.",
      "date": "1993-05-01"
    },
    {
      "headline": "Capture of Elephant Pass",
      "text": "In April 2000, the LTTE captured the strategic Elephant Pass, which connects the Jaffna Peninsula to the rest of Sri Lanka, marking a significant military victory for the organization.",
      "date": "2000-04"
    },
    {
      "headline": "Ceasefire Agreement",
      "text": "On February 22, 2002, a ceasefire agreement was signed between the LTTE and the Sri Lankan government, brokered by Norway. This led to a temporary halt in hostilities.",
      "date": "2002-02-22"
    },
    {
      "headline": "Resumption of Hostilities",
      "text": "In July 2006, hostilities resumed between the LTTE and the Sri Lankan government, effectively ending the ceasefire agreement.",
      "date": "2006-07"
    },
    {
      "headline": "Defeat of LTTE",
      "text": "On May 18, 2009, the Sri Lankan government declared victory over the LTTE after a military campaign that resulted in the death of LTTE leader Velupillai Prabhakaran and the collapse of the LTTE's control over its territories.",
      "date": "2009-05-18"
    }
  ]
}

