{
  "timeline": [
    {
      "headline": "Origins of Feng Shui",
      "text": "Feng Shui originated in Ancient China, with its principles being developed over thousands of years. It is believed to have started as early as the Neolithic period, with the practice of aligning structures with the stars and natural features.",
      "date": "-5000"
    },
    {
      "headline": "Development during the Zhou Dynasty",
      "text": "During the Zhou Dynasty (1046–256 BCE), Feng Shui principles were further developed and formalized. The Book of Burial, a classic text on Feng Shui, was written during this period, emphasizing the importance of aligning tombs with the natural environment.",
      "date": "-1046"
    },
    {
      "headline": "Han Dynasty Advancements",
      "text": "In the Han Dynasty (206 BCE–220 CE), Feng Shui practices became more sophisticated with the integration of cosmology and astrology. The use of the Luopan, a Feng Shui compass, became prevalent during this time.",
      "date": "-0206"
    },
    {
      "headline": "Tang Dynasty and Feng Shui Masters",
      "text": "The Tang Dynasty (618–907 CE) saw the rise of famous Feng Shui masters like Yang Yunsong, who contributed significantly to the development of Feng Shui theories and practices.",
      "date": "0618"
    },
    {
      "headline": "Song Dynasty and the Form School",
      "text": "During the Song Dynasty (960–1279 CE), the Form School of Feng Shui was developed, focusing on the physical shape and form of the environment, such as mountains and water bodies.",
      "date": "0960"
    },
    {
      "headline": "Ming Dynasty and the Compass School",
      "text": "The Ming Dynasty (1368–1644 CE) saw the rise of the Compass School, which emphasized the use of the Luopan compass and the importance of directional influences in Feng Shui.",
      "date": "1368"
    },
    {
      "headline": "Modernization and Global Spread",
      "text": "In the 20th century, Feng Shui began to spread globally, influenced by modern interpretations and adaptations. It became popular in Western countries, where it was often integrated with interior design and architecture.",
      "date": "1900"
    }
  ]
}

