      "headline": "First Implementation of Daylight Saving Time",
      "text": "Daylight saving time was first implemented in the United States during World War I, starting on March 31, 1918, as a measure to conserve energy.",
      "date": "1918-03-31"
    },
    {
      "headline": "Repeal of Daylight Saving Time",
      "text": "After World War I, daylight saving time was repealed on March 31, 1919, due to its unpopularity.",
      "date": "1919-03-31"
    },
    {
      "headline": "Reintroduction During World War II",
      "text": "Daylight saving time was reintroduced on February 9, 1942, during World War II, as a year-round measure to conserve resources.",
      "date": "1942-02-09"
    },
    {
      "headline": "End of Year-Round Daylight Saving Time",
      "text": "The year-round daylight saving time ended on September 30, 1945, after the conclusion of World War II.",
      "date": "1945-09-30"
    },
    {
      "headline": "Uniform Time Act of 1966",
      "text": "The Uniform Time Act was signed into law on April 13, 1966, establishing a uniform system of daylight saving time throughout the United States.",
      "date": "1966-04-13"
    },
    {
      "headline": "Energy Crisis and Year-Round Daylight Saving Time",
      "text": "In response to the 1973 oil embargo, the United States observed year-round daylight saving time from January 6, 1974, to April 27, 1975.",
      "date": "1974-01-06"
    },
    {
      "headline": "Energy Policy Act of 2005",
      "text": "The Energy Policy Act of 2005 extended daylight saving time in the United States, starting in 2007, from the second Sunday in March to the first Sunday in November.",
      "date": "2005"
    }
  ]
}

