{
  "timeline": [
    {
      "headline": "Signing of the Molotov–Ribbentrop Pact",
      "text": "The Molotov–Ribbentrop Pact, officially the Treaty of Non-Aggression between Germany and the Union of Soviet Socialist Republics, was signed in Moscow on 24 August 1939 by Soviet Foreign Minister Vyacheslav Molotov and German Foreign Minister Joachim von Ribbentrop. This pact included a secret protocol that divided Eastern Europe into German and Soviet spheres of influence.",
      "date": "1939-08-24"
    },
    {
      "headline": "Secret Protocol of the Pact",
      "text": "The secret protocol of the Molotov–Ribbentrop Pact outlined the division of territories in Eastern Europe between Nazi Germany and the Soviet Union. This included the partitioning of Poland and the assignment of the Baltic States and parts of Romania to the Soviet sphere of influence.",
      "date": "1939-08-24"
    },
    {
      "headline": "Invasion of Poland",
      "text": "On 1 September 1939, Germany invaded Poland from the west, marking the beginning of World War II. This invasion was followed by the Soviet invasion from the east on 17 September 1939, as per the secret protocol of the Molotov–Ribbentrop Pact.",
      "date": "1939-09-01"
    },
    {
      "headline": "Soviet Invasion of Poland",
      "text": "On 17 September 1939, the Soviet Union invaded Poland from the east, in accordance with the secret protocol of the Molotov–Ribbentrop Pact, leading to the division and occupation of Poland by Germany and the Soviet Union.",
      "date": "1939-09-17"
    },
    {
      "headline": "Annexation of the Baltic States",
      "text": "In June 1940, the Soviet Union occupied and subsequently annexed the Baltic States of Estonia, Latvia, and Lithuania, as outlined in the secret protocol of the Molotov–Ribbentrop Pact.",
      "date": "1940-06"
    },
    {
      "headline": "Operation Barbarossa",
      "text": "On 22 June 1941, Nazi Germany launched Operation Barbarossa, invading the Soviet Union and effectively breaking the Molotov–Ribbentrop Pact.",
      "date": "1941-06-22"
    }
  ]
}

