      "headline": "Discovery by Europeans",
      "text": "Bikini Atoll was first sighted by Europeans in 1529 by Spanish explorer Álvaro de Saavedra.",
      "date": "1529"
    },
    {
      "headline": "German Annexation",
      "text": "In 1885, Bikini Atoll was annexed by the German Empire as part of German New Guinea.",
      "date": "1885"
    },
    {
      "headline": "Japanese Control",
      "text": "Following World War I, Bikini Atoll was placed under Japanese control as part of the South Seas Mandate in 1919.",
      "date": "1919"
    },
    {
      "headline": "U.S. Administration",
      "text": "After World War II, in 1944, the United States took control of Bikini Atoll from Japan.",
      "date": "1944"
    },
    {
      "headline": "Nuclear Testing Begins",
      "text": "On March 7, 1946, the United States began nuclear testing at Bikini Atoll, starting with Operation Crossroads.",
      "date": "1946-03-07"
    },
    {
      "headline": "Castle Bravo Test",
      "text": "On March 1, 1954, the United States conducted the Castle Bravo test at Bikini Atoll, the largest nuclear explosion ever conducted by the U.S.",
      "date": "1954-03-01"
    },
    {
      "headline": "End of Nuclear Testing",
      "text": "The last nuclear test at Bikini Atoll was conducted in 1958, marking the end of nuclear testing on the atoll.",
      "date": "1958"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 2010, Bikini Atoll was declared a UNESCO World Heritage Site due to its historical significance related to nuclear testing.",
      "date": "2010"
    }
  ]
}

