{
  "timeline": [
    {
      "headline": "Petrarch's Birth",
      "text": "Francesco Petrarca, commonly anglicized as Petrarch, was born on July 20, 1304. He is often considered the father of Humanism.",
      "date": "1304-07-20"
    },
    {
      "headline": "Petrarch's Letter to Posterity",
      "text": "Around 1370, Petrarch wrote his 'Letter to Posterity', which is considered one of the earliest expressions of humanist thought.",
      "date": "1370"
    },
    {
      "headline": "The Fall of Constantinople",
      "text": "The Fall of Constantinople in 1453 led to the migration of Greek scholars to the West, bringing with them classical texts that fueled the Renaissance and humanist thought.",
      "date": "1453"
    },
    {
      "headline": "Publication of 'Oration on the Dignity of Man'",
      "text": "In 1486, Giovanni Pico della Mirandola published 'Oration on the Dignity of Man', a key text of Renaissance humanism.",
      "date": "1486"
    },
    {
      "headline": "Erasmus's 'In Praise of Folly'",
      "text": "In 1509, Desiderius Erasmus wrote 'In Praise of Folly', a critical work that reflects humanist ideals.",
      "date": "1509"
    },
    {
      "headline": "Thomas More's 'Utopia'",
      "text": "In 1516, Thomas More published 'Utopia', a work that explores humanist themes through the depiction of an ideal society.",
      "date": "1516"
    },
    {
      "headline": "The Reformation Begins",
      "text": "The Protestant Reformation began in 1517, influenced by humanist ideas that emphasized personal faith and the reading of scriptures.",
      "date": "1517"
    },
    {
      "headline": "Montaigne's 'Essays'",
      "text": "Michel de Montaigne published his 'Essays' in 1580, which are considered a significant contribution to humanist literature.",
      "date": "1580"
    },
    {
      "headline": "Galileo's Trial",
      "text": "In 1633, Galileo Galilei was tried by the Inquisition for his support of heliocentrism, a conflict between science and religious doctrine that highlighted humanist values of inquiry and evidence.",
      "date": "1633"
    },
    {
      "headline": "The Enlightenment",
      "text": "The Enlightenment, spanning the late 17th to the 18th century, was heavily influenced by humanist principles, emphasizing reason, science, and individual rights.",
      "date": "1700"
    },
