{
  "timeline": [
    {
      "headline": "Theoretical Foundation of Lasers",
      "text": "In 1958, Charles H. Townes and Arthur Leonard Schawlow published a paper on the theoretical foundation of lasers, proposing the concept of optical masers.",
      "date": "1958"
    },
    {
      "headline": "First Laser Built",
      "text": "On May 16, 1960, Theodore Maiman built the first operational laser at Hughes Research Laboratories, using a synthetic ruby crystal.",
      "date": "1960-05-16"
    },
    {
      "headline": "First Gas Laser",
      "text": "In December 1960, Ali Javan, William R. Bennett Jr., and Donald Herriott developed the first gas laser, a helium-neon laser, at Bell Labs.",
      "date": "1960-12"
    },
    {
      "headline": "First Semiconductor Laser",
      "text": "In 1962, Robert N. Hall and his team at General Electric developed the first semiconductor laser, which was made of gallium arsenide.",
      "date": "1962"
    },
    {
      "headline": "First Dye Laser",
      "text": "In 1966, Peter Sorokin and J. R. Lankard at IBM developed the first dye laser, which used organic dyes as the lasing medium.",
      "date": "1966"
    },
    {
      "headline": "First CO2 Laser",
      "text": "In 1964, Kumar Patel at Bell Labs developed the first carbon dioxide (CO2) laser, which became widely used for industrial cutting and welding.",
      "date": "1964"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "In 1964, Charles H. Townes, along with Nikolay Basov and Alexander Prokhorov, was awarded the Nobel Prize in Physics for fundamental work in the field of quantum electronics, which led to the construction of oscillators and amplifiers based on the maser-laser principle.",
      "date": "1964"
    }
  ]
}

