{
  "timeline": [
    {
      "headline": "Earliest Known Use of Egyptian Language",
      "text": "The Egyptian language is first attested around 3300 BCE in the form of hieroglyphs on pottery and other artifacts.",
      "date": "-3300"
    },
    {
      "headline": "Old Egyptian Period",
      "text": "Old Egyptian, the earliest stage of the language, was used during the Old Kingdom of Egypt, approximately from 2686 to 2181 BCE.",
      "date": "-2686"
    },
    {
      "headline": "Middle Egyptian Period",
      "text": "Middle Egyptian, often referred to as Classical Egyptian, was used from around 2055 to 1650 BCE. It became the literary language of ancient Egypt.",
      "date": "-2055"
    },
    {
      "headline": "Late Egyptian Period",
      "text": "Late Egyptian was used from around 1350 to 700 BCE. It shows significant changes in grammar and vocabulary from Middle Egyptian.",
      "date": "-1350"
    },
    {
      "headline": "Demotic Egyptian",
      "text": "Demotic Egyptian, a later stage of the language, was used from around 650 BCE to the 5th century CE. It was the language of daily life and administration.",
      "date": "-0650"
    },
    {
      "headline": "Coptic Egyptian",
      "text": "Coptic, the final stage of the Egyptian language, emerged around the 2nd century CE and was used until at least the 17th century CE. It is written in the Coptic alphabet, derived from the Greek alphabet.",
      "date": "0200"
    },
    {
      "headline": "Decipherment of Egyptian Scripts",
      "text": "The ancient Egyptian scripts were deciphered in the early 19th century, notably by Jean-François Champollion in 1822, using the Rosetta Stone.",
      "date": "1822"
    }
  ]
}

