    {
      "headline": "Founding of Ur",
      "text": "Ur was founded during the Ubaid period, around 3800 BCE. It became an important Sumerian city-state in ancient Mesopotamia.",
      "date": "-3800"
    },
    {
      "headline": "Ur as a City-State",
      "text": "Ur is recorded in written history as a city-state from the 26th century BCE. It was a significant urban center in Sumer.",
      "date": "-2600"
    },
    {
      "headline": "Reign of King Tuttues",
      "text": "King Tuttues is recorded as the first king of Ur, ruling during the 26th century BCE.",
      "date": "-2600"
    },
    {
      "headline": "Third Dynasty of Ur",
      "text": "The Third Dynasty of Ur, also known as the Ur III period, was a Sumerian ruling dynasty based in the city of Ur. It lasted from approximately 2112 BCE to 2004 BCE.",
      "date": "-2112"
    },
    {
      "headline": "Reign of Ur-Nammu",
      "text": "Ur-Nammu founded the Third Dynasty of Ur and is known for creating the Code of Ur-Nammu, one of the earliest known law codes, around 2100 BCE.",
      "date": "-2100"
    },
    {
      "headline": "Construction of the Great Ziggurat of Ur",
      "text": "The Great Ziggurat of Ur was constructed during the reign of King Ur-Nammu around 2100 BCE. It served as a temple complex dedicated to the moon god Nanna.",
      "date": "-2100"
    },
    {
      "headline": "Reign of Shulgi",
      "text": "Shulgi, son of Ur-Nammu, ruled from 2094 BCE to 2047 BCE. He is known for his administrative reforms and military campaigns.",
      "date": "-2094"
    },
    {
      "headline": "Fall of the Third Dynasty of Ur",
      "text": "The Third Dynasty of Ur fell around 2004 BCE due to invasions by the Elamites and internal strife.",
      "date": "-2004"
    },
    {
      "headline": "Ur under Babylonian Control",
      "text": "After the fall of the Third Dynasty, Ur came under the control of various powers, including the Babylonians, around 1900 BCE.",
      "date": "-1900"
    },
    {
      "headline": "Decline of Ur",
      "text": "Ur began to decline as a major city around 500 BCE due to shifting trade routes and changing political landscapes.",
      "date": "-0500"
    }
  ]
}

