{
  "timeline": [
    {
      "headline": "Foundation of the Order",
      "text": "The Order of Saint John of Jerusalem was founded around 1048, originally as a hospital in Jerusalem to provide care for sick, poor, or injured pilgrims to the Holy Land.",
      "date": "1048"
    },
    {
      "headline": "Recognition by the Pope",
      "text": "In 1113, Pope Paschal II issued a papal bull recognizing the Order of Saint John of Jerusalem as a religious order of the Church, granting it independence and protection.",
      "date": "1113"
    },
    {
      "headline": "Establishment in Rhodes",
      "text": "In 1310, after being driven from the Holy Land, the Order established itself on the island of Rhodes, where it became a sovereign power.",
      "date": "1310"
    },
    {
      "headline": "Siege of Rhodes",
      "text": "In 1522, the Order faced a major siege by the Ottoman Empire, led by Sultan Suleiman the Magnificent, which resulted in the Order's expulsion from Rhodes.",
      "date": "1522"
    },
    {
      "headline": "Settlement in Malta",
      "text": "In 1530, the Order was granted the islands of Malta, Gozo, and Tripoli by Charles V, Holy Roman Emperor, establishing its new base of operations.",
      "date": "1530"
    },
    {
      "headline": "Great Siege of Malta",
      "text": "In 1565, the Order successfully defended Malta against a massive siege by the Ottoman Empire, a pivotal event in its history.",
      "date": "1565"
    },
    {
      "headline": "Loss of Malta",
      "text": "In 1798, Napoleon Bonaparte captured Malta during his campaign in the Mediterranean, forcing the Order to leave the island.",
      "date": "1798"
    },
    {
      "headline": "Establishment in Rome",
      "text": "After losing Malta, the Order established its headquarters in Rome, where it continues to operate today.",
      "date": "1834"
    },
    {
      "headline": "UN Observer Status",
      "text": "In 1994, the Sovereign Military Order of Malta was granted observer status at the United Nations, recognizing its humanitarian efforts.",
      "date": "1994"
    }
  ]
}

