    {
      "headline": "Wardrobe Malfunction Incident",
      "text": "During the halftime show on February 1, 2004, Justin Timberlake accidentally exposed Janet Jackson's right breast and nipple, adorned with a nipple shield, to the viewing public. The incident became known as 'Nipplegate' or 'Janetgate'.",
      "date": "2004-02-01"
    },
    {
      "headline": "FCC Crackdown on Indecency",
      "text": "Following the incident on February 1, 2004, the Federal Communications Commission (FCC) launched an immediate crackdown on perceived indecency in broadcasting, leading to increased fines and stricter regulations.",
      "date": "2004-02"
