{
  "timeline": [
    {
      "headline": "First Use of Air Force One Call Sign",
      "text": "The call sign 'Air Force One' was first used in 1953 after a commercial flight (Eastern Air Lines Flight 8610) entered the same airspace as the president's plane, which had a similar call sign. To avoid confusion, the unique call sign 'Air Force One' was created for any aircraft carrying the U.S. President.",
      "date": "1953"
    },
    {
      "headline": "Introduction of the Boeing 707 as Air Force One",
      "text": "In 1959, the Boeing 707 SAM 970 was introduced as the first jet aircraft to serve as Air Force One. It was used by President Dwight D. Eisenhower.",
      "date": "1959"
    },
    {
      "headline": "Introduction of the VC-137C",
      "text": "In 1962, the VC-137C, a modified Boeing 707, was introduced as the primary aircraft for Air Force One. It was famously used by President John F. Kennedy.",
      "date": "1962"
    },
    {
      "headline": "Introduction of the VC-25A",
      "text": "In 1990, the Boeing VC-25A, a modified Boeing 747-200B, was introduced as the primary aircraft for Air Force One. Two aircraft, tail numbers 28000 and 29000, were delivered and have been used by every president since George H. W. Bush.",
      "date": "1990"
    },
    {
      "headline": "Announcement of New Air Force One Aircraft",
      "text": "In 2018, it was announced that two new Boeing 747-8 aircraft would be modified to serve as the next generation of Air Force One, replacing the aging VC-25A models.",
      "date": "2018"
    }
  ]
}

