    },
    {
      "headline": "Publication of 'On the Origin of Species'",
      "text": "On November 24, 1859, Charles Darwin published 'On the Origin of Species', which introduced the scientific theory that populations evolve over generations through a process of natural selection.",
      "date": "1859-11-24"
    },
    {
      "headline": "Gregor Mendel's Experiments",
      "text": "Between 1856 and 1863, Gregor Mendel conducted experiments on pea plants, establishing many of the rules of heredity, now referred to as the laws of Mendelian inheritance.",
      "date": "1856"
    },
    {
      "headline": "Rediscovery of Mendel's Work",
      "text": "In 1900, Mendel's work was rediscovered by Hugo de Vries, Carl Correns, and Erich von Tschermak, leading to the foundation of the modern synthesis of evolutionary biology.",
      "date": "1900"
    },
    {
      "headline": "Modern Synthesis of Evolutionary Biology",
      "text": "In the 1930s and 1940s, the modern synthesis of evolutionary biology was developed, integrating Darwin's theory of evolution by natural selection with Mendelian genetics.",
      "date": "1930"
    },
    {
      "headline": "Discovery of DNA Structure",
      "text": "In 1953, James Watson and Francis Crick discovered the double helix structure of DNA, providing a molecular basis for inheritance and evolution.",
      "date": "1953"
    },
    {
      "headline": "Human Genome Project Completion",
      "text": "In 2003, the Human Genome Project was completed, mapping the entire human genome and providing insights into human evolution and genetic variation.",
      "date": "2003"
    }
  ]
}

