    {
      "headline": "Hubble Space Telescope Launch",
      "text": "The Hubble Space Telescope was launched into low Earth orbit on April 24, 1990, aboard the Space Shuttle Discovery (STS-31).",
      "date": "1990-04-24"
    },
    {
      "headline": "First Servicing Mission (STS-61)",
      "text": "The first servicing mission to the Hubble Space Telescope took place from December 2 to December 13, 1993. This mission corrected the telescope's flawed optics and upgraded its instruments.",
      "date": "1993-12-02"
    },
    {
      "headline": "Second Servicing Mission (STS-82)",
      "text": "The second servicing mission occurred from February 11 to February 21, 1997. It replaced and upgraded several instruments, including the installation of the Near Infrared Camera and Multi-Object Spectrometer (NICMOS).",
      "date": "1997-02-11"
    },
    {
      "headline": "Third Servicing Mission (STS-103)",
      "text": "The third servicing mission, originally planned as two separate missions, was combined into one and took place from December 19 to December 27, 1999. It involved replacing the gyroscopes and other critical components.",
      "date": "1999-12-19"
    },
    {
      "headline": "Fourth Servicing Mission (STS-109)",
      "text": "The fourth servicing mission occurred from March 1 to March 12, 2002. It included the installation of the Advanced Camera for Surveys (ACS) and other upgrades.",
      "date": "2002-03-01"
    },
    {
      "headline": "Fifth and Final Servicing Mission (STS-125)",
      "text": "The fifth and final servicing mission took place from May 11 to May 24, 2009. It involved significant upgrades, including the installation of the Wide Field Camera 3 (WFC3) and the Cosmic Origins Spectrograph (COS).",
      "date": "2009-05-11"
    },
    {
      "headline": "30th Anniversary",
      "text": "On April 24, 2020, the Hubble Space Telescope celebrated its 30th anniversary in orbit, continuing to provide valuable data and images to the scientific community.",
      "date": "2020-04-24"
    }
  ]
}

