      "headline": "Birth of Henry Lee Lucas",
      "text": "Henry Lee Lucas was born on August 23, 1936, in Blacksburg, Virginia, USA.",
      "date": "1936-08-23"
    },
    {
      "headline": "Murder of Lucas's Mother",
      "text": "On January 11, 1960, Henry Lee Lucas murdered his mother, Viola Lucas, during an argument. He was subsequently convicted of second-degree murder.",
      "date": "1960-01-11"
    },
    {
      "headline": "Release from Prison",
      "text": "Lucas was released from prison in 1970 after serving 10 years for the murder of his mother.",
      "date": "1970"
    },
    {
      "headline": "Murder of Becky Powell and Kate Rich",
      "text": "In 1983, Henry Lee Lucas was convicted of murdering Becky Powell, his teenage companion, and Kate Rich, an elderly woman.",
      "date": "1983"
    },
    {
      "headline": "Confessions to Multiple Murders",
      "text": "While incarcerated in 1983, Lucas began confessing to hundreds of murders, claiming responsibility for approximately 600 killings. These confessions led to the closure of many unsolved cases.",
      "date": "1983"
    },
    {
      "headline": "Conviction for Eleven Murders",
      "text": "Henry Lee Lucas was convicted of murdering eleven people, although many of these convictions were later questioned due to the dubious nature of his confessions.",
      "date": "1984"
    },
    {
      "headline": "Death Sentence for 'Orange Socks' Murder",
      "text": "Lucas was condemned to death for the murder of an unidentified woman, known as 'Orange Socks', who was later identified as Debra Jackson. This was the only case for which he received a death sentence.",
      "date": "1984"
    },
    {
      "headline": "Commutation of Death Sentence",
      "text": "In 1998, then-Governor George W. Bush commuted Lucas's death sentence to life imprisonment due to doubts about his guilt in the 'Orange Socks' case.",
      "date": "1998"
    },
    {
      "headline": "Death of Henry Lee Lucas",
      "text": "Henry Lee Lucas died of heart failure on March 12, 2001, in a Texas prison.",
      "date": "2001-03-12"
    }
  ]
}

