{
  "timeline": [
    {
      "headline": "Beginning of the Pleistocene Epoch",
      "text": "The Pleistocene Epoch began approximately 2.58 million years ago. It is characterized by the Earth's most recent period of repeated glaciations.",
      "date": "-2580000"
    },
    {
      "headline": "First Major Glaciation",
      "text": "Around 2.4 million years ago, the first major glaciation of the Pleistocene occurred, marking significant climatic changes.",
      "date": "-2400000"
    },
    {
      "headline": "Homo habilis Emergence",
      "text": "Approximately 2.1 million years ago, Homo habilis, one of the earliest members of the genus Homo, appeared during the Pleistocene.",
      "date": "-2100000"
    },
    {
      "headline": "Homo erectus Emergence",
      "text": "Around 1.9 million years ago, Homo erectus emerged, known for its use of more advanced stone tools.",
      "date": "-1900000"
    },
    {
      "headline": "Oldowan Tool Industry",
      "text": "The Oldowan tool industry, characterized by simple stone tools, was prevalent around 2.6 to 1.7 million years ago.",
      "date": "-2600000"
    },
    {
      "headline": "Homo heidelbergensis Emergence",
      "text": "Around 600,000 years ago, Homo heidelbergensis appeared, considered a common ancestor of both Neanderthals and modern humans.",
      "date": "-600000"
    },
    {
      "headline": "Neanderthals in Europe",
      "text": "Neanderthals began to inhabit Europe around 400,000 years ago, adapting to the cold climate of the Pleistocene.",
      "date": "-400000"
    },
    {
      "headline": "Last Glacial Maximum",
      "text": "Approximately 26,500 years ago, the Last Glacial Maximum occurred, marking the peak of the last glacial period.",
      "date": "-26500"
    },
    {
      "headline": "End of the Pleistocene Epoch",
      "text": "The Pleistocene Epoch ended around 11,700 years ago, coinciding with the end of the last glacial period and the beginning of the Holocene Epoch.",
      "date": "-11700"
    }
  ]
}

