{
  "timeline": [
    {
      "headline": "Invasion of Portugal",
      "text": "The Peninsular War began with the invasion of Portugal by French forces under General Junot in November 1807.",
      "date": "1807-11"
    },
    {
      "headline": "Treaty of Fontainebleau",
      "text": "The Treaty of Fontainebleau was signed in October 1807, allowing French troops to cross Spain to invade Portugal.",
      "date": "1807-10"
    },
    {
      "headline": "Spanish Revolt",
      "text": "In May 1808, a popular revolt against the French occupation began in Madrid, marking the start of the Spanish War of Independence.",
      "date": "1808-05"
    },
    {
      "headline": "Battle of Bailén",
      "text": "The Battle of Bailén took place in July 1808, where Spanish forces achieved a significant victory against the French.",
      "date": "1808-07"
    },
    {
      "headline": "British Intervention",
      "text": "In August 1808, British forces under Sir Arthur Wellesley landed in Portugal to support the fight against the French.",
      "date": "1808-08"
    },
    {
      "headline": "Convention of Cintra",
      "text": "The Convention of Cintra was signed in August 1808, allowing French troops to evacuate Portugal.",
      "date": "1808-08"
    },
    {
      "headline": "Battle of Corunna",
      "text": "The Battle of Corunna occurred in January 1809, resulting in a tactical British victory but the death of General Sir John Moore.",
      "date": "1809-01"
    },
    {
      "headline": "Second French Invasion of Portugal",
      "text": "In 1809, Marshal Soult led a second French invasion of Portugal, capturing Porto in March.",
      "date": "1809-03"
    },
    {
      "headline": "Battle of Talavera",
      "text": "The Battle of Talavera was fought in July 1809, where British and Spanish forces defeated the French.",
      "date": "1809-07"
    },
    {
      "headline": "Lines of Torres Vedras",
      "text": "By October 1810, the Lines of Torres Vedras were completed, fortifying the defense of Lisbon against French forces.",
