{
  "timeline": [
    {
      "headline": "Formation of Awami League",
      "text": "The Awami League was founded on June 23, 1949, in Dhaka, East Bengal (now Bangladesh), as the Awami Muslim League. It was established as a political party to represent the interests of the Bengali-speaking population of East Bengal.",
      "date": "1949-06-23"
    },
    {
      "headline": "Renaming to Awami League",
      "text": "In 1955, the party dropped the word 'Muslim' from its name and became the Awami League, reflecting its secular stance and appeal to all Bengalis, regardless of religion.",
      "date": "1955"
    },
    {
      "headline": "Victory in 1954 Elections",
      "text": "The Awami League, as part of the United Front, won a landslide victory in the 1954 East Bengal Legislative Assembly elections, securing 223 out of 237 Muslim seats.",
      "date": "1954"
    },
    {
      "headline": "Six-Point Movement",
      "text": "In 1966, Sheikh Mujibur Rahman, the leader of the Awami League, announced the Six-Point Movement, demanding greater autonomy for East Pakistan. This became a pivotal moment in the struggle for Bangladesh's independence.",
      "date": "1966"
    },
    {
      "headline": "1970 General Elections",
      "text": "The Awami League won a decisive victory in the 1970 general elections in Pakistan, securing 167 out of 169 seats allocated to East Pakistan in the National Assembly, which set the stage for the independence movement.",
      "date": "1970"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On March 26, 1971, following the refusal of the Pakistani government to transfer power, the Awami League declared the independence of Bangladesh, leading to the Bangladesh Liberation War.",
      "date": "1971-03-26"
    },
    {
      "headline": "Independence of Bangladesh",
      "text": "After a nine-month-long war, Bangladesh achieved independence on December 16, 1971, with the Awami League playing a crucial role in the liberation movement.",
      "date": "1971-12-16"
    },
    {
      "headline": "Assassination of Sheikh Mujibur Rahman",
      "text": "On August 15, 1975, Sheikh Mujibur Rahman, the founding leader of the Awami League and the first President of Bangladesh, was assassinated in a military coup.",
      "date": "1975-08-15"
    },
    {
      "headline": "Return to Power",
      "text": "The Awami League returned to power in 1996 after winning the general elections, with Sheikh Hasina, the daughter of Sheikh Mujibur Rahman, becoming the Prime Minister of Bangladesh.",
      "date": "1996"
    },
    {
      "headline": "Victory in 2008 Elections",
      "text": "The Awami League won a landslide victory in the 2008 general elections, securing 230 out of 300 seats in the National Parliament, marking a significant political comeback.",
      "date": "2008"
    },
    {
      "headline": "2014 General Elections",
      "text": "The Awami League won the 2014 general elections amidst controversy and a boycott by the main opposition party, the Bangladesh Nationalist Party.",
      "date": "2014"
    },
    {
      "headline": "2018 General Elections",
      "text": "The Awami League won the 2018 general elections, securing 288 out of 300 seats, ensuring another term for Sheikh Hasina as Prime Minister.",
      "date": "2018"
    }
  ]
}

