{
  "timeline": [
    {
      "headline": "Divergence from Ancestor of Living Cats",
      "text": "Smilodon diverged from the ancestor of living cats around 20 million years ago.",
      "date": "-20000000"
    },
    {
      "headline": "Evolution of Smilodon gracilis",
      "text": "Smilodon gracilis evolved from the genus Megantereon. This species is considered the earliest of the Smilodon genus.",
      "date": "-2500000"
    },
    {
      "headline": "Existence of Smilodon in the Americas",
      "text": "Smilodon lived in the Americas during the Pleistocene epoch, which lasted from about 2.5 million to 11,700 years ago.",
      "date": "-2500000"
    },
    {
      "headline": "Naming of the Genus Smilodon",
      "text": "The genus Smilodon was named in 1842 based on fossils found in Brazil. The name means 'scalpel' or 'two-edged knife' combined with 'tooth'.",
      "date": "1842"
    },
    {
      "headline": "Discovery of Smilodon Fossils at La Brea Tar Pits",
      "text": "Hundreds of Smilodon fossils were discovered at the La Brea Tar Pits in Los Angeles, providing the largest collection of Smilodon specimens.",
      "date": "Late 19th to early 20th century"
    },
    {
      "headline": "Recognition of Three Smilodon Species",
      "text": "Today, three species of Smilodon are recognized: S. gracilis, S. fatalis, and S. populator. S. fatalis and S. populator are believed to have descended from S. gracilis.",
      "date": "Modern classification"
    }
  ]
}

