    {
      "headline": "Origin of the Black Swan Metaphor",
      "text": "The term 'black swan' originated from a Latin expression that presumed black swans did not exist. This metaphor was used to describe something impossible or non-existent.",
      "date": "-01697"
    },
    {
      "headline": "Discovery of Black Swans",
      "text": "In 1697, Dutch mariners discovered black swans in Australia, challenging the previous belief that all swans were white. This discovery led to the reinterpretation of the term 'black swan' to mean an unforeseen and consequential event.",
      "date": "1697"
    },
    {
      "headline": "Development of Black Swan Theory",
      "text": "The black swan theory was developed by Nassim Nicholas Taleb, who used the metaphor to describe events that come as a surprise, have a major effect, and are often rationalized with hindsight.",
      "date": "2007"
    },
    {
      "headline": "Publication of 'The Black Swan'",
      "text": "In 2007, Nassim Nicholas Taleb published 'The Black Swan: The Impact of the Highly Improbable', which explores the concept of black swan events and their impact on the world.",
      "date": "2007"
    }
  ]
}

