      "headline": "Austronesian Expansion Begins",
      "text": "Around 3000 BCE, the Austronesian peoples began their expansion from Taiwan into the Philippines, marking the start of their widespread dispersal across the Pacific and Indian Oceans.",
      "date": "-3000"
    },
    {
      "headline": "Settlement of the Philippines",
      "text": "By around 2200 BCE, Austronesian peoples had settled in the Philippines, establishing the first of many communities in the region.",
      "date": "-2200"
    },
    {
      "headline": "Expansion into Maritime Southeast Asia",
      "text": "Between 2000 BCE and 1500 BCE, Austronesian peoples expanded further into Maritime Southeast Asia, reaching areas such as Borneo, Sulawesi, and the Maluku Islands.",
      "date": "-2000"
    },
    {
      "headline": "Settlement of Madagascar",
      "text": "By around 500 CE, Austronesian peoples had reached and settled in Madagascar, introducing their language and culture to the island.",
      "date": "0500"
    },
    {
      "headline": "Polynesian Expansion",
      "text": "Between 1000 CE and 1300 CE, Polynesian Austronesians expanded across the Pacific, reaching islands such as Hawaii, Easter Island, and New Zealand.",
      "date": "1000"
    },
    {
      "headline": "Development of Austronesian Languages",
      "text": "Over millennia, Austronesian peoples developed a diverse range of languages, now known as the Austronesian language family, which includes over 1,200 languages spoken by millions across the Pacific and Indian Oceans.",
      "date": "Present"
    }
  ]
}

