    },
    {
      "headline": "Lavrentiy Beria as Head of NKVD",
      "text": "Lavrentiy Beria became the head of the NKVD in 1938, following the dismissal of Nikolai Yezhov. Beria continued the NKVD's operations during World War II.",
      "date": "1938"
