{
  "timeline": [
    {
      "headline": "Emergence of Electronic Dance Music",
      "text": "Electronic dance music (EDM) began to emerge in the late 1970s and early 1980s, with the development of electronic music genres like disco, synth-pop, and electro.",
      "date": "1980"
    },
    {
      "headline": "Birth of House Music",
      "text": "House music, one of the earliest forms of EDM, originated in Chicago in the early 1980s. It was characterized by repetitive 4/4 beats and synthesized basslines.",
      "date": "1980"
    },
    {
      "headline": "Techno Music Develops",
      "text": "Techno music developed in Detroit in the mid-1980s, influenced by electronic music pioneers like Kraftwerk and the Belleville Three.",
