      "headline": "Founding of Dubrovnik",
      "text": "Dubrovnik, historically known as Ragusa, was founded in the 7th century by refugees from Epidaurum (modern-day Cavtat).",
      "date": "-0600"
    },
    {
      "headline": "Establishment of the Republic of Ragusa",
      "text": "In 1358, Dubrovnik became a free state under the Treaty of Zadar, establishing the Republic of Ragusa.",
      "date": "1358"
    },
    {
      "headline": "Golden Age of the Republic of Ragusa",
      "text": "The 15th and 16th centuries marked the Golden Age of the Republic of Ragusa, during which it became a significant maritime power.",
      "date": "1400"
    },
    {
      "headline": "Earthquake of 1667",
      "text": "On April 6, 1667, a devastating earthquake struck Dubrovnik, killing over 5,000 people and destroying much of the city.",
      "date": "1667-04-06"
    },
    {
      "headline": "End of the Republic of Ragusa",
      "text": "In 1808, the Republic of Ragusa was abolished by Napoleon's forces, and Dubrovnik was annexed into the Napoleonic Kingdom of Italy.",
      "date": "1808"
    },
    {
      "headline": "Inclusion in the Austrian Empire",
      "text": "After the fall of Napoleon, Dubrovnik became part of the Austrian Empire in 1815 following the Congress of Vienna.",
      "date": "1815"
    },
    {
      "headline": "Inclusion in Yugoslavia",
      "text": "Following World War I, Dubrovnik became part of the Kingdom of Serbs, Croats, and Slovenes, later known as Yugoslavia, in 1918.",
      "date": "1918"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1979, the city of Dubrovnik was added to the UNESCO list of World Heritage Sites in recognition of its outstanding medieval architecture and fortified old town.",
      "date": "1979"
    },
    {
      "headline": "Siege of Dubrovnik",
      "text": "During the Croatian War of Independence, Dubrovnik was besieged by the Yugoslav People's Army from October 1991 to May 1992.",
      "date": "1991-10"
    },
    {
      "headline": "Restoration and Tourism Boom",
      "text": "Post-war restoration efforts and the city's UNESCO status have led to a significant increase in tourism, making Dubrovnik one of the most prominent tourist destinations in the Mediterranean.",
      "date": "2000"
    }
  ]
}

