      "headline": "Birth of Abdul Hamid II",
      "text": "Abdul Hamid II was born on September 21, 1842, in Istanbul, Ottoman Empire.",
      "date": "1842-09-21"
    },
    {
      "headline": "Accession to the Throne",
      "text": "Abdul Hamid II became the 34th Sultan of the Ottoman Empire on August 31, 1876, following the deposition of his brother Murad V.",
      "date": "1876-08-31"
    },
    {
      "headline": "First Constitutional Era",
      "text": "On December 23, 1876, Abdul Hamid II promulgated the first Ottoman constitution, marking the beginning of the First Constitutional Era.",
      "date": "1876-12-23"
    },
    {
      "headline": "Russo-Turkish War (1877–1878)",
      "text": "The Ottoman Empire, under Abdul Hamid II, engaged in an unsuccessful war with the Russian Empire from 1877 to 1878, resulting in significant territorial losses.",
      "date": "1877"
    },
    {
      "headline": "Suspension of the Constitution",
      "text": "In 1878, Abdul Hamid II suspended the Ottoman constitution and dissolved the parliament, marking the end of the First Constitutional Era.",
      "date": "1878"
    },
    {
      "headline": "Loss of Egypt and Cyprus",
      "text": "During Abdul Hamid II's reign, the Ottoman Empire lost control of Egypt and Cyprus, with Egypt becoming a British protectorate in 1882 and Cyprus being administered by Britain from 1878.",
      "date": "1882"
    },
    {
      "headline": "Greco-Turkish War (1897)",
      "text": "In 1897, Abdul Hamid II led the Ottoman Empire to a military victory against the Kingdom of Greece, although the gains were limited by European intervention.",
      "date": "1897"
    },
    {
      "headline": "Young Turk Revolution",
      "text": "The Young Turk Revolution in 1908 forced Abdul Hamid II to restore the Ottoman constitution and reconvene the parliament, marking the start of the Second Constitutional Era.",
      "date": "1908"
    },
    {
      "headline": "Deposition and Exile",
      "text": "Abdul Hamid II was deposed on April 27, 1909, following a countercoup and was subsequently exiled to Thessaloniki.",
      "date": "1909-04-27"
    },
    {
      "headline": "Death of Abdul Hamid II",
      "text": "Abdul Hamid II died on February 10, 1918, in Istanbul, Ottoman Empire.",
      "date": "1918-02-10"
    }
  ]
}

