{
  "timeline": [
    {
      "headline": "John Calvin's Birth",
      "text": "John Calvin, the principal figure in the development of the system of Christian theology later called Calvinism, was born on July 10, 1509, in Noyon, France.",
      "date": "1509-07-10"
    },
    {
      "headline": "Publication of 'Institutes of the Christian Religion'",
      "text": "In 1536, John Calvin published the first edition of 'Institutes of the Christian Religion', a seminal work in Protestant theology that laid the foundation for Calvinist thought.",
      "date": "1536"
    },
    {
      "headline": "Calvin's Leadership in Geneva",
      "text": "In 1541, John Calvin was invited to Geneva, Switzerland, where he became a leading figure in the city's religious and political life, establishing a theocratic government.",
      "date": "1541"
    },
    {
      "headline": "The Consensus Tigurinus",
      "text": "In 1549, the Consensus Tigurinus was agreed upon, uniting the Reformed churches of Zurich and Geneva and marking a significant step in the development of Reformed theology.",
      "date": "1549"
    },
    {
      "headline": "Calvin's Death",
      "text": "John Calvin died on May 27, 1564, in Geneva, Switzerland, leaving a lasting legacy on Protestant theology and church governance.",
      "date": "1564-05-27"
    },
    {
      "headline": "Synod of Dort",
      "text": "The Synod of Dort was held from 1618 to 1619 in the Netherlands, where the Five Points of Calvinism were articulated in response to the Arminian controversy.",
      "date": "1618"
    },
    {
      "headline": "Westminster Assembly",
      "text": "The Westminster Assembly, convened from 1643 to 1653, produced the Westminster Confession of Faith, a key document in Reformed theology, particularly for Presbyterian churches.",
      "date": "1643"
    },
    {
      "headline": "Adoption of the Westminster Confession",
      "text": "In 1647, the Church of Scotland adopted the Westminster Confession of Faith, solidifying its influence in Presbyterianism.",
      "date": "1647"
    },
    {
      "headline": "Great Awakening",
      "text": "During the 18th century, the Great Awakening, a series of religious revivals, spread Calvinist theology across the American colonies, influencing various Protestant denominations.",
      "date": "1730"
    },
    {
      "headline": "Formation of the World Alliance of Reformed Churches",
      "text": "In 1875, the World Alliance of Reformed Churches was formed, uniting Reformed churches worldwide and promoting Calvinist theology.",
      "date": "1875"
    }
  ]
}

