{
  "timeline": [
    {
      "headline": "Pythagoras Proposes Spherical Earth",
      "text": "Around 500 BCE, Pythagoras is believed to have been one of the first to propose that the Earth is spherical, based on observations of the Moon and stars.",
      "date": "-0500"
    },
    {
      "headline": "Plato and Aristotle Support Spherical Earth",
      "text": "In the 4th century BCE, Plato and Aristotle provided philosophical and observational arguments for a spherical Earth. Aristotle's observations of the Earth's shadow on the Moon during a lunar eclipse were particularly influential.",
      "date": "-0400"
    },
    {
      "headline": "Eratosthenes Measures Earth's Circumference",
      "text": "Around 240 BCE, Eratosthenes calculated the Earth's circumference with remarkable accuracy by measuring the angle of the Sun's rays in two different locations in Egypt.",
      "date": "-0240"
    },
    {
      "headline": "Ptolemy's Geocentric Model",
      "text": "In the 2nd century CE, Claudius Ptolemy developed a geocentric model of the universe that included a spherical Earth, which became widely accepted in the Western world.",
      "date": "0100"
    },
    {
      "headline": "Islamic Golden Age Advances",
      "text": "During the Islamic Golden Age (8th to 14th centuries), Muslim scholars such as Al-Farghani and Al-Biruni made significant contributions to the understanding of Earth's shape and size, further supporting the spherical Earth model.",
      "date": "0800"
    },
    {
      "headline": "Copernican Revolution",
      "text": "In 1543, Nicolaus Copernicus published 'De revolutionibus orbium coelestium', which proposed a heliocentric model of the universe with a spherical Earth, challenging the long-standing Ptolemaic system.",
      "date": "1543"
    },
    {
      "headline": "Newton's Principia",
      "text": "In 1687, Isaac Newton published 'Philosophiæ Naturalis Principia Mathematica', where he described the Earth as an oblate spheroid due to its rotation, refining the concept of a spherical Earth.",
      "date": "1687"
    },
    {
      "headline": "Confirmation of Earth's Oblate Spheroid Shape",
      "text": "In the 18th century, expeditions led by the French Academy of Sciences confirmed that the Earth is an oblate spheroid, with measurements taken in the polar and equatorial regions.",
      "date": "1735"
    }
  ]
}

