{
  "timeline": [
    {
      "headline": "Thalidomide First Marketed",
      "text": "Thalidomide was first marketed in 1957 by the German pharmaceutical company Chemie Grünenthal as a non-barbiturate sedative and was later found to be effective in treating morning sickness in pregnant women.",
      "date": "1957"
    },
    {
      "headline": "Thalidomide Prescribed to Pregnant Women",
      "text": "In the late 1950s, thalidomide was widely prescribed to pregnant women in 46 countries to alleviate morning sickness, leading to unforeseen consequences.",
      "date": "1950s"
    },
    {
      "headline": "First Reports of Birth Defects",
      "text": "In 1961, reports began to emerge linking thalidomide to severe birth defects, including phocomelia, where children were born with shortened or absent limbs.",
      "date": "1961"
    },
    {
      "headline": "Thalidomide Withdrawn from the Market",
      "text": "By late 1961, thalidomide was withdrawn from the market in Germany and the UK after the connection to birth defects was confirmed.",
      "date": "1961"
    },
    {
      "headline": "Thalidomide Scandal Publicized",
      "text": "The thalidomide scandal became widely publicized in 1962, highlighting the drug's devastating effects and leading to increased regulation of pharmaceuticals.",
      "date": "1962"
    },
    {
      "headline": "Legal Actions and Compensation",
      "text": "Throughout the 1960s and 1970s, legal actions were taken against Chemie Grünenthal and other companies involved, resulting in compensation for victims and their families.",
      "date": "1960s-1970s"
    },
    {
      "headline": "Thalidomide Approved for New Uses",
      "text": "In the late 1990s, thalidomide was approved for new uses, such as treating leprosy and multiple myeloma, under strict regulations to prevent birth defects.",
      "date": "1990s"
    }
  ]
}

