{
  "timeline": [
    {
      "headline": "Birth of Martin Niemöller",
      "text": "Martin Niemöller was born on January 14, 1892, in Lippstadt, Germany.",
      "date": "1892-01-14"
    },
    {
      "headline": "Niemöller's Early Career",
      "text": "Before becoming a pastor, Niemöller served as a U-boat commander during World War I.",
      "date": "1914"
    },
    {
      "headline": "Ordination as a Pastor",
      "text": "Martin Niemöller was ordained as a Lutheran pastor in 1924.",
      "date": "1924"
    },
    {
      "headline": "Niemöller's Opposition to Nazi Regime",
      "text": "Niemöller became an outspoken critic of Adolf Hitler's regime, particularly opposing the Nazis' interference in church affairs.",
      "date": "1933"
    },
    {
      "headline": "Arrest and Imprisonment",
      "text": "Niemöller was arrested by the Gestapo in 1937 and spent the years until 1945 in Sachsenhausen and Dachau concentration camps.",
      "date": "1937"
    },
    {
      "headline": "Release from Concentration Camp",
      "text": "Niemöller was liberated from Dachau concentration camp in 1945 by Allied forces.",
      "date": "1945"
    },
    {
      "headline": "Publication of 'First they came...'",
      "text": "In 1946, Niemöller wrote the prose 'First they came...', reflecting on the passive complicity of German intellectuals during the Nazi regime.",
      "date": "1946"
    },
    {
      "headline": "Niemöller's Post-War Activities",
      "text": "After the war, Niemöller became a prominent figure in the peace movement and served as President of the World Council of Churches from 1961 to 1968.",
      "date": "1961"
    },
    {
      "headline": "Death of Martin Niemöller",
      "text": "Martin Niemöller passed away on March 6, 1984, in Wiesbaden, Germany.",
      "date": "1984-03-06"
    }
  ]
}

