{
  "timeline": [
    {
      "headline": "Construction of the Western Wall",
      "text": "The Western Wall was constructed as part of the expansion of the Second Jewish Temple by Herod the Great. This expansion took place around 19 BCE.",
      "date": "-0019"
    },
    {
      "headline": "Destruction of the Second Temple",
      "text": "In 70 CE, the Second Temple was destroyed by the Roman Empire during the Siege of Jerusalem. The Western Wall was one of the few remaining structures.",
      "date": "0070"
    },
    {
      "headline": "Muslim Conquest of Jerusalem",
      "text": "In 638 CE, Jerusalem was conquered by the Muslim Caliphate under Caliph Umar. The Western Wall became part of the Islamic heritage as the Buraq Wall.",
      "date": "0638"
    },
    {
      "headline": "Ottoman Rule and the Western Wall",
      "text": "During the Ottoman period, which began in 1517, the Western Wall became a site of Jewish pilgrimage and prayer.",
      "date": "1517"
    },
    {
      "headline": "British Mandate and the Western Wall",
      "text": "Under the British Mandate from 1920 to 1948, the Western Wall was a focal point of Jewish religious life, but also a source of tension between Jews and Muslims.",
      "date": "1920"
    },
    {
      "headline": "Jordanian Control of the Western Wall",
      "text": "From 1948 to 1967, the Western Wall was under Jordanian control following the Arab-Israeli War. Jews were denied access to the Wall during this period.",
      "date": "1948"
    },
    {
      "headline": "Israeli Control of the Western Wall",
      "text": "In June 1967, during the Six-Day War, Israel captured East Jerusalem, including the Western Wall, allowing Jews to access the site freely for the first time in 19 years.",
      "date": "1967-06"
    },
    {
      "headline": "Excavations and Archaeological Discoveries",
      "text": "Since 1967, extensive archaeological excavations have been conducted around the Western Wall, uncovering significant historical artifacts and structures.",
      "date": "1967"
    }
  ]
}

