{
  "timeline": [
    {
      "headline": "First Mention of Wrocław",
      "text": "The city of Wrocław was first mentioned in the year 1000 when a bishopric was established there by Bolesław I the Brave, the Duke of Poland.",
      "date": "1000"
    },
    {
      "headline": "Wrocław Becomes Part of the Kingdom of Poland",
      "text": "In 1138, Wrocław became part of the Kingdom of Poland following the fragmentation of the Polish state.",
      "date": "1138"
    },
    {
      "headline": "Wrocław Receives City Rights",
      "text": "Wrocław was granted city rights in 1241, marking its development as a significant urban center.",
      "date": "1241"
    },
    {
      "headline": "Mongol Invasion",
      "text": "In 1241, Wrocław was attacked by the Mongols during the first Mongol invasion of Poland.",
      "date": "1241"
    },
    {
      "headline": "Wrocław Joins the Hanseatic League",
      "text": "In 1387, Wrocław became a member of the Hanseatic League, a commercial and defensive confederation of merchant guilds and market towns in Northwestern and Central Europe.",
      "date": "1387"
    },
    {
      "headline": "Wrocław Becomes Part of the Kingdom of Bohemia",
      "text": "In 1335, Wrocław became part of the Kingdom of Bohemia under the rule of King John of Bohemia.",
      "date": "1335"
    },
    {
      "headline": "Wrocław Under Habsburg Rule",
      "text": "In 1526, Wrocław came under the rule of the Habsburg Monarchy following the death of King Louis II of Hungary and Bohemia.",
      "date": "1526"
    },
    {
      "headline": "Prussian Annexation",
      "text": "In 1741, Wrocław was annexed by the Kingdom of Prussia during the First Silesian War.",
      "date": "1741"
    },
    {
      "headline": "Wrocław Becomes Part of the German Empire",
      "text": "In 1871, Wrocław became part of the newly formed German Empire.",
      "date": "1871"
    },
    {
      "headline": "World War II and Siege of Breslau",
      "text": "During World War II, Wrocław (then Breslau) was declared a fortress city and was besieged by the Soviet Red Army in 1945.",
      "date": "1945"
    },
    {
      "headline": "Wrocław Becomes Part of Poland",
      "text": "After World War II, in 1945, Wrocław was transferred to Poland as part of the Potsdam Agreement.",
      "date": "1945"
    },
    {
      "headline": "Wrocław's Population Growth",
      "text": "By 2023, Wrocław's population had grown to 674,132, making it the third largest city in Poland.",
      "date": "2023"
    }
  ]
}

