    {
      "headline": "First Military Coup",
      "text": "On January 15, 1966, a group of army officers led by Major Chukwuma Kaduna Nzeogwu executed Nigeria's first military coup, overthrowing the civilian government.",
      "date": "1966-01-15"
    },
    {
      "headline": "Counter-Coup",
      "text": "On July 29, 1966, a counter-coup was staged by Northern officers, leading to the assassination of Major General Johnson Aguiyi-Ironsi and the installation of Lieutenant Colonel Yakubu Gowon as head of state.",
      "date": "1966-07-29"
    },
    {
      "headline": "Anti-Igbo Pogroms",
      "text": "In September 1966, widespread anti-Igbo pogroms occurred in the Northern Region, resulting in the massacre of thousands of Igbos and prompting a mass exodus to the Eastern Region.",
      "date": "1966-09"
    },
    {
      "headline": "Declaration of Biafra",
      "text": "On May 30, 1967, Lieutenant Colonel Chukwuemeka Odumegwu Ojukwu declared the independence of the Republic of Biafra from Nigeria.",
      "date": "1967-05-30"
    },
    {
      "headline": "Start of the Nigerian Civil War",
      "text": "The Nigerian Civil War, also known as the Biafran War, officially began on July 6, 1967, when Nigerian federal troops advanced into Biafra.",
      "date": "1967-07-06"
    },
    {
      "headline": "Fall of Enugu",
      "text": "In October 1967, Nigerian forces captured Enugu, the capital of Biafra, marking a significant point in the war.",
      "date": "1967-10"
    },
    {
      "headline": "Biafran Humanitarian Crisis",
      "text": "By 1968, the humanitarian crisis in Biafra had escalated, with widespread famine and international attention on the plight of Biafran civilians.",
      "date": "1968"
    },
    {
      "headline": "End of the Nigerian Civil War",
      "text": "The Nigerian Civil War ended on January 15, 1970, when Biafran forces surrendered to the Nigerian government.",
      "date": "1970-01-15"
    }
  ]
}

