{
  "timeline": [
    {
      "headline": "Surrender of Bataan",
      "text": "On April 9, 1942, Major General Edward P. King Jr. surrendered approximately 75,000 Filipino and American troops on the Bataan Peninsula to the Japanese forces.",
      "date": "1942-04-09"
    },
    {
      "headline": "Start of the Bataan Death March",
      "text": "The Bataan Death March began on April 9, 1942, immediately following the surrender of Bataan. The prisoners were forced to march approximately 65 miles from Mariveles and Bagac to San Fernando.",
      "date": "1942-04-09"
    },
    {
      "headline": "March to San Fernando",
      "text": "The prisoners were marched in intense heat with little food or water. Many were subjected to harsh treatment and brutality by the Japanese guards. The march continued until April 15, 1942.",
      "date": "1942-04-15"
    },
    {
      "headline": "Arrival at San Fernando",
      "text": "By April 15, 1942, the surviving prisoners reached San Fernando, where they were loaded onto trains and transported to Capas.",
      "date": "1942-04-15"
    },
    {
      "headline": "Final March to Camp O'Donnell",
      "text": "From Capas, the prisoners were forced to march an additional 9 miles to Camp O'Donnell, where they arrived on April 20, 1942.",
      "date": "1942-04-20"
    },
    {
      "headline": "End of the Bataan Death March",
      "text": "The Bataan Death March officially ended on April 20, 1942, with the arrival of the prisoners at Camp O'Donnell. Thousands of prisoners died during the march due to starvation, dehydration, and abuse.",
      "date": "1942-04-20"
    }
  ]
}

