      "headline": "Birth of Edvard Munch",
      "text": "Edvard Munch was born on December 12, 1863, in Loten, Norway.",
      "date": "1863-12-12"
    },
    {
      "headline": "Death of Munch's Mother",
      "text": "Munch's mother died of tuberculosis in 1868, when he was only five years old.",
      "date": "1868"
    },
    {
      "headline": "Death of Munch's Sister",
      "text": "In 1877, Munch's older sister, Sophie, also died of tuberculosis.",
      "date": "1877"
    },
    {
      "headline": "Enrollment at the Royal School of Art and Design",
      "text": "In 1881, Munch enrolled at the Royal School of Art and Design in Kristiania (now Oslo).",
      "date": "1881"
    },
    {
      "headline": "First Solo Exhibition",
      "text": "Munch held his first solo exhibition in 1889 in Kristiania.",
      "date": "1889"
    },
    {
      "headline": "Death of Munch's Father",
      "text": "Munch's father died in 1889, which deeply affected him and influenced his work.",
      "date": "1889"
    },
    {
      "headline": "Creation of The Scream",
      "text": "In 1893, Munch created his iconic painting, The Scream, which became one of the most famous images in art history.",
      "date": "1893"
    },
    {
      "headline": "Exhibition in Berlin",
      "text": "Munch exhibited his work in Berlin in 1892, which led to a scandal and the exhibition being closed after a week.",
      "date": "1892"
    },
    {
      "headline": "Munch's Breakdown and Hospitalization",
      "text": "In 1908, Munch suffered a nervous breakdown and was hospitalized for eight months.",
      "date": "1908"
    },
    {
      "headline": "Return to Norway",
      "text": "After his recovery, Munch returned to Norway in 1909 and continued to work prolifically.",
      "date": "1909"
    },
    {
      "headline": "Death of Edvard Munch",
      "text": "Edvard Munch died on January 23, 1944, in Oslo, Norway.",
      "date": "1944-01-23"
    }
  ]
}

