    {
      "headline": "Visigoths Enter the Roman Empire",
      "text": "In 376, the Visigoths, likely including many descendants of the Thervingi, began moving into the Roman Empire.",
      "date": "0376"
    },
    {
      "headline": "Battle of Adrianople",
      "text": "On August 9, 378, the Visigoths played a major role in defeating the Romans at the Battle of Adrianople.",
      "date": "0378-08-09"
    },
    {
      "headline": "Alaric I Becomes King",
      "text": "Alaric I became the king of the Visigoths around 395, uniting them as a formidable force within the Roman Empire.",
      "date": "0395"
    },
    {
      "headline": "Visigoths Invade Italy",
      "text": "Under the leadership of Alaric I, the Visigoths invaded Italy in 401, marking the beginning of a series of conflicts with the Roman Empire.",
      "date": "0401"
    },
    {
      "headline": "Sack of Rome",
      "text": "In August 410, the Visigoths, led by Alaric I, famously sacked Rome, a significant event in the decline of the Western Roman Empire.",
      "date": "0410-08"
    },
    {
      "headline": "Visigoths Settle in Aquitaine",
      "text": "In 418, the Visigoths were settled in Aquitaine by the Roman Empire as foederati, or allied peoples.",
      "date": "0418"
    },
    {
      "headline": "Kingdom of Toulouse Established",
      "text": "The Visigoths established the Kingdom of Toulouse in 418, which became a significant power in Western Europe.",
      "date": "0418"
    },
    {
      "headline": "Battle of Vouillé",
      "text": "In 507, the Visigoths were defeated by the Franks at the Battle of Vouillé, leading to the loss of their territories in Gaul.",
      "date": "0507"
    },
    {
      "headline": "Visigothic Kingdom in Hispania",
      "text": "After their defeat in Gaul, the Visigoths focused on consolidating their power in Hispania, where they established a kingdom that lasted until the early 8th century.",
      "date": "0507"
    },
