    {
      "headline": "First Mention of Somnath Tirtha",
      "text": "The Somnath Tirtha is mentioned in ancient texts such as the Mahabharata and the Bhagavata Purana, indicating the religious significance of the site in early centuries.",
      "date": "-0500"
    },
    {
      "headline": "Construction of the First Temple",
      "text": "The first temple at the site is believed to have been built around the 9th century CE, although the exact date is unclear.",
      "date": "0900"
    },
    {
      "headline": "Destruction by Mahmud of Ghazni",
      "text": "In 1025, Mahmud of Ghazni attacked and destroyed the Somnath temple, looting its wealth.",
      "date": "1025"
    },
    {
      "headline": "Reconstruction by the Paramara King Bhoja",
      "text": "The temple was rebuilt by the Paramara King Bhoja of Malwa and the Solanki king Bhimadeva I of Anhilwara around 1026.",
      "date": "1026"
    },
    {
      "headline": "Destruction by Alauddin Khalji's Army",
      "text": "In 1299, the temple was again destroyed by the army of Alauddin Khalji, led by his general Ulugh Khan.",
      "date": "1299"
    },
    {
      "headline": "Reconstruction by Mahipala I",
      "text": "The temple was rebuilt by Mahipala I, the Chudasama king of Saurashtra, in the early 14th century.",
      "date": "1300"
    },
    {
      "headline": "Destruction by Muzaffar Shah I",
      "text": "In 1395, the temple was destroyed by Muzaffar Shah I, the Sultan of Gujarat.",
      "date": "1395"
    },
    {
      "headline": "Reconstruction by Mahmud Begada",
      "text": "The temple was rebuilt by Mahmud Begada, the Sultan of Gujarat, in the late 15th century.",
      "date": "1451"
    },
    {
      "headline": "Destruction by Aurangzeb",
      "text": "In 1665, the temple was destroyed by the Mughal emperor Aurangzeb.",
      "date": "1665"
    },
    {
      "headline": "Reconstruction in the 20th Century",
      "text": "The present temple was reconstructed in the Chaulukya style of Hindu temple architecture and completed in May 1951, under the orders of the then Home Minister of India, Vallabhbhai Patel.",
      "date": "1951-05"
    }
  ]
}

