    {
      "headline": "Indus Valley Civilization",
      "text": "The region that is now Punjab was part of the Indus Valley Civilization, one of the world's earliest urban cultures, which flourished around 2600 BCE.",
      "date": "-2600"
    },
    {
      "headline": "Achaemenid Empire",
      "text": "Punjab was part of the Achaemenid Empire around 518 BCE, under the rule of Darius the Great.",
      "date": "-0518"
    },
    {
      "headline": "Conquest by Alexander the Great",
      "text": "In 326 BCE, Alexander the Great invaded Punjab, defeating King Porus in the Battle of the Hydaspes.",
      "date": "-0326"
    },
    {
      "headline": "Maurya Empire",
      "text": "After Alexander's death, Punjab became part of the Maurya Empire around 322 BCE under Chandragupta Maurya.",
      "date": "-0322"
    },
    {
      "headline": "Gupta Empire",
      "text": "Punjab was part of the Gupta Empire during the 4th and 5th centuries CE, a period known for cultural and scientific advancements.",
      "date": "0400"
    },
    {
      "headline": "Arrival of Islam",
      "text": "Islam was introduced to Punjab in the 8th century CE by Arab traders and later by invasions.",
      "date": "0700"
    },
    {
      "headline": "Delhi Sultanate",
      "text": "Punjab became part of the Delhi Sultanate in the 13th century, marking the beginning of Muslim rule in the region.",
      "date": "1200"
    },
    {
      "headline": "Mughal Empire",
      "text": "In the early 16th century, Punjab was incorporated into the Mughal Empire under Babur's rule.",
      "date": "1526"
    },
    {
      "headline": "Sikh Empire",
      "text": "In the early 19th century, the Sikh Empire was established in Punjab under Maharaja Ranjit Singh.",
      "date": "1801"
    },
    {
      "headline": "British Rule",
      "text": "Punjab was annexed by the British Empire in 1849 after the Second Anglo-Sikh War.",
      "date": "1849"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, Punjab was divided between India and Pakistan during the partition of India, leading to significant demographic changes.",
      "date": "1947"
    },
    {
      "headline": "Formation of Punjab Province",
      "text": "Following the partition, the western part of Punjab became a province of Pakistan.",
      "date": "1947"
    }
  ]
}

